window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0055", [{"word":"individualistic","ipa_uk":"/ˌɪndɪˌvɪdʒuəˈlɪstɪk/","ipa_us":"/ˌɪndɪvɪdʒuəˈlɪstɪk/","definition_zh":"个人主义的；强调个体独立与个性的；我行我素的","definition_en":"favouring individual independence and personal choice over collective authority; also showing a distinctive personal style that resists group pressure","core_image":"整齐的队伍向前走，只有一个人拐向自己的小路","scene":"His individualistic streak made him reject the team's uniform schedule and design his own research plan. Colleagues found him difficult, yet the plan eventually won the prize.","sceneCN":"这里 individualistic 是「强调自立自主的」（第 2 个义项：行为上独立自主）；句意：他那种我行我素的性格使他拒绝团队统一的日程，自行设计了研究方案；同事们觉得他难相处，但方案最终获了奖。图中可辨识物件：队伍、独自的小路、研究笔记、奖杯。","pos":[{"tag":"adj.","zh":"个人主义的；强调个体独立的；我行我素的"}],"collocations":[{"phrase":"individualistic culture","zh":"个人主义文化"},{"phrase":"individualistic society","zh":"个人主义社会"},{"phrase":"individualistic approach","zh":"个人主义式的方法"},{"phrase":"highly individualistic","zh":"高度个人主义的"},{"phrase":"individualistic streak","zh":"我行我素的性格倾向"},{"phrase":"individualistic values","zh":"个人主义价值观"}],"forms":[{"label":"比较级","form":"more individualistic"},{"label":"最高级","form":"most individualistic"}],"derivatives":[{"word":"individualism","pos":"n.","zh":"个人主义"},{"word":"individualist","pos":"n.","zh":"个人主义者"},{"word":"individuality","pos":"n.","zh":"个性；独特性"},{"word":"individual","pos":"adj./n.","zh":"个人的；个体"},{"word":"individualize","pos":"v.","zh":"使个性化；分别处理"}],"senses":[{"no":"01","title":"Holding that the individual comes before the group","titleCN":"个人主义（学说）：个体先于群体","definition":"believing that individual independence and personal interests should take priority over collective authority","definitionCN":"认为个体的独立与个人利益应优先于集体权威的","example":"The party's individualistic philosophy opposed any plan that assigned people to collective farms.","exampleCN":"该党的个人主义理念反对任何把人分配到集体农场的计划。","why":"Latin individuus means 'not divisible': the individual is the atom that cannot be split. A doctrine that makes this atom the starting point of politics is literally individualistic, and -istic marks adherence to a doctrine.","whyCN":"拉丁 individuus 意为「不可分的」：个体是不可再分的原子。把这一原子当作政治出发点的学说，字面上就是 individualistic，而 -istic 标记对学说的归属。"},{"no":"02","title":"Acting independently rather than relying on the group","titleCN":"行为上自立自主","definition":"showing a habit of making one's own decisions and acting without depending on others","definitionCN":"表现出自行决定、不依赖他人而行动的习惯","example":"She had an individualistic working style and rarely asked for guidance.","exampleCN":"她的工作风格很自主，很少请求指导。","why":"If the individual is the indivisible unit, then individualistic conduct treats one's own judgment as the unit of decision and refuses to dissolve it into the group's judgment.","whyCN":"如果个体是不可分的单位，那么 individualistic 行为就把自己的判断当作决策单位，拒绝把它溶入群体的判断。"},{"no":"03","title":"Expressing a distinctive personal style","titleCN":"风格独特、不随大流","definition":"marked by a personal style or taste that deliberately avoids following the crowd","definitionCN":"带有刻意不随大流的个人风格或品味的","example":"His individualistic dress made him easy to spot at any conference.","exampleCN":"他独特的穿着使他在任何会议上都容易被认出。","why":"The image shifts from 'cannot be divided' to 'cannot be merged': a style that refuses to be absorbed into a common style is individualistic.","whyCN":"意象从「不可分」转为「不可融合」：拒绝被吸收进共同风格的风格，就是 individualistic。"},{"no":"04","title":"Stressing private initiative in economic life","titleCN":"经济上强调个人自主经营","definition":"favouring private initiative, personal ownership, and market choices over collective economic control","definitionCN":"主张私人创业、个人所有权和市场选择，而非集体经济控制的","example":"The country moved from an individualistic farm economy to large cooperatives within a decade.","exampleCN":"该国在十年内从个人自主的农业经济转向大型合作社。","why":"Economics took the indivisible individual as its basic unit of decision. An individualistic economy is one built from many such units rather than from one collective planner.","whyCN":"经济学把不可分的个体当作基本决策单位。个人主义经济就是由许多这样的单位、而非由一个集体计划者搭建起来的经济。"},{"no":"05","title":"Explaining social facts through individuals","titleCN":"方法论上以个体为解释单位","definition":"relating to a method that explains collective behaviour by tracing it back to individual choices","definitionCN":"与把集体行为追溯至个体选择来解释的方法相关的","example":"The sociologist took an individualistic view of voting patterns.","exampleCN":"这位社会学家以个体主义的视角看待投票模式。","why":"The same atom image becomes a research rule: if society is made of indivisible individuals, then collective facts should be explained from individual decisions upward.","whyCN":"同一个原子意象变成研究规则：如果社会由不可分的个体组成，那么集体事实就应自下而上地由个体决策来解释。"},{"no":"06","title":"Selfish or indifferent to others","titleCN":"自私的；不顾他人的","definition":"caring mainly about one's own advantage and showing little concern for other people","definitionCN":"主要关心自身利益、很少顾及他人的","example":"Voters rejected an individualistic housing policy that left poorer families to fend for themselves.","exampleCN":"选民否决了一项让较贫困家庭自行谋生的个人主义住房政策。","why":"When the boundary around the indivisible self hardens into a wall, independence becomes indifference. The negative sense grows from the same root image of a unit that will not merge.","whyCN":"当不可分的自我边界凝固成墙时，独立就变成冷漠。贬义正是从「不肯融合的单位」这一同一词根意象生长出来的。"},{"no":"07","title":"Giving personal rights priority over the state","titleCN":"政治上个人权利优先于国家","definition":"holding that personal rights and freedoms should limit what the state may require of a citizen","definitionCN":"主张个人权利与自由应限制国家对公民的要求的","example":"The constitution reflects an individualistic distrust of unchecked state power.","exampleCN":"这部宪法反映出一种个人主义的、对不受制约的国家权力的不信任。","why":"The state is a larger body made of citizens; individualistic politics insists that the smaller indivisible unit cannot be absorbed by the larger one. The prefix in- 'not' keeps the unit from being divided into the state.","whyCN":"国家是由公民组成的更大整体；个人主义政治坚持较小的不可分单位不能被较大整体吞并。否定前缀 in-「不」使这个单位不被分割进国家。"},{"no":"08","title":"A culture that rewards personal achievement","titleCN":"崇尚个人成就的文化特征","definition":"describing a culture in which personal achievement and self-expression are valued above group loyalty","definitionCN":"描述一种把个人成就与自我表达看得高于群体忠诚的文化","example":"Cross-cultural studies often contrast individualistic cultures with collectivist ones.","exampleCN":"跨文化研究常把个人主义文化与集体主义文化相对照。","why":"Cultures differ in what they treat as the unit of society. Where the indivisible individual is the unit, achievement is measured person by person, and that pattern is called individualistic.","whyCN":"不同文化对社会单位的设定不同。在把不可分个体当作单位的地方，成就按人逐一衡量，这种模式就被称为 individualistic。"},{"no":"09","title":"Playing alone instead of with the team","titleCN":"球场上单打独斗、缺乏配合","definition":"in sport, tending to keep the ball and act alone rather than combine with teammates","definitionCN":"在体育中倾向于控球单干、不与队友配合的","example":"The coach benched the talented but individualistic winger.","exampleCN":"教练把那位有天赋但爱单干的边锋放到替补席。","why":"A team is a whole made of parts; the individualistic player treats himself as a unit that need not merge with the passing pattern. The same 'will not merge' idea appears in a purely physical setting.","whyCN":"团队是由部分组成的整体；个人主义的球员把自己当作无需融入传球配合的单位。同一个「不肯融合」的观念出现在纯身体性的场景中。"}],"etymology":{"intro":{"en":"Individualistic is an English adjective built on individual, which goes back through medieval Latin individualis to Latin individuus 'not divisible'. The suffix -istic reached English through French -istique and Greek -istikos.","cn":"individualistic 是在 individual 上构成的英语形容词；individual 经中世纪拉丁 individualis 上溯到拉丁 individuus「不可分的」。后缀 -istic 经法语 -istique 和希腊 -istikos 进入英语。"},"items":[{"era":"LATIN VERB dividere","en":"dividere meant 'to divide, separate'. Its root is a verb of splitting, so anything built with it starts from the image of cutting a whole apart.","cn":"dividere 意为「分开、分离」。它的词根是一个表示劈开的动词，因此由它构成的词都从「把整体切开」这一画面出发。"},{"era":"LATIN individuus","en":"in- 'not' + dividere produced individuus 'not divisible, inseparable'. Latin used it of atoms and of persons: the smallest thing that cannot be cut further.","cn":"in-「不」+ dividere 构成 individuus「不可分的、不可分离的」。拉丁语用它指原子，也指人：不能再被切开的最小单位。"},{"era":"MEDIEVAL LATIN individualis","en":"Schoolmen formed individualis to mean 'single, belonging to one indivisible entity'. This is the direct source of English individual.","cn":"经院学者构成 individualis，意为「单一的、属于一个不可分实体的」。这是英语 individual 的直接来源。"},{"era":"ENGLISH individual","en":"English took the word in the 15th century as an adjective and by the 17th century used it as a noun for a single person. The idea of the unmergeable unit was now a social word.","cn":"英语在 15 世纪借入作形容词，到 17 世纪又用作名词指单个的人。不可融合的单位这一观念由此成为社会用语。"},{"era":"SUFFIX -istic","en":"Greek -istikos meant 'skilled in, pertaining to'; through French -istique it became English -istic, the adjective suffix attached to -ism nouns. It marks adherence to a doctrine or tendency.","cn":"希腊 -istikos 意为「精于某事的、与某事相关的」；经法语 -istique 变成英语 -istic，是加在 -ism 名词上的形容词后缀，标记对某种学说或倾向的归属。"},{"era":"MODERN USAGE","en":"Individualistic is generally dated to the 19th century, when sociology and economics began contrasting individualist with collectivist societies. The exact first coinage is uncertain, but the formation is transparent.","cn":"individualistic 一般认为是 19 世纪的产物，当时社会学和经济学开始把个人主义社会与集体主义社会对照。最早的确切用例已难考，但构词方式清楚。"}]},"similar":{"note":{"en":"Group one shares the Latin base individuus and differs only in suffix; group two is close in meaning but comes from other roots (Greek idios, Latin ego).","cn":"第一组共享拉丁词基 individuus，差别只在后缀；第二组意义相近，但分别来自其他词根（希腊 idios、拉丁 ego）。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"individual","ipa":"/ˌɪndɪˈvɪdʒuəl/","tag":"base adjective and noun","definition":"a single person or thing, or relating to one person; from Latin individuus 'not divisible'","definitionCN":"单个的人或物；关于一个人的；来自拉丁 individuus「不可分的」"},{"word":"individualism","ipa":"/ˌɪndɪˈvɪdʒuəlɪzəm/","tag":"-ism doctrine noun","definition":"the belief that individual independence and interests should come first; -ism names the system of ideas, not the adjective","definitionCN":"认为个体独立与利益应优先的信念；-ism 命名观念体系，并非形容词"},{"word":"individualist","ipa":"/ˌɪndɪˈvɪdʒuəlɪst/","tag":"-ist person noun","definition":"a person who holds or lives by individualism; -ist marks the person, while -istic marks the quality","definitionCN":"持有或践行个人主义的人；-ist 标记人，-istic 标记性质"},{"word":"individuality","ipa":"/ˌɪndɪˌvɪdʒuˈæləti/","tag":"-ity state noun","definition":"the set of qualities that make a person distinct; built on individual with -ity, and not tied to any doctrine","definitionCN":"使一个人与众不同的特质总和；由 individual 加 -ity 构成，与学说无关"}]},{"heading":"NEAR MEANING","entries":[{"word":"independent","ipa":"/ˌɪndɪˈpendənt/","tag":"self-governing","definition":"not relying on or controlled by others; close to the self-reliance sense but says nothing about a doctrine","definitionCN":"不依赖或不受他人控制的；接近自立义，但不涉及学说"},{"word":"self-reliant","ipa":"/ˌself rɪˈlaɪənt/","tag":"behavioural","definition":"able to act and decide without help from others; the behavioural core of the second sense","definitionCN":"能无需他人帮助而行动和决定的；第 2 个义项的行为核心"},{"word":"idiosyncratic","ipa":"/ˌɪdiəsɪŋˈkrætɪk/","tag":"peculiarly personal","definition":"oddly or strikingly personal in behaviour or style; from Greek idios 'one's own' + syn 'with' + krasis 'mixture', not from Latin individuus","definitionCN":"行为或风格上奇特而个人的；来自希腊 idios「自己的」+ syn「一起」+ krasis「混合」，并非拉丁 individuus"},{"word":"egoistic","ipa":"/ˌiːɡəʊˈɪstɪk/","tag":"self-centred","definition":"centred on one's own interests; from Latin ego 'I', a different root from individuus","definitionCN":"以自身利益为中心的；来自拉丁 ego「我」，与 individuus 词根不同"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'not' + dividere 'to divide': the individual is the unit that cannot be divided any further.","cn":"in-「不」+ dividere「分开」：个体就是不能再被分割的单位。"},{"en":"-istic is the adjective partner of -ism, as in realism → realistic; individualism is the doctrine, individualistic is its colour.","cn":"-istic 是 -ism 的形容词搭档，如 realism → realistic；individualism 是学说，individualistic 是它的色调。"},{"en":"individual is the base; individuality is what makes each individual distinct; individualistic says that this distinctness should guide conduct.","cn":"individual 是基础词；individuality 是使每个个体独特的东西；individualistic 则说这种独特性应当指导行为。"},{"en":"Think of a crowd moving as one mass: the individualistic person is the dot that refuses to be dissolved into the mass.","cn":"想象一群人以一个整体移动：个人主义的人就是那颗拒绝被溶入整体的点。"},{"en":"The pair individualistic / collectivist marks two ends of a scale in social description, and the suffixes -istic / -ist show the same pattern.","cn":"individualistic 与 collectivist 在社会描述中标出两个端点，后缀 -istic / -ist 呈现同一模式。"}],"abstract":[{"en":"Think of an atom: it is called 'indivisible' precisely because every attempt to cut it fails, and individualistic thought treats the person the same way.","cn":"想象一个原子：它被称为「不可分」，正因为每次切割都失败；个人主义思想也这样对待个人。"},{"en":"Picture a grid of dots: institutions draw lines between them, but the individualistic dot insists that the lines are optional.","cn":"想象一张点阵：制度在点与点之间画线，而个人主义的点坚持这些线是可选的。"},{"en":"Think of the suffix as a lens: -ism shows the belief, -ist shows the believer, and -istic shows the colour the belief gives to a life.","cn":"把后缀当作镜片：-ism 显示信念，-ist 显示信者，-istic 显示这信念给生活染上的颜色。"}]},"examples":[{"en":"American culture is often described as individualistic, stressing personal achievement over group loyalty.","cn":"美国文化常被描述为个人主义的，强调个人成就高于群体忠诚。"},{"en":"His individualistic approach to research produced a method that no one else could copy.","cn":"他那种个人主义的研究方式产生了一套别人无法复制的方法。"},{"en":"Critics say the reform is too individualistic and ignores collective bargaining.","cn":"批评者说这项改革过于个人主义，忽视了集体谈判。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（不）+ dividere（分开）→ individuus 不可分的 → individual 个体；-istic 表学说与倾向 → individualistic 以个体为中心、个人主义的","word":"individualistic"},"root":"拉丁 dividere「分开」加否定前缀 in- 构成 individuus「不可分的」，经中世纪拉丁 individualis 形成 individual，再加经法语 -istique / 希腊 -istikos 而来的 -istic；核心是「不可再分的个体」。","sensesIntro":{"en":"Nine senses radiate from one image: the individual is the smallest unit that cannot be divided, so a doctrine, a style, or a method that starts from that unit is individualistic.","cn":"九个义项从一个意象辐射开来：个体是不可再分的最小单位，因此以这个单位为出发点的学说、风格或方法都是 individualistic。"},"semanticMap":{"core":{"en":"CORE IMAGE: the smallest unit that cannot be cut any further, standing on its own.","cn":"核心意象：不能再被切开、独自站立的最小单位。"},"chain":["CUT A WHOLE APART","NOT DIVISIBLE","ONE SINGLE PERSON","THE SELF AS THE UNIT","A DOCTRINE OF THE SELF","STYLE AND SOCIETY"],"branches":[{"senses":"S01","en":"THE DOCTRINE: individual independence and interests are treated as the starting point of social life.","cn":"学说：把个体独立与利益当作社会生活的出发点。"},{"senses":"S02 · S06","en":"CONDUCT: the same unit becomes self-reliance when respected, and selfishness when it hardens into a wall.","cn":"行为：同一个单位被尊重时表现为自立，凝固成墙时表现为自私。"},{"senses":"S03 · S08 · S09","en":"STYLE AND GROUP FRICTION: personal taste, a culture of achievement, and the player who will not pass the ball.","cn":"风格与群体摩擦：个人品味、崇尚成就的文化，以及不肯传球的球员。"},{"senses":"S04 · S07","en":"ECONOMY AND POLITICS: systems built on the independent individual as the basic unit.","cn":"经济与政治：以独立个体为基本单位来搭建的制度。"},{"senses":"S05","en":"METHOD: collective facts are explained by tracing them back to individual decisions.","cn":"方法：把集体事实追溯回个体决策来解释。"}]},"affixes":{"intro":{"en":"Individualistic is individual plus the adjective suffix -istic, which descends from Greek -istikos through French -istique. The negative prefix in- and the verb dividere are fossilized inside the base.","cn":"individualistic 是 individual 加形容词后缀 -istic 构成，-istic 经法语 -istique 上溯希腊 -istikos。否定前缀 in- 与动词 dividere 已凝固在词基内部。"},"latinIntro":{"en":"Latin dividere 'to divide' built a family: divide, division, individual, indivisible, subdivide, dividend. The root appears as divid-, divis-, or vid-.","cn":"拉丁 dividere「分开」构成了一个词族：divide、division、individual、indivisible、subdivide、dividend。词根以 divid-、divis- 或 vid- 形式出现。"},"items":[{"word":"divide","structure":"dividere (to divide)","meaning":"to separate something into parts","meaningCN":"分开；划分（直接来自拉丁 dividere）","example":"Divide the class into four groups.","exampleCN":"把班级分成四组。"},{"word":"division","structure":"divid- + -ion","meaning":"the act of dividing; a part or department formed by dividing","meaningCN":"分开；部门（-ion 动作或结果名词）","example":"The division of labour raised output.","exampleCN":"分工提高了产量。"},{"word":"individual","structure":"in- (not) + dividere + -ual","meaning":"a single person or thing that cannot be split further","meaningCN":"个人；个体（in-「不」+ dividere「分开」+ -ual）","example":"Each individual has a different learning style.","exampleCN":"每个个体都有不同的学习方式。"},{"word":"individuality","structure":"individual + -ity","meaning":"the quality of being distinct as a person","meaningCN":"个性；独特性（-ity 状态名词）","example":"Her paintings show strong individuality.","exampleCN":"她的画作显示出强烈的个性。"},{"word":"individualism","structure":"individual + -ism","meaning":"the doctrine that individual interests come first","meaningCN":"个人主义（-ism 学说名词）","example":"Individualism is central to his political philosophy.","exampleCN":"个人主义是他政治哲学的核心。"},{"word":"individualist","structure":"individual + -ist","meaning":"a person who advocates or lives by individualism","meaningCN":"个人主义者（-ist 指人名词）","example":"He was an individualist who distrusted committees.","exampleCN":"他是个不信任委员会的个人主义者。"},{"word":"individualistic","structure":"individual + -istic (Greek -istikos, French -istique)","meaning":"marked by or favouring individualism","meaningCN":"个人主义的；突出个性的（-istic 形容词后缀，表学说倾向）","example":"The culture is highly individualistic.","exampleCN":"这种文化高度个人主义。"},{"word":"individualize","structure":"individual + -ize","meaning":"to make personal or suit a particular person","meaningCN":"使个性化；分别处理（-ize 动词后缀）","example":"Good teachers individualize their instruction.","exampleCN":"好老师会因材施教。"},{"word":"indivisible","structure":"in- (not) + divis- + -ible","meaning":"unable to be divided","meaningCN":"不可分的（in-「不」+ divis- + -ible 形容词后缀）","example":"The nation was declared indivisible.","exampleCN":"这个国家被宣告不可分割。"}],"latinEntries":[{"word":"dividere","structure":"dividere (to divide)","meaning":"to divide, separate, distribute","meaningCN":"分开；分离；分配"},{"word":"individuus","structure":"in- (not) + dividere","meaning":"not divisible, inseparable","meaningCN":"不可分的；不可分离的"},{"word":"individualis","structure":"individuus + -alis","meaning":"single, indivisible; belonging to an individual","meaningCN":"单一的；不可分的；属于个体的"}]}},{"word":"industrialization","ipa_uk":"/ɪnˌdʌstriəlaɪˈzeɪʃn/","ipa_us":"/ɪnˌdʌstriələˈzeɪʃn/","definition_zh":"工业化；产业化","definition_en":"the large-scale development of industry in a country or region, especially the shift from agriculture and craft work to factory production","core_image":"田野上竖起一排烟囱，村庄被厂房和铁轨包围","scene":"Between 1760 and 1840, industrialization turned British textile towns into smoky factory cities. Families that had spun thread at home moved into mills powered by steam.","sceneCN":"这里 industrialization 是「工业化过程」（第 1 个义项：从农业与手工业转向工厂生产的经济转型）；句意：1760 至 1840 年间，工业化把英国的纺织城镇变成烟雾缭绕的工厂城市；原先在家纺线的家庭搬进了蒸汽驱动的工厂。图中可辨识物件：烟囱、厂房、铁轨、纱线、蒸汽机。","pos":[{"tag":"n.","zh":"工业化；产业化"}],"collocations":[{"phrase":"rapid industrialization","zh":"快速工业化"},{"phrase":"industrialization process","zh":"工业化进程"},{"phrase":"industrialization strategy","zh":"工业化战略"},{"phrase":"early industrialization","zh":"早期工业化"},{"phrase":"industrialization drive","zh":"工业化运动"},{"phrase":"industrialization of agriculture","zh":"农业的工业化"}],"forms":[{"label":"复数","form":"industrializations"}],"derivatives":[{"word":"industry","pos":"n.","zh":"工业；行业；勤勉"},{"word":"industrial","pos":"adj.","zh":"工业的；产业的"},{"word":"industrialize","pos":"v.","zh":"使工业化"},{"word":"industrialist","pos":"n.","zh":"工业家；实业家"},{"word":"industrialized","pos":"adj.","zh":"工业化的"}],"senses":[{"no":"01","title":"The shift from farming and crafts to factory production","titleCN":"工业化：从农业手工业转向工厂生产","definition":"the economic process by which a country or region moves from agriculture and handcrafts to machine-based factory production","definitionCN":"一个国家或地区从农业和手工业转向机器工厂生产的经济过程","example":"Industrialization began with textiles and later spread to iron and transport.","exampleCN":"工业化始于纺织业，后来扩展到钢铁和运输。","why":"Latin industria meant 'diligence, activity'; -ize means 'to make', and -ation names the process. So industrialization is literally the process of making an economy industrious in the new, factory sense.","whyCN":"拉丁 industria 意为「勤勉、活动」；-ize 意为「使」，-ation 命名过程。因此 industrialization 字面上就是把经济变成勤勉的、以工厂为核心的经济这一过程。"},{"no":"02","title":"A historical period of industrial growth","titleCN":"（某一国家的）工业化阶段","definition":"a particular historical era in which a country's industry grows rapidly and changes its economy","definitionCN":"一个国家的工业迅速增长并改变其经济的特定历史时期","example":"British industrialization is usually placed between 1760 and 1840.","exampleCN":"英国的工业化通常被定在 1760 至 1840 年之间。","why":"The suffix -ation can name a whole course of events, not only an abstract process. Because the course has a beginning and an end, it can be dated as a historical period.","whyCN":"后缀 -ation 可命名一整段事件进程，而不只是抽象过程。因为这段进程有起点和终点，所以可以被确定为历史时期。"},{"no":"03","title":"The state of being industrial","titleCN":"工业化程度；工业化状态","definition":"the degree to which a country or region has developed modern industry","definitionCN":"一个国家或地区发展现代工业所达到的程度","example":"Regions differ widely in their level of industrialization.","exampleCN":"各地区工业化程度差异很大。","why":"The same action noun also denotes the result of the action: once the process is complete, what remains is a condition, and one can measure its level.","whyCN":"同一个动作名词也指动作的结果：过程完成后留下的是一个状态，而状态是可以测量其程度的。"},{"no":"04","title":"The reorganization of work into factories","titleCN":"生产的工厂化组织","definition":"the reorganization of production into large units with machines, specialized tasks, and wage labour","definitionCN":"把生产重组为使用机器、分工任务和雇工劳动的大型单位","example":"Industrialization separated the worker from the tools he had once owned.","exampleCN":"工业化使工人与他曾拥有的工具分离。","why":"industry shifted from 'diligence' to 'systematic manufacturing'. Industrialization is the moment when that system takes over the workshop, gathering tools and workers under one roof.","whyCN":"industry 从「勤勉」转向「系统的制造业」。工业化就是这套体系接管作坊的时刻：把工具与工人聚到同一屋顶下。"},{"no":"05","title":"The social change that follows factory growth","titleCN":"工业化带来的社会变迁","definition":"the social transformation caused by industrial growth, especially urbanization and the rise of a wage-earning working class","definitionCN":"工业增长引起的社会转变，尤指城市化和挣工资的工人阶级的兴起","example":"Industrialization drew peasants into cities and broke up extended families.","exampleCN":"工业化把农民吸引进城市，并拆散了大家庭。","why":"A factory gathers many workers at one point. That gathering is a physical fact that becomes a social one: the mill gate produces the city street and the working class by contiguity.","whyCN":"工厂把许多工人聚集在一点。这种聚集是物理事实，却因相邻而成为社会事实：工厂大门催生了城市街道与工人阶级。"},{"no":"06","title":"A phase of building heavy industry","titleCN":"重工业化阶段","definition":"a stage of economic development in which heavy industry such as steel, coal, and machinery is built up on a large scale","definitionCN":"大规模建设钢铁、煤炭、机械等重工业的经济发展阶段","example":"The five-year plans pushed a second wave of industrialization centred on steel.","exampleCN":"五年计划推动了以钢铁为核心的第二次工业化浪潮。","why":"Once industry means manufacturing in general, adding the idea of scale yields a phase sense: industrialization can proceed by building heavier and larger plants, wave after wave.","whyCN":"当 industry 泛指制造业之后，再加上规模观念就得到阶段义：工业化可以一波接一波地通过建设更重、更大的工厂来推进。"},{"no":"07","title":"A state policy of promoting industry","titleCN":"工业化政策；工业化战略","definition":"a deliberate government programme or strategy to build up industry, often by protecting or subsidizing it","definitionCN":"政府有意推动工业建设的计划或战略，常通过保护或补贴工业","example":"Import-substitution industrialization protected local factories with high tariffs.","exampleCN":"进口替代工业化用高关税保护本地工厂。","why":"An -ation noun can name a programme as well as a natural process. Governments can 'carry out' industrialization, so the word becomes the label of a policy.","whyCN":"-ation 名词既可命名自然过程，也可命名计划。政府可以「推行」工业化，于是这个词成为政策的标签。"},{"no":"08","title":"Applying factory methods to another sector","titleCN":"某一部门的工业化（如农业）","definition":"the application of industrial methods such as machinery, standardization, and large-scale organization to a non-manufacturing sector","definitionCN":"把机械、标准化和大型组织等工业方法应用到非制造业部门","example":"The industrialization of agriculture replaced small farms with mechanized estates.","exampleCN":"农业的工业化以机械化大农场取代了小农场。","why":"Because the suffix means 'making X-like industry', it can attach to any sector: to industrialize farming is to make farming behave like industry.","whyCN":"由于该后缀意为「使某部门变得像工业」，它可以附着在任何部门：使农业工业化，就是让农业按工业方式运作。"},{"no":"09","title":"Treating an activity as standardized production","titleCN":"引申：把活动变成标准化的产业流程","definition":"the metaphorical reorganization of an activity into standardized, measurable, high-volume stages, as in education or health care","definitionCN":"隐喻性地把某项活动重组为标准化、可计量、大批量的阶段，如教育或医疗","example":"Critics speak of the industrialization of care, where patients become units on a spreadsheet.","exampleCN":"批评者谈到照护的工业化，病人变成了表格上的单位。","why":"The factory is no longer needed for the metaphor: any activity cut into uniform, countable steps has taken on the shape of industry, so it is said to be industrialized.","whyCN":"这个隐喻不再需要工厂本身：任何被切成统一、可计数步骤的活动都具备了工业的形态，因此被说成工业化。"}],"etymology":{"intro":{"en":"Industrialization is an English noun built on the verb industrialize, from industrial, from industry. Industry descends from Latin industria 'diligence, activity'; the suffixes -ize and -ation come from Greek and Latin.","cn":"industrialization 是在动词 industrialize 上构成的英语名词，industrialize 来自 industrial，industrial 来自 industry。industry 上溯拉丁 industria「勤勉、活动」；后缀 -ize 与 -ation 分别来自希腊语和拉丁语。"},"items":[{"era":"LATIN industria","en":"industria meant 'diligence, activity, care'. Its deeper origin is uncertain: it is generally thought to be indu- (a form of in-) plus struere 'to build', but this reconstruction is not certain.","cn":"industria 意为「勤勉、活动、用心」。其更深来源不确定：一般认为是 indu-（in- 的一种形式）加 struere「建造」，但这只是重构，并非定论。"},{"era":"LATIN industrius","en":"The adjective industrius meant 'diligent, active'. From it English inherited the sense of hard work that survives in industrious.","cn":"形容词 industrius 意为「勤勉的、活跃的」。英语由此继承了「勤奋」这一意义，保留在 industrious 中。"},{"era":"FRENCH industrie","en":"Old French industrie passed the word to English, where industry first meant 'diligence, skill' and only later 'systematic manufacturing'. The older sense survives in the adjective industrious.","cn":"古法语 industrie 把词传给英语；industry 最初意为「勤勉、技艺」，后来才指「系统的制造业」。较古的意义保留在形容词 industrious 中。"},{"era":"SUFFIX -ize","en":"-ize comes from Greek -izein 'to make, cause to be', through Latin -izare. It turns a noun or adjective into a verb of making: industrial → industrialize.","cn":"-ize 来自希腊 -izein「使某事发生、使成为」，经拉丁 -izare 传入。它把名词或形容词变成表示「使之成为」的动词：industrial → industrialize。"},{"era":"SUFFIX -ation","en":"-ation comes from Latin -atio, the suffix of action and its result. Added to industrialize, it names the whole process and its outcome: industrialization.","cn":"-ation 来自拉丁 -atio，是动作及其结果的名词后缀。加在 industrialize 上，它命名整个过程及其结果：industrialization。"},{"era":"MODERN COINAGE","en":"Industrialization is generally dated to the 19th century and follows French industrialisation. It became a standard term when economics began describing the shift from farm to factory as a single historical process.","cn":"industrialization 一般认为是 19 世纪的词，紧随法语 industrialisation 出现。当经济学开始把从农场到工厂的转变描述为单一历史过程时，它成为标准术语。"}]},"similar":{"note":{"en":"Group one shares the Latin base industria; group two is close in meaning but each comes from a different root (modernus, mekhane, urbs, manus + facere).","cn":"第一组共享拉丁词基 industria；第二组意义相近，但各自来自不同词根（modernus、mekhane、urbs、manus + facere）。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"industry","ipa":"/ˈɪndəstri/","tag":"base noun","definition":"manufacturing as a branch of business; also the older sense 'diligent work'. From Latin industria","definitionCN":"作为产业部门的制造业；也有较古的「勤勉」义。来自拉丁 industria"},{"word":"industrial","ipa":"/ɪnˈdʌstriəl/","tag":"-al adjective","definition":"relating to industry or manufacturing; from industry + Latin -alis","definitionCN":"与工业或制造业相关的；由 industry 加拉丁 -alis 构成"},{"word":"industrialist","ipa":"/ɪnˈdʌstriəlɪst/","tag":"-ist person noun","definition":"a person who owns or manages a large industrial business; -ist marks the person, not the process","definitionCN":"拥有或经营大型工业企业的人；-ist 标记人，而非过程"},{"word":"industrious","ipa":"/ɪnˈdʌstriəs/","tag":"same root, different branch","definition":"hard-working and diligent; it kept the original 'diligence' sense of industria and has nothing to do with factories","definitionCN":"勤劳的、勤勉的；它保留了 industria 原初的「勤勉」义，与工厂无关"}]},{"heading":"NEAR MEANING","entries":[{"word":"modernization","ipa":"/ˌmɒdənaɪˈzeɪʃn/","tag":"broader change","definition":"the process of adopting modern methods and ideas; broader than industrialization, which concerns manufacturing in particular","definitionCN":"采用现代方法与观念的过程；比 industrialization 更广，后者特指制造业"},{"word":"mechanization","ipa":"/ˌmekənaɪˈzeɪʃn/","tag":"machine substitution","definition":"replacing human or animal labour with machines; a part of industrialization, not the whole of it","definitionCN":"用机器替代人力或畜力；是工业化的一部分，而非全部"},{"word":"urbanization","ipa":"/ˌɜːbənaɪˈzeɪʃn/","tag":"city growth","definition":"the growth of towns and cities; often a consequence of industrialization rather than a synonym","definitionCN":"城镇与城市的增长；常是工业化的后果，而非同义词"},{"word":"manufacturing","ipa":"/ˌmænjuˈfæktʃərɪŋ/","tag":"production sector","definition":"the making of goods in large quantities; the activity that industrialization expands and reorganizes","definitionCN":"大批量制造商品；工业化所扩大并重组的生产活动"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"industria 'diligence' + -ize 'make' + -ation 'process': the word literally names the making of a diligent, factory-based economy.","cn":"industria「勤勉」+ -ize「使」+ -ation「过程」：这个词字面上命名了把经济变成勤勉的、以工厂为基础的经济这一过程。"},{"en":"industry first meant diligence; industrialization is the historical process that turned that diligence into mills and machines.","cn":"industry 最初意为勤勉；industrialization 是把这种勤勉转成工厂与机器的历史过程。"},{"en":"The verb is industrialize and the noun is industrialization, exactly like modernize and modernization.","cn":"动词是 industrialize，名词是 industrialization，正如 modernize 与 modernization。"},{"en":"The chain industry → industrial → industrialize → industrialization adds one grammatical layer at a time.","cn":"industry → industrial → industrialize → industrialization 这条链每次加一层语法成分。"},{"en":"Picture a farm with a mill rising beside it: that single change, seen as a national process, is industrialization.","cn":"想象农场旁立起一座工厂：把这一变化看作全国性的过程，就是 industrialization。"}],"abstract":[{"en":"Think of a chimney replacing a church tower as the tallest thing in town; that swap is the visible signature of industrialization.","cn":"把城镇最高处从教堂尖塔换成一截烟囱；这个替换就是工业化最可见的标志。"},{"en":"Think of a loom moving out of a cottage into a mill: the same motion, but now organized as a system.","cn":"把织机从农舍搬进工厂：动作相同，但如今被组织成一套系统。"},{"en":"Think of a timeline with fields on the left and factories on the right; industrialization is the arrow between them.","cn":"想象一条时间线，左边是田野，右边是工厂；工业化就是两者之间的箭头。"}]},"examples":[{"en":"Japan's industrialization was compressed into a few decades after 1868.","cn":"日本的工业化在 1868 年之后被压缩到几十年内完成。"},{"en":"Rapid industrialization polluted the river within a single generation.","cn":"快速的工业化在一代人之内就污染了这条河。"},{"en":"The industrialization of higher education has turned courses into standardized products.","cn":"高等教育的工业化把课程变成了标准化产品。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"industry（勤勉／工业）+ -ize（使之化）+ -ation（过程）→ 使国家转为工业体系的过程 → industrialization 工业化；词根本义是「勤勉、活动」","word":"industrialization"},"root":"拉丁 industria「勤勉、活动」，一般认为是 indu-（in）+ struere「建造」；经古法语 industrie 进入英语，再加希腊来源的 -ize 与拉丁 -ation，构成表示「使之工业化」的过程名词。","sensesIntro":{"en":"Nine senses all follow one arc: diligence becomes systematic work, systematic work becomes manufacturing, and manufacturing spreads until it reorganizes a whole economy, its cities, its policies, and even its schools.","cn":"九个义项沿一条弧线展开：勤勉变成系统化劳动，系统化劳动变成制造业，制造业扩散开来，直到重组整个经济、城市、政策乃至学校。"},"semanticMap":{"core":{"en":"CORE IMAGE: the farm horizon broken by chimneys and rail lines.","cn":"核心意象：农场地平线被烟囱与铁轨切开。"},"chain":["DILIGENCE","SYSTEMATIC WORK","MANUFACTURING","MAKING A COUNTRY INDUSTRIAL","FACTORIES AND CITIES","STANDARDIZED PRODUCTION"],"branches":[{"senses":"S01 · S02 · S03","en":"THE PROCESS ITSELF: the transition, its historical stages, and the level a country reaches.","cn":"过程本身：转型、其历史阶段，以及一国达到的程度。"},{"senses":"S04 · S08","en":"PRODUCTION REORGANIZED: work gathered into factories, and later whole sectors such as farming run like factories.","cn":"生产重组：劳动集中到工厂，后来农业等整个部门也按工厂方式运作。"},{"senses":"S05","en":"SOCIETY RESHAPED: mills pull workers into cities and create a new working class.","cn":"社会重塑：工厂把工人拉进城市，造就新的工人阶级。"},{"senses":"S06 · S07","en":"SCALE AND POLICY: heavy-industry phases and state strategies for building an industrial base.","cn":"规模与政策：重工业阶段与国家建设工业基础的战略。"},{"senses":"S09","en":"THE METAPHOR: any activity cut into standardized, measurable stages is said to be industrialized.","cn":"隐喻：任何被切成标准化、可计量阶段的活动都被称为工业化。"}]},"affixes":{"intro":{"en":"Industrialization is a three-layer construction: industry + -al + -ize + -ation. Each suffix is productive and each adds a clear grammatical step from thing to quality to action to process.","cn":"industrialization 是三层构造：industry + -al + -ize + -ation。每个后缀都能产，且各加一个清晰的语法步骤：从事物到性质、到动作、再到过程。"},"latinIntro":{"en":"Latin industria 'diligence' produced industrious and industry; the later industrial family was built in French and English on the manufacturing sense. The root appears as industr-.","cn":"拉丁 industria「勤勉」产生了 industrious 与 industry；后来的 industrial 词族是在法语和英语中依制造业义搭建的。词根以 industr- 形式出现。"},"items":[{"word":"industry","structure":"industria (diligence) via Old French industrie","meaning":"manufacturing as a sector; diligent work","meaningCN":"工业；行业；勤勉（经古法语 industrie 来自拉丁 industria）","example":"The steel industry employs thousands of workers.","exampleCN":"钢铁工业雇用了数千名工人。"},{"word":"industrious","structure":"industri- + -ous","meaning":"hard-working, diligent","meaningCN":"勤劳的；勤勉的（-ous 形容词后缀）","example":"She was an industrious student who never wasted an hour.","exampleCN":"她是个勤奋的学生，从不浪费一小时。"},{"word":"industrial","structure":"industri- + -al","meaning":"relating to industry","meaningCN":"工业的（-al 形容词后缀）","example":"Industrial output rose sharply last year.","exampleCN":"去年工业产出大幅上升。"},{"word":"industrialist","structure":"industrial + -ist","meaning":"an owner or manager of large industry","meaningCN":"工业家；实业家（-ist 指人名词）","example":"The industrialist built a model town for his workers.","exampleCN":"这位工业家为工人建了一座模范城镇。"},{"word":"industrialize","structure":"industrial + -ize","meaning":"to develop industry in a place","meaningCN":"使工业化（-ize 动词后缀）","example":"The government tried to industrialize the rural south.","exampleCN":"政府试图使南方乡村工业化。"},{"word":"industrialization","structure":"industrialize + -ation","meaning":"the process of becoming industrial","meaningCN":"工业化（-ation 过程名词后缀）","example":"Industrialization changed the face of the country.","exampleCN":"工业化改变了这个国家的面貌。"},{"word":"industrialized","structure":"industrialize + -ed","meaning":"having a developed industry","meaningCN":"工业化的（-ed 形容词后缀）","example":"Industrialized nations dominate the export market.","exampleCN":"工业化国家主导着出口市场。"},{"word":"deindustrialize","structure":"de- (reverse) + industrialize","meaning":"to reduce industrial activity in a region","meaningCN":"去工业化（de-「去除」+ industrialize）","example":"The region deindustrialized after the mines closed.","exampleCN":"矿场关闭后该地区去工业化了。"},{"word":"industrialism","structure":"industrial + -ism","meaning":"a social order organized around large-scale industry","meaningCN":"工业主义（-ism 学说／制度名词）","example":"Critics attacked the values of industrialism.","exampleCN":"批评者抨击工业主义的价值观。"}],"latinEntries":[{"word":"industria","structure":"industria (diligence, activity)","meaning":"diligence, activity, care","meaningCN":"勤勉；活动；用心"},{"word":"industrius","structure":"industria + -ius","meaning":"diligent, active","meaningCN":"勤勉的；活跃的"},{"word":"industrialis","structure":"industria + -alis","meaning":"relating to industry","meaningCN":"与工业相关的"}]}},{"word":"industrial","ipa_uk":"/ɪnˈdʌstriəl/","ipa_us":"/ɪnˈdʌstriəl/","definition_zh":"工业的；产业的；工业化的；从事工业的","definition_en":"relating to industry, manufacturing, or the people and systems that produce goods in factories","core_image":"厂房里的传送带不停转动，成品排成队列向外送出","scene":"The industrial belt along the river employed half the town. Its old mills now stand beside new electronics plants.","sceneCN":"这里 industrial 是「工业的」（第 1 个义项：与工业或制造业相关的）；句意：沿河的工业带雇用了镇上半数人口；它的老纺织厂如今与新电子厂并立。图中可辨识物件：厂房、传送带、烟囱、电子元件。","pos":[{"tag":"adj.","zh":"工业的；产业的；工业化的；从事工业的"},{"tag":"n.","zh":"工业股票（复数 industrials）"}],"collocations":[{"phrase":"industrial revolution","zh":"工业革命"},{"phrase":"industrial production","zh":"工业生产"},{"phrase":"industrial policy","zh":"产业政策"},{"phrase":"industrial waste","zh":"工业废料"},{"phrase":"industrial relations","zh":"劳资关系"},{"phrase":"industrial action","zh":"罢工等工业行动"}],"forms":[{"label":"比较级","form":"more industrial"},{"label":"最高级","form":"most industrial"},{"label":"名词复数","form":"industrials"}],"derivatives":[{"word":"industry","pos":"n.","zh":"工业；行业"},{"word":"industrialize","pos":"v.","zh":"使工业化"},{"word":"industrialization","pos":"n.","zh":"工业化"},{"word":"industrialist","pos":"n.","zh":"工业家"},{"word":"industrialized","pos":"adj.","zh":"工业化的"}],"senses":[{"no":"01","title":"Relating to industry and manufacturing","titleCN":"工业的；制造业的","definition":"connected with industry, especially the manufacturing of goods in factories","definitionCN":"与工业相关的，尤指在工厂中制造商品","example":"The government published a report on industrial growth.","exampleCN":"政府发布了一份关于工业增长的报告。","why":"Latin -alis means 'of or pertaining to'. Added to industry, industrial simply means 'of industry'; when industry came to mean factory manufacturing, the adjective followed it.","whyCN":"拉丁 -alis 意为「属于某物的、与某物相关的」。加在 industry 上，industrial 就是「工业的」；当 industry 转指工厂制造业时，这个形容词也随之转义。"},{"no":"02","title":"Used in or for industry","titleCN":"工业用的；工业规模的","definition":"made for use by industry, or operating on the scale of industry rather than a household","definitionCN":"供工业使用的，或按工业而非家庭规模运作的","example":"Industrial chemicals must be stored under strict safety rules.","exampleCN":"工业化学品必须在严格的安全规则下储存。","why":"The adjective marks belonging: chemicals that belong to the industrial process, not the kitchen. The same pattern gives industrial diamonds and industrial glue.","whyCN":"这个形容词标记归属：属于工业流程而非厨房的化学品。同一模式也构成 industrial diamonds（工业钻石）与 industrial glue（工业胶）。"},{"no":"03","title":"Having a lot of industry","titleCN":"工业发达的；工业密集的","definition":"describing a place that contains many factories and much manufacturing","definitionCN":"描述一个拥有许多工厂和大量制造业的地方","example":"The industrial north has higher wages but worse air.","exampleCN":"工业化的北方工资更高，但空气更差。","why":"A place can be named by what fills it. If industry fills a region, the region is industrial, just as a forested valley is wooded.","whyCN":"一个地方可以用充满它的东西来命名。如果工业充满一个地区，这个地区就是 industrial，正如长满森林的山谷是 wooded。"},{"no":"04","title":"Relating to employers and workers","titleCN":"劳资的；（劳资）关系的","definition":"concerning the relationship between employers and employees, especially disputes and negotiations","definitionCN":"关于雇主与雇员之间关系的，尤指争端与谈判","example":"Industrial relations in the plant have improved since the new manager arrived.","exampleCN":"新经理到任后，厂里的劳资关系有所改善。","why":"The relationship exists inside industry, so the adjective locates it: industrial relations are the relations of the industrial workplace, not relations between industries.","whyCN":"这种关系存在于工业内部，所以形容词为其定位：industrial relations 是工业工作场所内部的关系，而非工业之间的关系。"},{"no":"05","title":"Concerning government policy toward industry","titleCN":"产业（政策）的","definition":"relating to official plans and measures that support, regulate, or restructure industry","definitionCN":"与支持、规范或重组工业的官方计划与措施相关的","example":"Industrial policy in the region focuses on semiconductors.","exampleCN":"该地区的产业政策聚焦于半导体。","why":"Here industrial marks the object of policy: the policy is about industry. The adjective tells you what the noun governs, not who makes it.","whyCN":"此处 industrial 标记政策的对象：政策是关于工业的。这个形容词说明名词管的是什么，而不是谁制定它。"},{"no":"06","title":"Characteristic of an industrial society","titleCN":"工业社会的；工业时代的","definition":"belonging to the era or type of society whose economy and daily life are dominated by industry","definitionCN":"属于经济与日常生活由工业主导的时代或社会类型的","example":"The industrial city replaced the market town as the typical settlement.","exampleCN":"工业城市取代集镇成为典型的聚居形态。","why":"When industry dominates an age, the adjective can name the age itself: industrial society is the society shaped by industry, a label rather than a description of a single object.","whyCN":"当工业主导一个时代时，这个形容词可以命名时代本身：industrial society 是由工业塑造的社会，是标签而非对单一事物的描述。"},{"no":"07","title":"Belonging to the secondary sector","titleCN":"第二产业的；工业部门的","definition":"belonging to the sector of the economy that transforms raw materials into goods, as opposed to agriculture or services","definitionCN":"属于把原材料转化为产品的经济部门，与农业或服务业相对","example":"Industrial employment fell as service jobs expanded.","exampleCN":"随着服务业岗位扩张，工业就业下降。","why":"Statisticians classify an economy by adjectives: agricultural, industrial, service. The adjective turns a sector into a label, and the label becomes a noun-like category.","whyCN":"统计学家用形容词给经济分类：农业的、工业的、服务业的。这个形容词把部门变成标签，而标签又近似名词范畴。"},{"no":"08","title":"Industrial shares on the stock market","titleCN":"工业股票（复数名词）","definition":"the shares of industrial companies, used in the plural as a category on financial markets","definitionCN":"工业公司的股票，在金融市场上以复数形式作为一类资产","example":"Investors moved money out of industrials and into technology.","exampleCN":"投资者把资金从工业股转投科技股。","why":"This is an ellipsis: 'industrial shares' loses shares and keeps the adjective, which then behaves as a noun. English does this with many adjectives, as in valuables and chemicals.","whyCN":"这是省略：industrial shares 省去 shares，只留形容词，形容词便充当名词。英语常用这种方式，如 valuables 与 chemicals。"},{"no":"09","title":"Bare, functional, machine-made in style","titleCN":"工业风的；机器制造感的","definition":"having a plain, functional, machine-made look, as in industrial design or industrial music","definitionCN":"具有朴素、功能化、机器制造观感的，如工业设计或工业音乐","example":"The loft kept its industrial look with exposed pipes and concrete walls.","exampleCN":"这间 Loft 保留工业风，露出管道和混凝土墙。","why":"The metaphor drops the factory and keeps its manner: what looks as if it came from a factory, all bare function and metal, is called industrial.","whyCN":"这个隐喻丢开工厂本身，只保留它的方式：看起来像从工厂出来、全是裸露功能与金属感的东西，就被称为 industrial。"}],"etymology":{"intro":{"en":"Industrial is industry plus the Latin adjective suffix -alis, which became English -al. French industriel was the model for the English word, and the manufacturing sense of industry made the adjective mean 'of factories'.","cn":"industrial 是 industry 加拉丁形容词后缀 -alis（在英语中变为 -al）构成。法语 industriel 是英语词的样板；industry 的制造业义使这个形容词意为「工厂的」。"},"items":[{"era":"LATIN industria","en":"industria meant 'diligence, activity, care'. Its deeper origin is uncertain and is generally reconstructed as indu- (in-) + struere 'to build', but this is not proven.","cn":"industria 意为「勤勉、活动、用心」。其更深来源不确定，一般重构为 indu-（in-）+ struere「建造」，但并未得到证明。"},{"era":"LATIN industrius","en":"industrius meant 'diligent, active'. It kept the personal sense of hard work, which English preserves in industrious.","cn":"industrius 意为「勤勉的、活跃的」。它保留了个人勤奋这一意义，英语以 industrious 保存下来。"},{"era":"FRENCH industriel","en":"18th-century French formed industriel from industrie to mean 'relating to manufacturing'. French was then the language of economic writing, so the model spread quickly.","cn":"18 世纪法语由 industrie 构成 industriel，意为「与制造业相关的」。当时法语是经济写作的语言，这一样板迅速传播。"},{"era":"ENGLISH industrial","en":"English adopted industrial in the late 18th century, at first in phrases describing manufacturing. The word grew with the very thing it described.","cn":"英语在 18 世纪晚期采用 industrial，最初用于描述制造业的短语。这个词随它所描述的事物一同成长。"},{"era":"THE INDUSTRIAL REVOLUTION","en":"The phrase industrial revolution made the adjective the name of an era. From there industrial society, industrial city, and industrial age followed as standard labels.","cn":"industrial revolution 这一短语使该形容词成为时代的名称。此后 industrial society、industrial city、industrial age 都成为标准标签。"},{"era":"MODERN EXTENSIONS","en":"In the 20th century industrial produced a noun plural, industrials, for industrial shares, and later described machine-made styles in design and music. These are ellipses and metaphors of the core sense.","cn":"20 世纪 industrial 产生名词复数 industrials，指工业股票；后来又在设计与音乐中描述机器制造的风格。这些都是核心义的省略与隐喻。"}]},"similar":{"note":{"en":"Group one shares the Latin base industria; group two is close in meaning but not cognate with it (manus + facere, Greek mekhane, and the compound mass-produce).","cn":"第一组共享拉丁词基 industria；第二组意义相近，但与它并非同源（manus + facere、希腊 mekhane，以及复合词 mass-produce）。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"industry","ipa":"/ˈɪndəstri/","tag":"base noun","definition":"manufacturing as a sector, or diligent work; the noun from which industrial is formed","definitionCN":"作为部门的制造业，或勤勉的工作；industrial 所由构成的名词"},{"word":"industrious","ipa":"/ɪnˈdʌstriəs/","tag":"same root, different branch","definition":"hard-working; it kept the 'diligence' sense of industria and never came to mean 'of factories'","definitionCN":"勤劳的；它保留了 industria 的「勤勉」义，从未变成「工厂的」"},{"word":"industrialized","ipa":"/ɪnˈdʌstriəlaɪzd/","tag":"past-participle adjective","definition":"having developed a large manufacturing base; the -ed form describes a result, while industrial describes a relation","definitionCN":"已发展出大规模制造业的；-ed 形式描述结果，而 industrial 描述关系"},{"word":"industrialist","ipa":"/ɪnˈdʌstriəlɪst/","tag":"-ist person noun","definition":"an owner or manager of large industry; -ist names a person, not a quality","definitionCN":"大型工业的所有者或管理者；-ist 命名人，而非性质"}]},{"heading":"NEAR MEANING","entries":[{"word":"manufacturing","ipa":"/ˌmænjuˈfæktʃərɪŋ/","tag":"production","definition":"the making of goods on a large scale; it names the activity, while industrial describes what belongs to it","definitionCN":"大规模制造商品；它命名活动，而 industrial 描述从属于该活动的事物"},{"word":"mechanized","ipa":"/ˈmekənaɪzd/","tag":"machine-driven","definition":"run or operated by machines; a mechanized process is one kind of industrial process","definitionCN":"由机器运行或操作的；机械化的过程是工业过程的一种"},{"word":"mass-produced","ipa":"/ˌmɑːs prəˈdjuːst/","tag":"quantity","definition":"made in large numbers by a standard process; it stresses quantity, not the whole industrial system","definitionCN":"按标准流程大量制造的；强调数量，而非整个工业体系"},{"word":"blue-collar","ipa":"/ˌbluː ˈkɒlə/","tag":"workforce","definition":"relating to manual or factory workers; it describes people, while industrial can describe places, goods, or policies","definitionCN":"与体力或工厂劳动者相关的；它描述人，而 industrial 可描述地点、商品或政策"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"industria 'diligence, activity' + -al 'of or pertaining to': industrial means 'of that activity', and the activity later became factory manufacturing.","cn":"industria「勤勉、活动」+ -al「与之相关的」：industrial 意为「与该活动相关的」，而该活动后来变成了工厂制造。"},{"en":"Keep industrial and industrious apart: industrial is about factories, industrious is about hard work. The same root took two roads.","cn":"把 industrial 与 industrious 分清：前者关于工厂，后者关于勤奋。同一词根走了两条路。"},{"en":"The family runs industry → industrial → industrialize → industrialization, one suffix at a time.","cn":"这个词族沿 industry → industrial → industrialize → industrialization 展开，每次加一个后缀。"},{"en":"A skyline of smokestacks and conveyor belts is an industrial skyline; the adjective paints the whole scene.","cn":"由烟囱和传送带构成的天际线就是 industrial 天际线；这个形容词把整个场景涂上颜色。"},{"en":"The industrial revolution is the phrase that turned the adjective into the name of an age.","cn":"industrial revolution 这一短语把这个形容词变成了一个时代的名称。"}],"abstract":[{"en":"Think of a conveyor belt as the spine of a factory: whatever the belt touches becomes industrial.","cn":"把传送带想象成工厂的脊椎：传送带碰到什么，什么就变成工业的。"},{"en":"Think of two words leaving one root: industrious stays with the worker's sweat, industrial walks into the factory.","cn":"想象两个词从同一词根出发：industrious 留在工人的汗水里，industrial 走进工厂。"},{"en":"Think of a map coloured grey wherever chimneys stand; that grey is the adjective's territory.","cn":"想象一张地图，凡有烟囱处就涂成灰色；这片灰色就是该形容词的领地。"}]},"examples":[{"en":"The Ruhr became the industrial heart of Germany in the nineteenth century.","cn":"鲁尔区在 19 世纪成为德国的工业心脏。"},{"en":"Industrial action halted production for two weeks.","cn":"工业行动使生产停顿了两周。"},{"en":"Industrial design favours clean lines and cheap materials.","cn":"工业设计偏爱简洁线条与廉价材料。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"industry（工业）+ -al（表所属）→ industrial 工业的；同根 industrious 却是「勤劳的」——一个进工厂，一个留在人身上","word":"industrial"},"root":"拉丁 industria「勤勉、活动」+ 拉丁形容词后缀 -alis（英语 -al）；industria 一般认为是 indu-（in）+ struere「建造」。同根词 industrious 保留「勤奋」义，industrial 则沿「制造业」义发展。","sensesIntro":{"en":"Nine senses spread outward from 'of industry': the inputs industry uses, the places and eras it dominates, the relations inside it, the policies about it, its shares, and finally its machine-made look.","cn":"九个义项从「工业的」向外铺开：工业使用的投入品、它主导的地点与时代、它内部的劳资关系、关于它的政策、它的股票，最后是它机器制造的观感。"},"semanticMap":{"core":{"en":"CORE IMAGE: a conveyor belt that never stops, turning material into finished goods.","cn":"核心意象：一条不停运转、把材料变成成品的传送带。"},"chain":["DILIGENCE","INDUSTRY","OF FACTORIES","HEAVILY BUILT UP","WORKPLACE AND POLICY","MACHINE-MADE STYLE"],"branches":[{"senses":"S01 · S02","en":"THE CORE RELATION: what belongs to industry, including the materials and processes industry uses.","cn":"核心关系：从属于工业的事物，包括工业使用的材料与流程。"},{"senses":"S03 · S06 · S07","en":"PLACE, ERA, SECTOR: regions filled with industry, industrial civilization, and the industrial sector of an economy.","cn":"地点、时代与部门：布满工业的地区、工业文明，以及经济中的工业部门。"},{"senses":"S04 · S05","en":"WORKPLACE AND POLICY: relations between employers and workers, and government policy toward industry.","cn":"劳资与政策：雇主与工人之间的关系，以及政府对工业的政策。"},{"senses":"S08","en":"FINANCE: industrials are the shares of industrial companies, an ellipsis of 'industrial shares'.","cn":"金融：industrials 指工业公司的股票，是 industrial shares 的省略。"},{"senses":"S09","en":"STYLE: bare, functional, machine-made design is called industrial by metaphor.","cn":"风格：朴素、功能化、机器制造的设计被隐喻地称为工业风。"}]},"affixes":{"intro":{"en":"Industrial is a single suffix added to a noun: industry + -al. The suffix is Latin -alis, the ordinary maker of 'belonging to' adjectives, also seen in natural, national, and cultural.","cn":"industrial 只是名词加一个后缀：industry + -al。该后缀是拉丁 -alis，是构成表示所属关系的形容词的常规手段，也见于 natural、national、cultural。"},"latinIntro":{"en":"Latin industria 'diligence' yielded both the personal adjective industrius and, much later, the manufacturing noun industry. The root appears as industr-.","cn":"拉丁 industria「勤勉」既产出了描述人的形容词 industrius，也在很久以后产出了表示制造业的名词 industry。词根以 industr- 形式出现。"},"items":[{"word":"industry","structure":"industria via Old French industrie","meaning":"manufacturing sector; diligent work","meaningCN":"工业；行业；勤勉（经古法语来自拉丁 industria）","example":"The car industry is the largest employer in the region.","exampleCN":"汽车工业是该地区最大的雇主。"},{"word":"industrious","structure":"industri- + -ous","meaning":"hard-working and diligent","meaningCN":"勤劳的；勤勉的（-ous 形容词后缀）","example":"An industrious apprentice learns faster.","exampleCN":"勤奋的学徒学得更快。"},{"word":"industrial","structure":"industri- + -al (Latin -alis)","meaning":"relating to industry","meaningCN":"工业的（-al 拉丁形容词后缀）","example":"Industrial output fell during the recession.","exampleCN":"经济衰退期间工业产出下降。"},{"word":"industrialize","structure":"industrial + -ize","meaning":"to make industrial","meaningCN":"使工业化（-ize 动词后缀）","example":"The plan aimed to industrialize the interior.","exampleCN":"该计划旨在使内陆地区工业化。"},{"word":"industrialization","structure":"industrialize + -ation","meaning":"the process of becoming industrial","meaningCN":"工业化（-ation 过程名词）","example":"Industrialization brought both wealth and smog.","exampleCN":"工业化既带来财富，也带来烟雾。"},{"word":"industrialized","structure":"industrialize + -ed","meaning":"having a developed industry","meaningCN":"工业化的（-ed 形容词后缀）","example":"Industrialized economies usually have a larger service sector.","exampleCN":"工业化经济体通常拥有更庞大的服务业。"},{"word":"industrialist","structure":"industrial + -ist","meaning":"an owner or manager of large industry","meaningCN":"工业家（-ist 指人名词）","example":"The industrialist donated land for a school.","exampleCN":"这位工业家捐地建了一所学校。"},{"word":"industrialism","structure":"industrial + -ism","meaning":"a social order centred on large-scale industry","meaningCN":"工业主义（-ism 制度／学说名词）","example":"Industrialism reshaped family life.","exampleCN":"工业主义重塑了家庭生活。"},{"word":"deindustrialization","structure":"de- (reverse) + industrialization","meaning":"the decline of manufacturing in a region","meaningCN":"去工业化（de-「去除」+ industrialization）","example":"Deindustrialization left empty factories along the canal.","exampleCN":"去工业化在运河边留下空置的工厂。"}],"latinEntries":[{"word":"industria","structure":"industria (diligence, activity)","meaning":"diligence, activity, care","meaningCN":"勤勉；活动；用心"},{"word":"industrius","structure":"industria + -ius","meaning":"diligent, active","meaningCN":"勤勉的；活跃的"},{"word":"industrialis","structure":"industria + -alis","meaning":"relating to industry","meaningCN":"与工业相关的"}]}},{"word":"inequality","ipa_uk":"/ˌɪnɪˈkwɒləti/","ipa_us":"/ˌɪnɪˈkwɑːləti/","definition_zh":"不平等；不均等；不等式","definition_en":"an unfair difference in status, wealth, or opportunity; a lack of equality; in mathematics, a statement that one quantity is not equal to another","core_image":"天平一端压得很低，另一端高高翘起","scene":"Rising rent has widened inequality between homeowners and renters in the city. The mayor now publishes an annual report on the gap.","sceneCN":"这里 inequality 是「（收入与财富的）不平等」（第 1 个义项：社会成员之间的财富差距）；句意：房租上涨扩大了城市里房主与租客之间的不平等；市长现在每年发布一份关于这一差距的报告。图中可辨识物件：天平、高低不一的房屋、报告、城市天际线。","pos":[{"tag":"n.","zh":"不平等；不均等；不等式"}],"collocations":[{"phrase":"income inequality","zh":"收入不平等"},{"phrase":"social inequality","zh":"社会不平等"},{"phrase":"economic inequality","zh":"经济不平等"},{"phrase":"gender inequality","zh":"性别不平等"},{"phrase":"reduce inequality","zh":"减少不平等"},{"phrase":"the inequality gap","zh":"不平等差距"}],"forms":[{"label":"复数","form":"inequalities"}],"derivatives":[{"word":"equal","pos":"adj./v.","zh":"平等的；等于"},{"word":"equality","pos":"n.","zh":"平等"},{"word":"unequal","pos":"adj.","zh":"不平等的"},{"word":"unequally","pos":"adv.","zh":"不平等地"},{"word":"equalize","pos":"v.","zh":"使平等；使均等"}],"senses":[{"no":"01","title":"Unequal distribution of income and wealth","titleCN":"收入与财富的不平等","definition":"the situation in which income and assets are distributed unevenly among people or groups","definitionCN":"收入与资产在人与人、群体与群体之间分配不均的状况","example":"Inequality has risen sharply as executive pay has grown.","exampleCN":"随着高管薪酬增长，不平等急剧上升。","why":"Latin aequus means 'level'. Money placed on a balance either levels out or tilts; when the pans sit at different heights, the condition is literally inequality.","whyCN":"拉丁 aequus 意为「平的」。放在天平上的钱财要么持平，要么倾斜；当两端停在不同高度时，这种状态字面上就是 inequality。"},{"no":"02","title":"Unequal social status or class","titleCN":"社会地位与阶层的不平等","definition":"a condition in which people hold different social rank, prestige, or class position","definitionCN":"人们拥有不同社会等级、声望或阶级地位的状况","example":"Social inequality persisted long after the old titles were abolished.","exampleCN":"旧头衔废除很久之后，社会不平等依然存在。","why":"Society is imagined as a slope or a staircase: aequus supplies the image of level ground, so unequal rank is ground that slopes. The word measures height, not just money.","whyCN":"社会被想象成斜坡或楼梯：aequus 提供平地的意象，因此不平等的等级就是倾斜的地面。这个词衡量的是高度，不只是钱财。"},{"no":"03","title":"Lack of equal legal rights","titleCN":"法律权利上的不平等","definition":"the condition in which people do not have the same rights or treatment before the law","definitionCN":"人们没有相同权利或未能在法律面前获得同等待遇的状况","example":"The court struck down a law that permitted inequality before the courts.","exampleCN":"法院废除了一部允许法庭面前不平等的法律。","why":"Legal equality is imagined as everyone standing on the same level floor. The negative prefix in- removes that floor, so inequality means some stand higher before the law.","whyCN":"法律平等被想象为每个人都站在同一水平地面上。否定前缀 in- 抽掉这块地面，因此 inequality 意味着有些人在法律面前站得更高。"},{"no":"04","title":"Unequal treatment by gender or race","titleCN":"性别与种族不平等","definition":"the unequal treatment or outcomes that people experience because of their gender, race, or ethnicity","definitionCN":"人们因性别、种族或族裔而经历的不平等待遇或结果","example":"Gender inequality in pay remains a persistent problem in the industry.","exampleCN":"薪酬上的性别不平等在该行业仍是长期问题。","why":"The word takes categories of people and places them on different levels of the same scale. The level image is what makes 'gap' the natural companion of inequality.","whyCN":"这个词把人按类别放到同一台天平的不同高度上。正是水平意象使「差距」成为 inequality 的天然搭档。"},{"no":"05","title":"Unequal opportunity and access","titleCN":"机会与教育机会的不平等","definition":"the condition in which people have different chances to education, health care, or advancement","definitionCN":"人们在教育、医疗或上升机会上拥有不同几率的状况","example":"Inequality of opportunity begins with unequal schooling.","exampleCN":"机会的不平等始于教育的不平等。","why":"Opportunity is pictured as a starting line drawn across level ground; aequus supplies the level, and in- denies it. Unequal opportunity means some runners start uphill.","whyCN":"机会被描绘为画在平地上的起跑线；aequus 提供平坦，in- 否定平坦。机会不平等意味着有些跑者从坡上起跑。"},{"no":"06","title":"A mathematical statement of non-equality","titleCN":"数学不等式","definition":"a mathematical statement that one quantity is greater than or less than another, written with symbols such as < or >","definitionCN":"用 < 或 > 等符号表示一个量大于或小于另一个量的数学陈述","example":"The teacher asked the class to solve the inequality before the bell rang.","exampleCN":"老师让全班在下课铃响前解出这个不等式。","why":"This is the oldest literal sense: aequalitas is equality, and in- says 'not'. Mathematics simply kept the literal meaning while social usage grew metaphorical.","whyCN":"这是最古老的字面义：aequalitas 是相等，in- 表示「不」。数学只是保留了字面意义，而社会用法则日益隐喻化。"},{"no":"07","title":"The gap between rich and poor countries","titleCN":"国家之间的不平等","definition":"the unequal distribution of wealth, income, and resources among countries or regions","definitionCN":"财富、收入与资源在国家或地区之间分配不均的状况","example":"Global inequality has shifted as some former colonies industrialized.","exampleCN":"随着一些前殖民地实现工业化，全球不平等发生了转移。","why":"Nations can be treated as pans on one balance. The scale metaphor scales up: the same word that compares two households also compares two countries.","whyCN":"国家可以被当作同一台天平上的秤盘。秤的隐喻放大了：比较两户人家的同一个词，也用来比较两个国家。"},{"no":"08","title":"Unequal health outcomes","titleCN":"健康结果的不平等","definition":"avoidable differences in health status or access to care between social groups","definitionCN":"不同社会群体在健康状况或获得照护方面可避免的差异","example":"Health inequality between neighborhoods is visible in life expectancy.","exampleCN":"社区之间的健康不平等在预期寿命上清晰可见。","why":"Health outcomes are quantities that can be plotted for each group; when the plotted lines sit at different levels, the level metaphor of aequus applies once more.","whyCN":"健康结果是可为每个群体绘制的量；当绘出的线处于不同高度时，aequus 的水平隐喻再次适用。"},{"no":"09","title":"An imbalance of power or bargaining strength","titleCN":"权力或谈判力量的不对等","definition":"an asymmetry in power, influence, or bargaining strength between two parties","definitionCN":"两方在权力、影响力或谈判力量上的不对称","example":"Inequality of bargaining power makes the contract unfair to individual workers.","exampleCN":"谈判力量的不对等使合同对个体工人不公平。","why":"The two parties are weights on the scale rather than people on a floor. When one side can press the pan down at will, the relation itself is unequal.","whyCN":"两方是天平上的砝码，而非地板上的两个人。当一方能随意把秤盘压下时，关系本身就是不平等的。"}],"etymology":{"intro":{"en":"Inequality is the negative of equality: Latin in- 'not' added to aequalitas 'equality', from aequalis 'equal', from aequus 'level, even'. The word reached English through Old French inégalité.","cn":"inequality 是 equality 的否定形式：拉丁否定前缀 in-「不」加在 aequalitas「平等」上，aequalitas 来自 aequalis「相等的」，再上溯 aequus「平的、均匀的」。该词经古法语 inégalité 进入英语。"},"items":[{"era":"LATIN aequus","en":"aequus meant 'level, flat, even' and from that 'equal'. The physical image is a level surface, not a mathematical symbol.","cn":"aequus 意为「平的、平坦的、均匀的」，由此引申为「相等的」。它的本义画面是一个水平面，而非数学符号。"},{"era":"LATIN aequalis","en":"aequalis meant 'equal, like, of the same level'. It turned the flat-surface image into a relation between two things.","cn":"aequalis 意为「相等的、相同的、同一水平的」。它把平面意象转化为两物之间的关系。"},{"era":"LATIN aequalitas","en":"aequalitas was the state noun: 'equality, evenness'. The suffix -itas is the source of English -ity, which names a condition.","cn":"aequalitas 是状态名词：「平等、均匀」。后缀 -itas 是英语 -ity 的来源，用来命名一种状态。"},{"era":"LATIN inaequalitas","en":"in- 'not' + aequalitas gave inaequalitas, 'unevenness, inequality'. The negative was part of the Latin word before English borrowed anything.","cn":"in-「不」+ aequalitas 构成 inaequalitas「不均、不平等」。在英语借入之前，这个否定成分已属于拉丁词本身。"},{"era":"FRENCH inégalité","en":"Old French inégalité carried the word into English, where inequality is recorded in the Middle English period. The spelling and suffix became English.","cn":"古法语 inégalité 把词带入英语，inequality 在中古英语时期已有记录。拼写与后缀随之英语化。"},{"era":"MODERN USAGE","en":"From the 19th century onward, economics and sociology made inequality a central measurable term: income inequality, social inequality, global inequality. Mathematics kept the older literal sense in the word 'inequality' for statements such as x < y.","cn":"19 世纪以后，经济学与社会学使 inequality 成为核心的可测量术语：收入不平等、社会不平等、全球不平等。数学则保留较早的字面义，用这个词指 x < y 这类陈述。"}]},"similar":{"note":{"en":"Group one all goes back to Latin aequus 'level', but each word was built on a different base; group two is close in meaning and comes from other roots (par, bilancia, discriminare).","cn":"第一组都可上溯拉丁 aequus「平的」，但各自构建的词基不同；第二组意义相近，来自其他词根（par、bilancia、discriminare）。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"equality","ipa":"/iːˈkwæləti/","tag":"positive base noun","definition":"the state of being equal; formed directly on Latin aequalitas, the word that in- negates","definitionCN":"平等的状态；直接由拉丁 aequalitas 构成，也就是被 in- 否定的那个词"},{"word":"inequity","ipa":"/ɪnˈiːkwəti/","tag":"same root, different noun base","definition":"unfairness or injustice; built on equity (Latin aequitas), not on equality, and it has no mathematical sense","definitionCN":"不公平、不公正；由 equity（拉丁 aequitas）构成，而非 equality，且没有数学义"},{"word":"unequal","ipa":"/ʌnˈiːkwəl/","tag":"Germanic negative prefix","definition":"not equal; the negative is un-, a Germanic prefix, while inequality uses Latin in-","definitionCN":"不平等的；否定前缀是日耳曼语的 un-，而 inequality 用的是拉丁 in-"},{"word":"iniquity","ipa":"/ɪˈnɪkwəti/","tag":"same root, moral sense","definition":"wickedness or gross injustice; from Latin iniquitas, iniquus 'unjust' (in- + aequus), and unrelated to measurable difference","definitionCN":"邪恶、极不公正；来自拉丁 iniquitas、iniquus「不公正」（in- + aequus），与可测量的差距无关"}]},{"heading":"NEAR MEANING","entries":[{"word":"disparity","ipa":"/dɪˈspærəti/","tag":"difference","definition":"a great difference or gap; from Latin dis- 'apart' + par 'equal', a different root from aequus","definitionCN":"巨大差异或差距；来自拉丁 dis-「分开」+ par「相等」，词根与 aequus 不同"},{"word":"imbalance","ipa":"/ˌɪmˈbæləns/","tag":"scale metaphor","definition":"a state in which parts are not in proper proportion; from balance, Latin bilancia 'two scales', a different root","definitionCN":"各部分比例失调的状态；来自 balance、拉丁 bilancia「两秤盘」，词根不同"},{"word":"gap","ipa":"/ɡæp/","tag":"distance","definition":"a space or difference between two things; a plain physical word often used to gloss inequality","definitionCN":"两物之间的空隙或差异；一个常用来解释 inequality 的普通物理词"},{"word":"discrimination","ipa":"/dɪˌskrɪmɪˈneɪʃn/","tag":"unfair treatment","definition":"unfair treatment of people because of a group they belong to; from Latin discriminare 'to distinguish', a different root","definitionCN":"因所属群体而受到的不公平对待；来自拉丁 discriminare「区分」，词根不同"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'not' + aequus 'level' + -ity 'state': inequality is the state of not being on the same level.","cn":"in-「不」+ aequus「平的」+ -ity「状态」：inequality 就是不在同一水平上的状态。"},{"en":"equality and inequality are a minimal pair; the prefix in- simply flips the pan of the scale.","cn":"equality 与 inequality 构成最小对立体；前缀 in- 只是把天平的一端翻过来。"},{"en":"aequus also gives equator and equilibrium: the equator is the line where day and night are 'equal', and equilibrium is an 'equal balance'.","cn":"aequus 还给出 equator 与 equilibrium：赤道是昼夜「相等」的线，平衡是「相等的秤量」。"},{"en":"Picture a balance with unequal weights: the heavier pan sinks, and that tilt is inequality.","cn":"想象一台放着不等重砝码的天平：较重的一端下沉，这个倾斜就是 inequality。"},{"en":"In mathematics the word is literal again: an inequality uses < or > because the two sides are not level.","cn":"在数学里这个词回到字面义：不等式用 < 或 >，因为两边不相等。"}],"abstract":[{"en":"Think of a table with one leg shorter than the others: whatever you place on it slides toward the low end.","cn":"想象一张有一条腿较短的桌子：放在上面的东西都会滑向低的一端。"},{"en":"Think of a staircase where some children start on the top step and others on the bottom, though the race is called equal.","cn":"想象一段楼梯，有些孩子从最高一级起跑，有些从最低一级起跑，而比赛却被称为平等。"},{"en":"Think of a ruler with two scales, one stretched longer than the other: the same length reads as two different numbers.","cn":"想象一把有两套刻度的尺，其中一套被拉得更长：同一长度读出两个不同的数字。"}]},"examples":[{"en":"Income inequality has widened since the 1980s in many rich countries.","cn":"自 1980 年代以来，许多富裕国家的收入不平等扩大了。"},{"en":"The report documents inequality in access to clean water.","cn":"这份报告记录了在获得清洁水源方面的不平等。"},{"en":"Solve the inequality 3x + 2 < 11.","cn":"解不等式 3x + 2 < 11。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（不）+ aequus（平的、相等的）+ -ity（状态）→ 不处于同一水平的状态 → inequality 不平等；数学里就是「不等式」","word":"inequality"},"root":"拉丁否定前缀 in-「不」+ aequalitas「平等」，aequalitas 来自 aequalis「相等的」，再上溯 aequus「平的、均匀的」；经古法语 inégalité 进入英语，后缀 -ity 表状态。","sensesIntro":{"en":"Nine senses all start from a tilted scale: wealth, status, rights, opportunity, health, nations, and bargaining power can all be weighed unevenly, while mathematics turns the tilt into a sign.","cn":"九个义项都从一台倾斜的天平出发：财富、地位、权利、机会、健康、国家与谈判力量都可能被不均地称量，而数学把这个倾斜变成一个符号。"},"semanticMap":{"core":{"en":"CORE IMAGE: a balance whose two pans never settle at the same height.","cn":"核心意象：一台两端始终无法停在同一高度的天平。"},"chain":["LEVEL GROUND","EQUAL","NOT LEVEL","SOCIAL GAP","UNEVEN OUTCOMES","MATHEMATICAL NON-EQUALITY"],"branches":[{"senses":"S01 · S02 · S07","en":"WEALTH AND STATUS: income, class position, and the gap between nations are weighed on the same scale.","cn":"财富与地位：收入、阶级位置以及国家间的差距，都在同一台天平上称量。"},{"senses":"S03 · S04","en":"RIGHTS AND IDENTITY: who is allowed to stand on level legal ground, regardless of gender or race.","cn":"权利与身份：无论性别或种族，谁被允许站在平等的法律地面上。"},{"senses":"S05 · S08","en":"OPPORTUNITY AND OUTCOMES: unequal starting lines produce unequal schooling and unequal health.","cn":"机会与结果：不平等的起跑线产生不平等的教育与不平等的健康。"},{"senses":"S09","en":"POWER: when one party holds more weight in a bargain, the scale itself is unequal.","cn":"权力：当一方在谈判中掌握更多分量时，天平本身就是不平等的。"},{"senses":"S06","en":"MATHEMATICS: the literal statement that two quantities are not equal, written with < or >.","cn":"数学：关于两个量不相等的字面陈述，用 < 或 > 书写。"}]},"affixes":{"intro":{"en":"Inequality is in- plus equality, with -ity naming the state. The negative prefix is Latin in-, not the Germanic un-, which is why the word is inequality and not unequality.","cn":"inequality 是 in- 加 equality，-ity 命名状态。否定前缀是拉丁 in-，而非日耳曼语的 un-，所以这个词是 inequality 而不是 unequality。"},"latinIntro":{"en":"Latin aequus 'level' built aequalis, aequalitas, aequare, and inaequalitas; English descendants include equal, equality, equator, equilibrium, equity, and iniquity. The root appears as aequ- or equ-.","cn":"拉丁 aequus「平的」构成 aequalis、aequalitas、aequare 与 inaequalitas；英语后裔包括 equal、equality、equator、equilibrium、equity 与 iniquity。词根以 aequ- 或 equ- 形式出现。"},"items":[{"word":"equal","structure":"aequ- + -al (Latin aequalis)","meaning":"the same in amount, value, or status","meaningCN":"相等的；平等的（aequ- + -al）","example":"Every citizen should have an equal vote.","exampleCN":"每位公民都应拥有平等的投票权。"},{"word":"equality","structure":"equal + -ity (Latin aequalitas)","meaning":"the state of being equal","meaningCN":"平等（-ity 状态名词）","example":"The law promises equality before the courts.","exampleCN":"法律承诺法庭面前人人平等。"},{"word":"inequality","structure":"in- (not) + equality","meaning":"the state of not being equal","meaningCN":"不平等（in-「不」+ equality）","example":"Inequality between rich and poor grew quickly.","exampleCN":"贫富之间的不平等迅速加剧。"},{"word":"unequal","structure":"un- (not, Germanic) + equal","meaning":"not equal in size, status, or ability","meaningCN":"不平等的（un-「不」，日耳曼语前缀 + equal）","example":"The two sides were unequal in strength.","exampleCN":"双方实力不相等。"},{"word":"unequally","structure":"un- + equal + -ly","meaning":"in an unequal manner","meaningCN":"不平等地（-ly 副词后缀）","example":"Resources were unequally distributed.","exampleCN":"资源分配不均。"},{"word":"equalize","structure":"equal + -ize","meaning":"to make equal","meaningCN":"使平等；使均等（-ize 动词后缀）","example":"The reform aimed to equalize school funding.","exampleCN":"这项改革旨在使学校经费均等。"},{"word":"equalization","structure":"equalize + -ation","meaning":"the act of making equal","meaningCN":"均等化（-ation 过程名词）","example":"Fiscal equalization transfers money to poor regions.","exampleCN":"财政均等化向贫困地区转移资金。"},{"word":"inequity","structure":"in- (not) + equity (Latin aequitas)","meaning":"unfairness, injustice","meaningCN":"不公平（in-「不」+ equity，拉丁 aequitas）","example":"The report exposed inequity in housing policy.","exampleCN":"报告揭露了住房政策中的不公平。"},{"word":"iniquity","structure":"in- + iquus (Latin iniquus, unjust)","meaning":"wickedness, gross injustice","meaningCN":"邪恶；极不公正（in- + 拉丁 iniquus「不公正」）","example":"They protested against the iniquity of the law.","exampleCN":"他们抗议这部法律的不公。"}],"latinEntries":[{"word":"aequus","structure":"aequus (level, equal)","meaning":"level, flat, even, equal","meaningCN":"平的；平坦的；均匀的；相等的"},{"word":"aequalis","structure":"aequus + -alis","meaning":"equal, like, of the same level","meaningCN":"相等的；相同的；同水平的"},{"word":"aequalitas","structure":"aequalis + -itas","meaning":"equality, evenness","meaningCN":"平等；均匀"},{"word":"inaequalitas","structure":"in- (not) + aequalitas","meaning":"unevenness, inequality","meaningCN":"不均；不平等"}]}},{"word":"inference","ipa_uk":"/ˈɪnfərəns/","ipa_us":"/ˈɪnfərəns/","definition_zh":"推论；推断；推理过程；结论","definition_en":"a conclusion reached from evidence and reasoning; the process of drawing such a conclusion","core_image":"从散落的线索中拉出一条通向结论的线","scene":"From the muddy footprints, the detective drew an inference about the intruder's height, which a security camera later confirmed.","sceneCN":"这里 inference 是「推断出的结论」（第 2 个义项：根据证据得出的判断）；句意：侦探根据泥泞的脚印推断出入侵者的身高，这一推断后来被监控摄像头证实。图中可辨识物件：脚印、放大镜、身高标尺、摄像头。","pos":[{"tag":"n.","zh":"推论；推断；推理过程；结论"}],"collocations":[{"phrase":"draw an inference","zh":"作出推论"},{"phrase":"make an inference","zh":"进行推断"},{"phrase":"logical inference","zh":"逻辑推论"},{"phrase":"statistical inference","zh":"统计推断"},{"phrase":"by inference","zh":"通过推断"},{"phrase":"a valid inference","zh":"有效的推论"}],"forms":[{"label":"复数","form":"inferences"}],"derivatives":[{"word":"infer","pos":"v.","zh":"推断；推论"},{"word":"inferential","pos":"adj.","zh":"推论的；推断的"},{"word":"inferentially","pos":"adv.","zh":"在推论上"},{"word":"inferable","pos":"adj.","zh":"可推断的"},{"word":"inferencing","pos":"n.","zh":"推理过程（语言与人工智能领域）"}],"senses":[{"no":"01","title":"The process of drawing a conclusion","titleCN":"推断过程；推理","definition":"the mental process of reaching a conclusion by reasoning from evidence rather than by direct observation","definitionCN":"根据证据推理而非直接观察得出结论的心智过程","example":"Inference is what fills the gaps between the facts we are given.","exampleCN":"推断正是填补我们所获事实之间空缺的过程。","why":"Latin in- means 'into' and ferre means 'carry'. The mind carries the evidence inward and works it into a judgement, so the process itself is an inference.","whyCN":"拉丁 in- 意为「向内」，ferre 意为「携带」。心智把证据携带进来并加工成判断，因此这个过程本身就是 inference。"},{"no":"02","title":"The conclusion that is reached","titleCN":"推断出的结论","definition":"the judgement or conclusion produced by inferring","definitionCN":"由推断产生的判断或结论","example":"My inference was that the meeting had been cancelled.","exampleCN":"我的推断是会议已被取消。","why":"The -ence suffix, from Latin -entia, names both the action and its result. What has been carried in is also an inference, just as a building is both the act and the thing built.","whyCN":"来自拉丁 -entia 的后缀 -ence 同时命名动作与其结果。被携带进来的东西也是 inference，正如建筑既是建造行动也是建筑物。"},{"no":"03","title":"A formal step in logic","titleCN":"逻辑学中的推论","definition":"a conclusion derived from premises by a formal rule of logic","definitionCN":"依据形式逻辑规则从前提出推导出的结论","example":"If all men are mortal and Socrates is a man, the inference is that Socrates is mortal.","exampleCN":"如果所有人都会死而苏格拉底是人，那么推论就是苏格拉底会死。","why":"Logic formalizes the carrying: premises are placed in, and only the conclusions the rules permit are carried out. The name for the step is inference.","whyCN":"逻辑学把这种携带形式化：前提被放进去，只有规则允许的结论才能被带出来。这一步的名称就是 inference。"},{"no":"04","title":"Statistical inference","titleCN":"统计推断","definition":"the use of sample data to draw conclusions about a larger population","definitionCN":"利用样本数据对更大总体得出结论","example":"Statistical inference tells us how confident we can be in the estimate.","exampleCN":"统计推断告诉我们能对这个估计有多大信心。","why":"The sample is carried inward as evidence, and a statement about the whole population is carried out. The same verb covers a poll and a syllogism.","whyCN":"样本作为证据被携带进来，关于整个总体的陈述被带出去。同一个动词既涵盖民意调查，也涵盖三段论。"},{"no":"05","title":"A meaning understood but not stated","titleCN":"语用推理；言外之意","definition":"the implied meaning that a listener derives from a speaker's words in context","definitionCN":"听者根据语境从说话者话语中推导出的隐含意义","example":"The inference from 'some students passed' is that not all did.","exampleCN":"从「有些学生通过了」推断出的言外之意是并非全部都通过了。","why":"What the speaker carries in but does not say aloud becomes an inference for the listener. The mind supplies a conclusion the words only point to.","whyCN":"说话者带入却未说出口的内容，对听者而言就成了 inference。心智补充出一个话语仅指向的结论。"},{"no":"06","title":"An everyday guess from signs","titleCN":"日常凭迹象的推断","definition":"a practical conclusion drawn from visible signs or indirect clues in ordinary life","definitionCN":"在日常生活中根据可见迹象或间接线索得出的实际判断","example":"From the empty parking lot, she made an inference that the shop had closed early.","exampleCN":"从空荡的停车场，她推断商店提前关门了。","why":"Everyday reasoning is the same motion at a smaller scale: a sign is carried in, a conclusion comes out. No formal rule is needed for the verb to apply.","whyCN":"日常推理是同一动作在更小尺度上的重复：迹象被携带进来，结论被带出去。无需形式规则，这个动词同样适用。"},{"no":"07","title":"Machine inference in computing","titleCN":"机器推理；模型推断","definition":"the process by which a trained model produces an output from new input data","definitionCN":"训练好的模型根据新的输入数据产生输出的过程","example":"The model's inference took only milliseconds on the phone.","exampleCN":"这个模型在手机上的推断只花了几毫秒。","why":"Engineers borrowed the word because the machine does exactly what the mind does: input is carried through a network, and a conclusion is emitted. The metaphor became a technical term.","whyCN":"工程师借用这个词，因为机器所做的正是心智所做的：输入被携带穿过网络，结论被输出。这个隐喻成了技术术语。"},{"no":"08","title":"A factual conclusion in law","titleCN":"法律上根据证据的推定","definition":"a conclusion about facts that a court or investigator draws from evidence rather than direct proof","definitionCN":"法院或调查者根据证据而非直接证明对事实得出的结论","example":"The jury was allowed to draw an inference from the defendant's flight.","exampleCN":"陪审团被允许从被告的逃逸行为中作出推断。","why":"A court cannot carry the past into the room; it carries evidence in and asks what conclusion may be drawn. That permitted step is an inference.","whyCN":"法庭无法把过去带进房间；它把证据携带进来，并追问可以得出什么结论。这个被允许的步骤就是 inference。"},{"no":"09","title":"Something implied rather than said","titleCN":"暗示；隐含之意","definition":"an idea that is suggested by a statement or situation without being explicitly expressed","definitionCN":"由陈述或情境暗示而未被明确表达的观念","example":"The report's inference was clear: the policy had failed, though it never said so.","exampleCN":"报告的言外之意很清楚：政策已经失败，尽管它从未明说。","why":"Here the conclusion stays folded inside the evidence instead of being stated. The word names what the mind carries out even when no sentence carries it.","whyCN":"此处结论折叠在证据之中，而未被明说。这个词命名的是即便没有句子承载、心智仍会带出的东西。"}],"etymology":{"intro":{"en":"Inference is the noun of the verb infer, from Latin inferre 'to bring in, conclude', itself in- 'into' + ferre 'to carry'. The suffix -ence comes from Latin -entia and names an action or state.","cn":"inference 是动词 infer 的名词，infer 来自拉丁 inferre「带入、推论」，由 in-「向内」+ ferre「携带」构成。后缀 -ence 来自拉丁 -entia，命名动作或状态。"},"items":[{"era":"LATIN ferre","en":"ferre meant 'to carry, bear'. It is one of the most productive verbs in Latin, supplying a whole family of English words through different prefixes.","cn":"ferre 意为「携带、承受」。它是拉丁语中构词能力最强的动词之一，通过不同前缀为英语提供了整个词族。"},{"era":"LATIN inferre","en":"in- 'into' + ferre produced inferre, 'to bring in, introduce, and in logic to conclude'. The mind carries the evidence in and arrives at a judgement.","cn":"in-「向内」+ ferre 构成 inferre，意为「带入、引入，在逻辑上指推论」。心智把证据携带进来，从而抵达一个判断。"},{"era":"LATIN inferentia","en":"Late Latin inferentia named the act or result of bringing in a conclusion. This is the model for the English noun, though English also formed inference directly from infer.","cn":"晚期拉丁 inferentia 命名「带入结论」的动作或结果。这是英语名词的样板，不过英语也直接在 infer 上构成了 inference。"},{"era":"ENGLISH verb infer","en":"English infer is recorded in the 16th century, borrowed from Latin inferre. At first it meant 'to bring in' as well as 'to conclude'; the logical sense became dominant.","cn":"英语动词 infer 在 16 世纪有记录，借自拉丁 inferre。最初它既指「带入」，也指「推论」；逻辑义后来占据主导。"},{"era":"SUFFIX -ence","en":"-ence descends from Latin -entia through French -ence. It builds nouns of action or state, as in prefer → preference and refer → reference.","cn":"-ence 经法语 -ence 上溯拉丁 -entia。它构成动作或状态名词，如 prefer → preference、refer → reference。"},{"era":"MODERN EXPANSION","en":"In the 19th and 20th centuries inference became a technical term in logic, statistics, linguistics, law, and computing. Each field kept the same core motion: carrying evidence into a conclusion.","cn":"19 与 20 世纪，inference 成为逻辑学、统计学、语言学、法学与计算领域的技术术语。每个领域都保留同一核心动作：把证据携带进结论。"}]},"similar":{"note":{"en":"Group one all come from Latin ferre 'to carry' but with different prefixes; reference, conference, and transfer are not derived from infer. Group two is close in meaning and comes from other roots (ducere, claudere, plicare, ratio).","cn":"第一组都来自拉丁 ferre「携带」，但前缀不同；reference、conference、transfer 并非由 infer 派生。第二组意义相近，来自其他词根（ducere、claudere、plicare、ratio）。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"infer","ipa":"/ɪnˈfɜː(r)/","tag":"base verb","definition":"to reach a conclusion from evidence; from Latin inferre, in- 'into' + ferre 'carry'","definitionCN":"根据证据得出判断；来自拉丁 inferre，in-「向内」+ ferre「携带」"},{"word":"reference","ipa":"/ˈrefrəns/","tag":"different prefix, not a derivative","definition":"a mention or a source cited; from Latin referre 'to carry back' (re- 'back' + ferre), not from infer","definitionCN":"提及或引用的来源；来自拉丁 referre「带回」（re-「回」+ ferre），并非由 infer 派生"},{"word":"conference","ipa":"/ˈkɒnfərəns/","tag":"different prefix","definition":"a meeting for discussion; from Latin conferre 'to bring together' (con- 'together' + ferre)","definitionCN":"为讨论而举行的会议；来自拉丁 conferre「带到一起」（con-「一起」+ ferre）"},{"word":"transfer","ipa":"/trænsˈfɜː(r)/","tag":"different prefix","definition":"to move something from one place to another; from Latin transferre (trans- 'across' + ferre)","definitionCN":"把某物从一处移到另一处；来自拉丁 transferre（trans-「越过」+ ferre）"}]},{"heading":"NEAR MEANING","entries":[{"word":"deduction","ipa":"/dɪˈdʌkʃn/","tag":"formal reasoning","definition":"a conclusion reached by strict logical rule; from Latin deducere 'to lead down', and narrower than inference","definitionCN":"按严格逻辑规则得出的结论；来自拉丁 deducere「引下」，比 inference 范围窄"},{"word":"conclusion","ipa":"/kənˈkluːʒn/","tag":"end point","definition":"the judgement reached at the end of reasoning; from Latin concludere 'to shut up, close', and it names the result rather than the process","definitionCN":"推理结束时达成的判断；来自拉丁 concludere「关闭、收束」，命名结果而非过程"},{"word":"implication","ipa":"/ˌɪmplɪˈkeɪʃn/","tag":"what is implied","definition":"something suggested without being stated; from Latin implicare 'to fold in', and closer to the 'implied meaning' sense","definitionCN":"未明说而被暗示的东西；来自拉丁 implicare「折入」，更接近「言外之意」义"},{"word":"reasoning","ipa":"/ˈriːzənɪŋ/","tag":"thinking process","definition":"the process of thinking logically; from Latin ratio 'reckoning', and broader than a single inference","definitionCN":"逻辑思考的过程；来自拉丁 ratio「计算」，比单次推论更广"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'into' + ferre 'carry': inference is carrying evidence into the mind and arriving at a conclusion.","cn":"in-「向内」+ ferre「携带」：inference 就是把证据携带进头脑并抵达结论。"},{"en":"infer is the verb and inference is the noun, just as prefer gives preference and refer gives reference.","cn":"infer 是动词，inference 是名词，正如 prefer 给出 preference、refer 给出 reference。"},{"en":"Keep infer and refer apart: in- carries inward, re- carries back. Reference is not a relative of inference in meaning.","cn":"把 infer 与 refer 分清：in- 向内携带，re- 向后带回。reference 与 inference 在意义上并非亲属。"},{"en":"A detective carrying footprints into a conclusion is performing an inference in the plainest sense.","cn":"侦探把脚印带进结论，就是在做最普通意义上的 inference。"},{"en":"Statistics and computing use the same verb: input data is carried in, and a conclusion is carried out.","cn":"统计学与计算用的是同一个动词：把输入数据带进来，再把结论带出去。"}],"abstract":[{"en":"Think of a thread pulled from scattered clues until it reaches a knot: the thread is the inference, the knot the conclusion.","cn":"想象一根线从散落的线索中被拉出，直到抵达一个结：线是推断过程，结是结论。"},{"en":"Think of a courtroom where each piece of evidence is carried to the judge's bench; the verdict is the inference written down.","cn":"想象法庭上每件证据都被送到法官席；判决就是写下来的推论。"},{"en":"Think of a mill: grain goes in at the top, flour comes out below. Data goes in, inference comes out.","cn":"想象一座磨坊：谷物从上面进，面粉从下面出。数据进去，推论出来。"}]},"examples":[{"en":"From the drop in sales, we can infer that the advertising campaign failed.","cn":"从销售额下降可以推断，那场广告活动失败了。"},{"en":"Statistical inference allows researchers to generalize from a sample.","cn":"统计推断使研究者能够从样本推广到总体。"},{"en":"Her silence was taken as an inference that she disagreed.","cn":"她的沉默被理解为她不同意的暗示。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（向内）+ ferre（携带）→ infer 把证据带进头脑、得出结论；-ence 名词 → inference 推论、推断过程。别和 reference（re- 带回）混。","word":"inference"},"root":"拉丁 in-「向内」+ ferre「携带」构成 inferre「带入、推论」，加拉丁 -entia（英语 -ence）构成名词；核心动作是「把证据携带进结论」。与 reference 的 re-「带回」路径不同。","sensesIntro":{"en":"Nine senses all keep one motion: evidence is carried in and a conclusion comes out. The carrying may happen in logic, in a sample, in a sentence, in a court, or in a machine.","cn":"九个义项都保留同一个动作：证据被携带进来，结论被带出。这个携带可能发生在逻辑、样本、句子、法庭或机器之中。"},"semanticMap":{"core":{"en":"CORE IMAGE: a line drawn from scattered clues to a single knot of conclusion.","cn":"核心意象：从散落线索拉向单一结论之结的一条线。"},"chain":["CARRY IN","EVIDENCE","DRAW A CONCLUSION","THE CONCLUSION ITSELF","FORMAL AND STATISTICAL RULES","IMPLIED MEANING"],"branches":[{"senses":"S01 · S02","en":"ACT AND PRODUCT: the mental carrying and the judgement it delivers.","cn":"动作与产物：心智的携带过程及它所交付的判断。"},{"senses":"S03 · S04","en":"FORMAL RULES: logic and statistics prescribe how evidence may be carried to a conclusion.","cn":"形式规则：逻辑学与统计学规定证据应如何被带到结论。"},{"senses":"S05 · S09","en":"LANGUAGE: listeners carry words into implied meanings that were never spoken.","cn":"语言：听者把话语带进从未说出的隐含意义。"},{"senses":"S06 · S08","en":"SIGNS AND EVIDENCE: footprints or testimony are carried into a practical judgement.","cn":"迹象与证据：脚印或证词被带进一个实际判断。"},{"senses":"S07","en":"MACHINES: a model carries input data into an output label, the same motion in silicon.","cn":"机器：模型把输入数据带进输出标签，同一动作发生在硅片之中。"}]},"affixes":{"intro":{"en":"Inference is infer + -ence. The prefix in- and the verb ferre are Latin; -ence is the Latin -entia suffix for an action or state, also visible in preference and conference.","cn":"inference 是 infer + -ence。前缀 in- 与动词 ferre 属拉丁语；-ence 是拉丁 -entia 的动作或状态名词后缀，也见于 preference 与 conference。"},"latinIntro":{"en":"Latin ferre 'to carry' produced a large family through prefixes: inferre, referre, conferre, transferre, praeferre. The root appears as fer-, lat- (from the past participle latus), or -late.","cn":"拉丁 ferre「携带」通过前缀产生庞大词族：inferre、referre、conferre、transferre、praeferre。词根以 fer-、lat-（来自过去分词 latus）或 -late 形式出现。"},"items":[{"word":"infer","structure":"in- (into) + ferre","meaning":"to bring evidence in and reach a conclusion","meaningCN":"推断；推论（in-「向内」+ ferre「携带」）","example":"We can infer from the data that demand is falling.","exampleCN":"我们可以从数据推断需求正在下降。"},{"word":"inference","structure":"infer + -ence (Latin -entia)","meaning":"the act or result of inferring","meaningCN":"推论；推断（-ence 动作或状态名词）","example":"Her inference was based on very little evidence.","exampleCN":"她的推论依据的证据很少。"},{"word":"inferential","structure":"inference + -ial","meaning":"relating to inference","meaningCN":"推论的（-ial 形容词后缀）","example":"The argument is inferential rather than direct.","exampleCN":"这一论证是推论性的，而非直接的。"},{"word":"inferentially","structure":"inferential + -ly","meaning":"by means of inference","meaningCN":"在推论上；通过推断（-ly 副词后缀）","example":"The conclusion is reached inferentially.","exampleCN":"该结论是通过推断得出的。"},{"word":"inferable","structure":"infer + -able","meaning":"able to be inferred","meaningCN":"可推断的（-able 形容词后缀）","example":"It is inferable that the letter was never sent.","exampleCN":"可以推断这封信从未寄出。"},{"word":"inferencing","structure":"inference + -ing","meaning":"the ongoing process of drawing inferences, used in linguistics and computing","meaningCN":"推理过程（语言学与计算领域用语，-ing 名词化）","example":"Readers use inferencing to fill gaps in a text.","exampleCN":"读者用推理来填补文本中的空缺。"},{"word":"refer","structure":"re- (back) + ferre","meaning":"to send back, point to, or consult","meaningCN":"提及；参考（re-「回」+ ferre，方向与 infer 相反）","example":"The footnote refers to an earlier study.","exampleCN":"脚注提到了一项较早的研究。"},{"word":"reference","structure":"refer + -ence","meaning":"a mention or a cited source","meaningCN":"提及；参考文献（-ence 名词后缀）","example":"Please include a reference for each claim.","exampleCN":"请为每项主张附上参考文献。"},{"word":"conference","structure":"con- (together) + ferre + -ence","meaning":"a meeting where people bring ideas together","meaningCN":"会议（con-「一起」+ ferre「携带」+ -ence）","example":"Scholars met at the annual conference.","exampleCN":"学者们在年会上相聚。"}],"latinEntries":[{"word":"ferre","structure":"ferre (to carry)","meaning":"to carry, bear, bring","meaningCN":"携带；承受；带来"},{"word":"inferre","structure":"in- (into) + ferre","meaning":"to bring in, introduce, conclude","meaningCN":"带入；引入；推论"},{"word":"inferentia","structure":"inferre + -entia","meaning":"a bringing in; a conclusion","meaningCN":"带入；结论"},{"word":"referre","structure":"re- (back) + ferre","meaning":"to carry back, refer","meaningCN":"带回；提及"}]}},{"word":"influential","ipa_uk":"/ˌɪnfluˈenʃl/","ipa_us":"/ˌɪnfluˈenʃl/","definition_zh":"有影响力的；有势力的；举足轻重的；起作用的","definition_en":"having a strong effect on people, events, or the way something develops; carrying weight or power in a particular field","core_image":"一颗石子落进静水，涟漪一圈圈推到岸边——看不见的水流把力量送到远处，岸上的东西因此改变","scene":"Her influential report on urban heat changed the city's building code within a year.","sceneCN":"这里 influential 是「有影响力的」（第 1 个义项：能改变事件走向的）；句意：她关于城市高温的报告很有影响力，一年内就改变了城市的建筑规范。图中可辨识物件：报告封面、市政厅、修改后的规范文本。","pos":[{"tag":"adj.","zh":"有影响力的；有势力的；举足轻重的"}],"collocations":[{"phrase":"influential figure","zh":"有影响力的人物"},{"phrase":"highly influential","zh":"极具影响力的"},{"phrase":"influential in shaping","zh":"在塑造某事物方面有影响力的"},{"phrase":"influential voice","zh":"有分量的声音"},{"phrase":"politically influential","zh":"在政治上很有势力的"},{"phrase":"an influential factor","zh":"一个有影响的因素"}],"forms":[{"label":"比较级","form":"more influential"},{"label":"最高级","form":"most influential"},{"label":"副词","form":"influentially"}],"derivatives":[{"word":"influence","pos":"n./v.","zh":"影响；影响力；影响（某人）"},{"word":"influencer","pos":"n.","zh":"有影响力者；网络影响者"},{"word":"influentially","pos":"adv.","zh":"有影响力地"},{"word":"uninfluenced","pos":"adj.","zh":"未受影响的"},{"word":"influenza","pos":"n.","zh":"流行性感冒（同源异义）"}],"senses":[{"no":"01","title":"Producing an effect on events","titleCN":"有影响力的：能改变事情走向的","definition":"having the power to affect how events or situations develop","definitionCN":"有能力影响事件或局势发展方向的","example":"The drought was an influential factor in the price of grain.","exampleCN":"干旱是影响谷物价格的一个因素。","why":"Medieval Latin influentia named an invisible current flowing from the stars into earthly things and bending their fate. Remove the stars and the core remains: something flows in and changes the outcome.","whyCN":"中世纪拉丁 influentia 指从星体流入人间、拨动命运的一股无形水流。把星体去掉，核心仍在：某物流进来，结果因此改变。"},{"no":"02","title":"Able to sway a decision","titleCN":"能左右决定的：说话能进到决策那间屋里","definition":"able to affect the choice or judgment of a person or group","definitionCN":"能够影响个人或群体作出选择或判断的","example":"Three influential shareholders opposed the merger.","exampleCN":"三位有影响力的股东反对这次合并。","why":"A decision is a channel, and an influential person is a current that enters it before the vote is cast. The word measures inflow, not rank.","whyCN":"决定是一条水道，有影响力的人是在投票之前流入这条水道的一股水流。这个词衡量的是流入量，不是职位高低。"},{"no":"03","title":"Shaping public opinion","titleCN":"能左右舆论的：把风向带偏或带正","definition":"able to change what many people think or believe","definitionCN":"能够改变许多人想法或信念的","example":"The paper remained influential in shaping how readers saw the war.","exampleCN":"这家报纸在塑造读者对战争的看法上始终很有影响力。","why":"The astral current became metaphorical weather in the sixteenth century: minds were said to stand under the influence of persons, parties, or papers. Opinion is the field the current crosses.","whyCN":"16 世纪，星体水流变成了比喻意义上的天气：人们说头脑处在人物、党派或报纸的「影响」之下。舆论就是这股水流经过的田野。"},{"no":"04","title":"Commanding weight and prestige","titleCN":"举足轻重的：在一个领域里有分量","definition":"respected and listened to because of one's standing in a field","definitionCN":"因在某一领域中的地位而受尊重、被倾听的","example":"She became an influential critic of modern architecture.","exampleCN":"她成了现代建筑界一位举足轻重的评论家。","why":"Such a person has a large inflow into the common affairs of a field; prestige is the visible sign that others let that current pass.","whyCN":"这样的人对一个领域的公共事务有大量流入；威望就是别人允许这股水流通过的可见标志。"},{"no":"05","title":"Leaving a mark on later work","titleCN":"影响深远的：后来的作品顺着它流下来","definition":"having a lasting effect on later works, ideas, or styles","definitionCN":"对后来的作品、观念或风格产生持久影响的","example":"His influential book is still cited by historians today.","exampleCN":"他那本影响深远的著作至今仍被历史学家引用。","why":"Works downstream carry the mark of the work upstream. Scholars call a book influential because later books flow from it, the same water image read across time.","whyCN":"下游的作品带着上游作品的印记。学者说一本书有影响力，是因为后来的书从它流出，同一个水的意象放到了时间上。"},{"no":"06","title":"Contributing to a result","titleCN":"起促成作用的：往结果里添了一股水","definition":"playing a part in bringing about a result, without being the only cause","definitionCN":"在促成某一结果中起作用，但不是唯一原因的","example":"Parental reading habits are influential in a child's vocabulary growth.","exampleCN":"父母的阅读习惯对孩子的词汇增长有促成作用。","why":"Here the word names one current among several that feed a result. An influential factor does not decide alone; it adds volume to the flow.","whyCN":"此处这个词指汇入结果的几股水流之一。有影响的因素并不独自决定结果，它只是给水流增加了水量。"},{"no":"07","title":"Carrying weight in policy","titleCN":"对政策有影响力的：能推动规则转向","definition":"able to affect official decisions, laws, or the direction of an institution","definitionCN":"能够影响官方决定、法律或机构方向的","example":"The committee is influential in setting national health policy.","exampleCN":"该委员会在制定国家卫生政策方面很有影响力。","why":"Institutions are gates that direct large flows of money and rules. An influential body is one whose current reaches the gate where decisions are made.","whyCN":"机构是引导资金与规则大流的闸门。有影响力的机构，其水流能抵达作出决定的那道闸门。"},{"no":"08","title":"Spreading through a group","titleCN":"在群体中起带动作用的","definition":"able to spread a habit, style, or attitude through a group","definitionCN":"能够使某种习惯、风格或态度在群体中传播开的","example":"Her influential style of teaching was copied across the department.","exampleCN":"她那种有带动作用的教学风格被整个系效仿。","why":"When a style is influential in a group, it propagates like a current through connected channels rather than by command.","whyCN":"当一种风格在一个群体里有影响力时，它像水流一样沿相连的渠道传播，而不是靠命令推行。"},{"no":"09","title":"Backed by connections","titleCN":"有势力的：靠关系能办成事","definition":"having personal power that comes from who one knows and can ask","definitionCN":"因认识谁、能求到谁而拥有的个人势力","example":"He was influential enough to get the permit approved in a week.","exampleCN":"他很有势力，一周内就把许可证办了下来。","why":"The older sense of influence as personal ascendancy survives in the phrase 'a man of influence'. Connections are channels through which a request can flow out and return as a favour.","whyCN":"influence 旧有的「个人支配力」义保存在「a man of influence」这一说法里。关系就是渠道，请求沿它流出，再以人情的形式流回来。"}],"etymology":{"intro":{"en":"Influential is the adjective of influence, from Medieval Latin influentia 'an inflow'. The word began as astrology: a fluid current from the stars was thought to enter a person and shape his fate. The modern sense keeps the current and drops the stars.","cn":"influential 是 influence 的形容词。influence 来自中世纪拉丁 influentia「流入」，最初是占星术语：人们认为星体流出的某种流质进入人体、决定其命运。现代义保留了「流」，去掉了星体。"},"items":[{"era":"LATIN VERB influere","en":"influere is in- 'into' plus fluere 'to flow': to flow into. The image is water entering a vessel or a field, quietly changing what it touches.","cn":"influere 由 in-「向内」加 fluere「流」构成，意为「流入」。意象是水进入容器或田地，悄悄改变所触之物。"},{"era":"MEDIEVAL LATIN influentia","en":"influentia was an astrological term for the emanation believed to flow from the stars into bodies on earth. This astrological use is generally regarded as the direct source of the English word's 'influence' sense.","cn":"influentia 是占星术语，指一般认为从星体流向地上万物的流射。这一占星用法一般被认为是英语 influence「影响力」义的直接来源。"},{"era":"OLD FRENCH influence","en":"Old French took influence in the fourteenth century with the astral sense. English borrowed it then, first for the power of stars over human affairs.","cn":"古法语在 14 世纪借入 influence，保留星体义。英语随即借入，最初指星体对人类事务的支配力。"},{"era":"SECULAR SHIFT","en":"In the sixteenth century the stars faded and the current stayed: a person, a court, or a book could exert influence, meaning an invisible power flowing into events.","cn":"16 世纪，星体淡出，水流留下：一个人、一个宫廷或一本书都能施加 influence，指一股流入事件的无形力量。"},{"era":"SUFFIX -al","en":"Latin -alis, through French -al, turned the noun influence into the adjective influential: 'having or exerting influence'. The adjective is recorded later than the noun.","cn":"拉丁 -alis 经法语 -al 把名词 influence 变成形容词 influential，意为「具有或施加影响力的」。形容词的记录晚于名词。"},{"era":"MODERN WIDE USE","en":"Today the word covers persons, works, factors, institutions, and styles. Influenza is a doublet from the same astral word, but it names a disease, not a power.","cn":"如今这个词覆盖人物、作品、因素、机构和风格。influenza 是同一个占星词的分支双词，但它指的是疾病，不是力量。"}]},"similar":{"note":{"en":"The first group shares the Latin flow-root fluere or looks close to it, and the differences lie in their prefixes. The second group contains words close in effect or standing but built on other roots.","cn":"第一组共享拉丁词根 fluere「流」，或在拼写上贴近它，区别在各自的前缀。第二组是效果或地位相近、但词根不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"influence","ipa":"/ˈɪnfluəns/","tag":"base noun and verb","definition":"the power to affect people or events; to affect them. It is the noun from which influential is built with -al.","definitionCN":"影响他人或事件的力量；影响。它是 influential 加 -al 所依据的名词。"},{"word":"influenza","ipa":"/ˌɪnfluˈenzə/","tag":"same astral source, different meaning","definition":"a contagious viral illness. Italian influenza borrowed the Medieval Latin word for astral influence, then narrowed it to a disease that was thought to come from the stars.","definitionCN":"一种传染性病毒疾病。意大利语 influenza 借用了表示星体影响的中世纪拉丁词，后来缩小为一种被认为来自星体的疾病。"},{"word":"fluid","ipa":"/ˈfluːɪd/","tag":"same flow-root, no prefix","definition":"a substance that flows; flowing. It comes from Latin fluidus, from fluere 'to flow', the same root without in-.","definitionCN":"流体；流动的。来自拉丁 fluidus，再上溯 fluere「流」，同根但没有 in- 前缀。"},{"word":"affluent","ipa":"/ˈæfluənt/","tag":"same root, different prefix","definition":"wealthy, having a great flow of money. It is ad- 'to' plus fluere 'flow': a flow toward someone, not into them.","definitionCN":"富裕的，钱财大量流入的。它是 ad-「向」加 fluere「流」：水流向某人，而不是流入某人。"}]},{"heading":"NEAR MEANING","entries":[{"word":"powerful","ipa":"/ˈpaʊəfl/","tag":"force and control","definition":"having great power or control. It stresses the ability to command, while influential stresses the ability to affect.","definitionCN":"有权势的；有强大控制力的。它强调发号施令的能力，而 influential 强调产生影响的能力。"},{"word":"persuasive","ipa":"/pəˈsweɪsɪv/","tag":"winning agreement","definition":"good at making people agree. It aims at convincing a mind, a narrower act than exerting general influence.","definitionCN":"有说服力的；善于使人认同的。它瞄准的是说服一个头脑，比施加广泛影响的范围窄。"},{"word":"prominent","ipa":"/ˈprɒmɪnənt/","tag":"visible standing","definition":"important and well known. It describes visibility and rank rather than the flow of effect into events.","definitionCN":"显赫的；著名的。它描述的是可见度与地位，而不是作用力流入事件的过程。"},{"word":"significant","ipa":"/sɪɡˈnɪfɪkənt/","tag":"importance","definition":"important enough to matter. It measures weight or consequence, not the invisible current that influential keeps in view.","definitionCN":"重要的；有分量的。它衡量的是重要性或后果，而不是 influential 所保留的那股无形水流。"}]}]},"mnemonics":{"normalIntro":{"en":"The family is one current seen at different points: the flow itself, the thing it enters, and the mark it leaves.","cn":"这个词族就是同一股水流在不同位置上的样子：水流本身、它进入的东西，以及它留下的痕迹。"},"normal":[{"en":"in- 'into' + fluere 'flow': influence is a current flowing into a person or an event.","cn":"in-「向内」+ fluere「流」：influence 就是流进一个人或一件事的水流。"},{"en":"-al makes the adjective: influential means having or sending that current.","cn":"-al 构成形容词：influential 意为拥有或送出那股水流。"},{"en":"The root flu- reappears in fluid, fluent, affluent and influenza; all keep some idea of flowing.","cn":"词根 flu- 在 fluid、fluent、affluent、influenza 中重现，都保留着「流」的某种含义。"},{"en":"The original current came from the stars; astrology gave the word its shape before politics borrowed it.","cn":"最早的水流来自星体；在政治借走它之前，占星术先给了这个词形状。"},{"en":"influential and influenza are doublets: one is power flowing in, the other a disease once blamed on the stars.","cn":"influential 与 influenza 是同源双词：一个是流入的力量，一个是曾被归咎于星体的疾病。"}],"abstract":[{"en":"Think of an open window on a cold day: no one sees the air, but the room's temperature changes. Influence works like that.","cn":"想象冷天里一扇开着的窗：没人看得见空气，但房间的温度变了。影响力就是这样起作用的。"},{"en":"Think of a river feeding fields far downstream: the field never meets the source, yet its harvest depends on it.","cn":"想象一条河滋养远在下游的田地：田地从未见过源头，收成却依赖它。"},{"en":"Think of a small hand on a ship's tiller: almost no force, a very large turn.","cn":"想象一只小手放在大船的舵柄上：力气极小，转向却极大。"}]},"examples":[{"en":"The report proved highly influential in the debate over housing policy.","cn":"这份报告在住房政策辩论中被证明极具影响力。"},{"en":"He grew into one of the most influential figures in contemporary music.","cn":"他成长为当代音乐界最有分量的人物之一。"},{"en":"Early reading habits are influential in shaping a child's later vocabulary.","cn":"早期阅读习惯对塑造孩子日后的词汇量有促成作用。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in（向内）+ flu（流）+ ential（形容词）——像一股看不见的水流进屋里，把温度改了，这就是「有影响力的」。同根 flu 见 fluid、fluent；influenza 同源，却指流感。","word":"influential"},"root":"拉丁 influere「流入」（in-「向内」+ fluere「流」）→ 中世纪拉丁 influentia「流入、星体流出的影响力」→ 古法语 influence → 英语 influence + -al（拉丁 -alis）；与 fluid、fluent、affluent 同根，与 influenza 同源异义。占星来源一般认为是现代「影响力」义的直接出处。","sensesIntro":{"en":"Nine senses all keep one image: an invisible current entering something and changing it. The current may enter an event, a decision, a mind, a field, a later work, a group, or a channel of favours.","cn":"九个义项都守住一个意象：一股看不见的水流进入某物并改变它。这股水流可以进入事件、决定、头脑、领域、后世作品、群体或人情渠道。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unseen current flowing into a thing and altering what it becomes.","cn":"核心意象：一股看不见的水流进入某物，改变它后来的样子。"},"chain":["AN UNSEEN CURRENT","FLOWING INTO A THING","CHANGING THE OUTCOME","ENTERING A MIND","WEIGHT THAT MOVES DECISIONS","A MARK LEFT DOWNSTREAM"],"branches":[{"senses":"S01 · S06","en":"CAUSE AND CONTRIBUTION: a current that changes events, and one that adds volume to a result among other causes.","cn":"原因与促成：一股改变事件的水流，以及在其他原因之间为结果添水量的一股。"},{"senses":"S02 · S07","en":"THE DECISION CHANNEL: influence that reaches a vote, and influence that reaches the gate of policy.","cn":"决策渠道：抵达投票的影响力，以及抵达政策闸门的影响力。"},{"senses":"S03 · S08","en":"THE SOCIAL FIELD: a current crossing public opinion, and one spreading a style through a group.","cn":"社会场域：穿过舆论的水流，以及在群体中传播风格的水流。"},{"senses":"S04 · S09","en":"PERSONAL WEIGHT: standing that makes others listen, and connections that make requests flow.","cn":"个人分量：让别人愿意听的地位，以及让请求流动起来的关系。"},{"senses":"S05","en":"DOWNSTREAM TIME: a work whose current still feeds later works.","cn":"下游的时间：其水流至今仍在滋养后世作品的一部作品。"}]},"affixes":{"intro":{"en":"Influential is built from the noun influence plus the adjective suffix -al. Inside influence sit in- 'into' and fluere 'to flow'; the prefix is still transparent, while the flow-root is shared with a large Latin family.","cn":"influential 由名词 influence 加形容词后缀 -al 构成。influence 内部是 in-「向内」与 fluere「流」；前缀仍可辨认，流这个词根则与一个庞大的拉丁词族共享。"},"latinIntro":{"en":"Latin fluere 'to flow' yields fluvius 'river', fluidus 'fluid', and compounds such as influere, affluere, effluere. The -al suffix comes from Latin -alis. The medieval noun influentia belongs to astrology before it belongs to politics.","cn":"拉丁 fluere「流」产生 fluvius「河流」、fluidus「流动的」，以及 influere、affluere、effluere 等复合词。-al 后缀来自拉丁 -alis。中世纪名词 influentia 先属于占星术，后来才属于政治。"},"items":[{"word":"influence","structure":"in- (into) + fluere (to flow)","meaning":"a current flowing into something; the power to affect it","meaningCN":"流入某物的水流；影响它的力量","example":"The tide had a strong influence on the harbor's shape.","exampleCN":"潮汐对港口形状有很大的影响。"},{"word":"influential","structure":"influence + -al (Latin -alis)","meaning":"having or exerting influence","meaningCN":"有影响力的；施加影响的","example":"She is an influential member of the planning board.","exampleCN":"她是规划委员会中一位有影响力的成员。"},{"word":"influentially","structure":"influential + -ly (adverb)","meaning":"in a way that exerts influence","meaningCN":"以施加影响的方式","example":"He acted influentially behind the scenes.","exampleCN":"他在幕后发挥了影响。"},{"word":"influencer","structure":"influence + -er (agent noun)","meaning":"one who exerts influence, especially online","meaningCN":"施加影响者，尤指网络影响者","example":"The brand hired a travel influencer for the campaign.","exampleCN":"该品牌为这次活动聘请了一位旅行影响者。"},{"word":"influenza","structure":"Italian influenza < Medieval Latin influentia","meaning":"an epidemic viral disease; a doublet of influence","meaningCN":"流行性感冒；influence 的同源双词","example":"The influenza season peaks in midwinter.","exampleCN":"流感季节在隆冬达到高峰。"},{"word":"fluid","structure":"Latin fluidus, from fluere (to flow)","meaning":"a flowing substance; able to flow","meaningCN":"流体；能流动的","example":"The patient was given fluids through a drip.","exampleCN":"病人通过点滴补充了液体。"},{"word":"fluent","structure":"Latin fluens, present participle of fluere","meaning":"flowing smoothly; speaking easily","meaningCN":"流畅的；说话流利的","example":"She is fluent in three languages.","exampleCN":"她能流利地说三种语言。"},{"word":"affluent","structure":"ad- (to) + fluere (to flow)","meaning":"wealthy; having riches flowing toward one","meaningCN":"富裕的；财富流向自己的","example":"The suburb became affluent within a decade.","exampleCN":"这个郊区在十年内变得富裕起来。"},{"word":"uninfluenced","structure":"un- (not) + influence + -ed","meaning":"not affected by outside influence","meaningCN":"未受外界影响的","example":"Her decision was uninfluenced by the publicity.","exampleCN":"她的决定没有受舆论宣传的影响。"}],"latinEntries":[{"word":"fluere","structure":"fluere (to flow)","meaning":"to flow, stream, run","meaningCN":"流动；流；奔流"},{"word":"influere","structure":"in- (into) + fluere","meaning":"to flow into","meaningCN":"流入"},{"word":"influentia","structure":"influere + -ntia (noun of state)","meaning":"an inflow; an astral emanation","meaningCN":"流入；星体流射"},{"word":"-alis","structure":"Latin adjective suffix -alis","meaning":"of or belonging to","meaningCN":"属于某物的；与某物有关的"}]}},{"word":"information","ipa_uk":"/ˌɪnfəˈmeɪʃn/","ipa_us":"/ˌɪnfərˈmeɪʃn/","definition_zh":"信息；资料；消息；知识；情报；数据；通知；（法律）告发","definition_en":"facts or details about someone or something; knowledge given or received; data stored or processed by a computer","core_image":"桌上散乱的纸页被分门别类装进档案盒，贴上标签——原本只是纸，现在别人能按标签找到它、读懂它、用它","scene":"At the information desk she collected timetables and maps for the whole journey.","sceneCN":"这里 information 与问讯处有关（第 8 个义项：负责向提问者提供事实的场所或服务）；句意：她在问讯处拿到了整个行程所需的时刻表和地图。图中可辨识物件：问讯台、时刻表、地图。","pos":[{"tag":"n.","zh":"信息；资料；消息；知识；情报；数据；通知"}],"collocations":[{"phrase":"a piece of information","zh":"一条信息"},{"phrase":"information technology","zh":"信息技术"},{"phrase":"personal information","zh":"个人信息"},{"phrase":"for your information","zh":"供你参考"},{"phrase":"information desk","zh":"问讯处"},{"phrase":"information overload","zh":"信息过载"}],"forms":[{"label":"复数（罕用，多用于法律「告发」义）","form":"informations"}],"derivatives":[{"word":"inform","pos":"v.","zh":"告知；通知；影响"},{"word":"informative","pos":"adj.","zh":"提供信息的；有教益的"},{"word":"informed","pos":"adj.","zh":"知情的；有见识的"},{"word":"informant","pos":"n.","zh":"提供信息者；线人"},{"word":"misinformation","pos":"n.","zh":"错误信息；误传"}],"senses":[{"no":"01","title":"Facts about something","titleCN":"信息：关于某人某事的实情","definition":"facts or details that tell you about a person, place, event, or situation","definitionCN":"说明某人、某地、某事件或某情况的实情或细节","example":"The website gives information about local bus routes.","exampleCN":"这个网站提供本地公交线路的信息。","why":"Latin informatio first meant the act of shaping the mind, then the idea placed there. The modern 'facts' sense is a nineteenth-century narrowing: what is communicated is treated as a body of well-shaped facts.","whyCN":"拉丁 informatio 最初指给头脑塑形的动作，后来指放进去的观念。现代「事实」义是 19 世纪的收窄：被传递的内容被当成一套已经塑好形状的事实。"},{"no":"02","title":"Knowledge received and kept","titleCN":"知识；见闻：进到脑子里并留下来的那部分","definition":"knowledge or understanding that someone has received or learned","definitionCN":"某人已接收或习得的知识或理解","example":"His lectures are full of information about Roman engineering.","exampleCN":"他的讲座充满关于罗马工程的知识。","why":"To inform is to give form to a mind. What the mind receives and keeps is information in the older, educational sense of the word.","whyCN":"inform 就是给头脑赋予形状。头脑接收并留下的东西，就是 information 较古老的教育义。"},{"no":"03","title":"What a message carries","titleCN":"信息内容：一条消息里真正传过去的东西","definition":"the meaningful content of a message or signal, especially in communication theory","definitionCN":"消息或信号中有意义的内容，尤用于通信理论","example":"A clear signal carries more information than a noisy one.","exampleCN":"清晰的信号比嘈杂的信号携带更多信息。","why":"In information theory, information is whatever reduces uncertainty in a message. The old core survives: a signal must take a definite shape before it can carry meaning.","whyCN":"在信息论中，信息就是减少消息不确定性的东西。旧的核心仍在：信号必须先取得确定的形状，才能承载意义。"},{"no":"04","title":"Data in a computer","titleCN":"（计算机）数据；信息：机器能读的形状","definition":"data that is stored, processed, or transmitted by a computer","definitionCN":"由计算机存储、处理或传输的数据","example":"The server stores information about every login.","exampleCN":"服务器存储每一次登录的信息。","why":"A computer keeps data in fixed forms; information is data that has been given a form a machine or reader can use. The suffix -ation marks the result of shaping.","whyCN":"计算机以固定的形式保存数据；信息就是被赋予机器或读者可用的形式的数据。后缀 -ation 标记的正是塑形的结果。"},{"no":"05","title":"Intelligence gathered for a purpose","titleCN":"情报：为某个目的收集来的信息","definition":"facts gathered about an enemy, a competitor, or a situation, often secretly","definitionCN":"关于敌人、竞争者或局势而收集的事实，常带秘密性质","example":"Military information was passed to headquarters by radio.","exampleCN":"军事情报通过无线电传到了总部。","why":"Intelligence is information gathered for a purpose. The flow is the same, but the channel is hidden and the receiver is chosen.","whyCN":"情报是为特定目的收集的信息。流还是同一股流，只是渠道隐蔽了，接收者也经过挑选。"},{"no":"06","title":"Formal notice given to someone","titleCN":"通知；告知：正式递到手上的消息","definition":"a formal statement or notice that tells someone something official","definitionCN":"向某人说明官方事务的正式陈述或通知","example":"Please contact us for further information about your application.","exampleCN":"欲知申请的进一步通知，请联系我们。","why":"A formal notice is information delivered on the record, so that the receiver is officially shaped by it. The act and the content share one noun.","whyCN":"正式通知是有记录地送达的信息，使接收者在官方意义上被它塑形。动作与内容共用同一个名词。"},{"no":"07","title":"Material laid before an inquiry","titleCN":"资料；材料：摆到桌面上供判断的东西","definition":"particulars or evidence supplied for an investigation or decision","definitionCN":"为调查或决定而提供的细节或证据材料","example":"The panel based its finding on information from eyewitnesses.","exampleCN":"小组根据目击者提供的材料作出判断。","why":"In inquiries, information is the shaped material laid before a decision-maker. It is not yet proof; it is what proof will be built from.","whyCN":"在调查中，信息是摆到决策者面前的成形材料。它还不是证据，而是证据将被搭建出来的原料。"},{"no":"08","title":"A service that answers questions","titleCN":"问讯处；资讯服务：把消息指给该去的人","definition":"a place or service whose job is to give facts to people who ask","definitionCN":"负责向提问者提供事实的场所或服务","example":"Ask at the information desk near the main entrance.","exampleCN":"请到正门附近的问讯处咨询。","why":"The desk is named for the act of informing: a place where the flow of facts is directed to whoever asks. The abstract noun stands for the concrete service.","whyCN":"问讯处以 informing 这个动作为名：在这里，事实的水流被引向提问的人。抽象名词转指具体的服务。"},{"no":"09","title":"A formal accusation in law","titleCN":"（法律）告发；起诉：把指控写成正式形状","definition":"in English law, a formal statement of an offence presented to a court","definitionCN":"在英国法中，向法庭正式提出的犯罪陈述","example":"The case began with an information filed against the company.","exampleCN":"案件始于对该公司提出的一份正式告发。","why":"In English law an information is a formal statement of an offence laid before a magistrate. The accusation has been given a legal form, which is exactly what informatio meant.","whyCN":"在英国法中，information 是提交治安法官的正式犯罪陈述。指控被赋予了法律形式，这正是 informatio 的本义。"}],"etymology":{"intro":{"en":"Information comes from Latin informatio, a noun of action from informare 'to give shape to, form, instruct'. The word's spine is forma, 'shape': to inform is to put a shape into something, especially a mind. The modern 'facts' sense is a later narrowing.","cn":"information 来自拉丁 informatio，是动词 informare「塑形、教导」的行为名词。它的脊梁是 forma「形状」：inform 就是把形状放进某物，尤其是放进头脑。现代「事实」义是后来收窄的结果。"},"items":[{"era":"LATIN NOUN forma","en":"forma meant 'shape, figure, mould'. A potter's forma is the mould that gives clay its outline; the word already contains the idea of a shape imposed from outside.","cn":"forma 意为「形状、外形、模子」。陶工的 forma 是给黏土定轮廓的模子；这个词本身已含有「从外部加上的形状」这一观念。"},{"era":"LATIN VERB informare","en":"informare is in- 'into' plus forma: to give a form to something, to mould it. By extension it came to mean 'to form the mind, instruct, teach'.","cn":"informare 是 in-「向内」加 forma：把形状给予某物、塑造它。引申后意为「塑造头脑、教导、传授」。"},{"era":"LATIN NOUN informatio","en":"informatio named the act of shaping and, by metonymy, the shape or idea produced: a conception, an outline, an instruction.","cn":"informatio 指塑形的动作，并以转喻指所产生的形状或观念：概念、轮廓、教导。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French information passed into English in the fourteenth century. Early English information meant instruction, news, or the act of informing, not a mass of neutral facts.","cn":"古法语 information 在 14 世纪进入英语。早期英语的 information 指教导、消息或告知的行为，而不是一堆中性的事实。"},{"era":"THE FACTS SENSE","en":"The modern sense 'facts communicated' is generally regarded as a nineteenth-century development, pushed by newspapers, telegraphy, and organized science, which needed a word for transferable factual content.","cn":"现代「被传递的事实」义一般被认为是 19 世纪的发展，由报纸、电报与有组织的科学推动——它们需要一个词来指可转移的事实内容。"},{"era":"THE COMPUTER AGE","en":"In the twentieth century information became a measurable quantity in communication theory (1948) and then the ordinary word for data handled by machines.","cn":"20 世纪，information 在通信理论（1948 年）中成为可度量的量，随后又成为机器所处理数据的日常用词。"}]},"similar":{"note":{"en":"The first group shares the Latin base forma or the verb informare; the last item, informal, looks identical in prefix but belongs to a different in-. The second group holds words that overlap in content but differ in origin and scope.","cn":"第一组共享拉丁词基 forma 或动词 informare；最后一项 informal 前缀形似，却属于另一个 in-。第二组是内容上重叠、但来源与范围不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"inform","ipa":"/ɪnˈfɔːm/","tag":"base verb","definition":"to tell someone facts; literally to give a form to the mind. It is the verb behind information.","definitionCN":"告知某人事实；字面是给头脑塑形。它是 information 所依据的动词。"},{"word":"informative","ipa":"/ɪnˈfɔːmətɪv/","tag":"same base, -ive adjective","definition":"giving useful facts. It describes the source or content, while information names the content itself.","definitionCN":"提供有用事实的。它描述来源或内容，而 information 指内容本身。"},{"word":"informant","ipa":"/ɪnˈfɔːmənt/","tag":"same base, person suffix","definition":"a person who supplies information, often secretly to an investigator. The -ant suffix marks the agent.","definitionCN":"提供信息的人，常指向调查者秘密提供信息者。-ant 后缀标记施动者。"},{"word":"informal","ipa":"/ɪnˈfɔːml/","tag":"false friend: another in-","definition":"relaxed, not official. It is in- 'not' plus formalis 'formal', not in- 'into' plus forma. The two prefixes are unrelated in sense here.","definitionCN":"非正式的；放松的。它是 in-「不」加 formalis「正式的」，不是 in-「向内」加 forma。此处两个前缀意义无关。"}]},{"heading":"NEAR MEANING","entries":[{"word":"data","ipa":"/ˈdeɪtə/","tag":"raw figures","definition":"facts and figures collected for reference or analysis. Data is raw material; information is data given meaning or form.","definitionCN":"为参考或分析而收集的事实与数字。data 是原料，information 是被赋予意义或形式的数据。"},{"word":"knowledge","ipa":"/ˈnɒlɪdʒ/","tag":"understanding held in a mind","definition":"organized understanding that a person or group possesses. Information can sit in a file; knowledge lives in a mind.","definitionCN":"个人或群体拥有的成体系理解。信息可以躺在文件里，知识则活在头脑中。"},{"word":"intelligence","ipa":"/ɪnˈtelɪdʒəns/","tag":"gathered secretly","definition":"information collected about an enemy or a situation, especially by secret means. Narrower and more purposeful than information.","definitionCN":"关于敌人或局势而收集的信息，尤指通过秘密手段。比 information 更窄、更有目的性。"},{"word":"news","ipa":"/njuːz/","tag":"recent events reported","definition":"newly received information about recent events. News is time-bound; information need not be new.","definitionCN":"关于近期事件的新消息。news 受时间约束，information 则不必是新的。"}]}]},"mnemonics":{"normalIntro":{"en":"The family is one act of shaping: forma is the mould, inform is to press the shape in, information is the shape that remains.","cn":"这个词族就是一次塑形：forma 是模子，inform 是把形状压进去，information 是留下的形状。"},"normal":[{"en":"in- 'into' + forma 'shape': to inform a mind is to press a shape into it, and information is that shape once it is there.","cn":"in-「向内」+ forma「形状」：inform 一个头脑，就是把形状压进去；information 就是留在里面的那个形状。"},{"en":"-ation (Latin -atio) is the noun suffix of an action and its result: inform → information.","cn":"-ation（拉丁 -atio）是表示动作及其结果的名词后缀：inform → information。"},{"en":"The early meaning was instruction, not neutral facts; the 'facts' sense is a modern narrowing.","cn":"早期词义是教导，不是中性事实；「事实」义是后来的收窄。"},{"en":"informal is a false friend: in- there means 'not', and the base is formal, not form.","cn":"informal 是假朋友：那里的 in- 意为「不」，词基是 formal，不是 form。"},{"en":"A computer's information is data that has been given a form a machine can hold.","cn":"计算机的信息，就是被赋予机器可保存之形式的数据。"}],"abstract":[{"en":"Think of clay on a wheel: the raw facts are clay, and information is the pot that has taken a shape.","cn":"想象陶轮上的黏土：原始事实是泥，信息是已经成形的陶罐。"},{"en":"Think of a library where every fact has a label and a shelf: the label is what turns a pile of papers into information.","cn":"想象一座图书馆，每条事实都有标签和书架位置：标签就是把一叠纸变成信息的东西。"},{"en":"Think of a signal crossing a noisy room: information is the part that still arrives and reduces your uncertainty.","cn":"想象一个信号穿过嘈杂的房间：信息就是仍然抵达、并减少你不确定性的那部分。"}]},"examples":[{"en":"The guidebook contains practical information about trains, ferries, and local markets.","cn":"这本指南包含关于火车、渡船和本地市场的实用信息。"},{"en":"The company encrypts all personal information before it leaves the server.","cn":"公司在个人信息离开服务器前将其全部加密。"},{"en":"Under English law, an information may be laid before a magistrate to begin proceedings.","cn":"根据英国法，可以向治安法官提交正式告发以启动程序。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in（向内）+ form（形状）+ ation（名词）——把形状放进头脑，头脑里留下的那个形状就是「信息」；纸上的事实被整理成形，也就成了可查找的「资料」。","word":"information"},"root":"拉丁 informare「塑形、教导」（in-「向内」+ forma「形状」）→ 拉丁 informatio「概念、教导」→ 古法语 information → 英语 information；-ation 为拉丁 -atio 名词后缀。现代「事实」义一般认为是 19 世纪随报刊、电报与科学兴起而固定。注意 informal 的 in- 是「不」，与此处 in-「向内」不同源。","sensesIntro":{"en":"Nine senses all come from one act: giving a shape. A mind is shaped by teaching, a message by a definite form, a computer file by a format, a court by a formal accusation.","cn":"九个义项都出自同一个动作：赋予形状。头脑被教导塑形，消息被确定的形式塑形，计算机文件被格式塑形，法庭被正式指控塑形。"},"semanticMap":{"core":{"en":"CORE IMAGE: raw material pressed into a form that someone can read and use.","cn":"核心意象：原料被压成某种形状，好让别人读懂、使用。"},"chain":["GIVE A SHAPE","FORM THE MIND","TELL WHAT IS TRUE","CARRY MEANING","STORE AS DATA","LAY BEFORE A COURT"],"branches":[{"senses":"S01 · S02","en":"FACTS AND KNOWLEDGE: shaped facts about the world, and what a mind keeps after being shaped.","cn":"事实与知识：关于世界的成形事实，以及头脑被塑形后留下的东西。"},{"senses":"S03 · S04","en":"FORM IN TRANSIT: the meaningful content of a signal, and data given a machine-readable form.","cn":"传递中的形式：信号里有意义的内容，以及被赋予机器可读形式的数据。"},{"senses":"S05 · S06","en":"PURPOSEFUL FLOW: facts gathered for a purpose, and notice officially delivered.","cn":"有目的的流动：为特定目的收集的事实，以及正式送达的通知。"},{"senses":"S07 · S08","en":"BEFORE A DECISION: material laid before an inquiry, and a desk that directs facts to askers.","cn":"决定之前：摆到调查者面前的料，以及把事实引向提问者的问讯处。"},{"senses":"S09","en":"THE LEGAL FORM: an accusation given the shape the court requires.","cn":"法律的形式：被赋予法庭所需形状的一项指控。"}]},"affixes":{"intro":{"en":"Information is a Latinate noun: informare plus -atio. The suffix builds action-and-result nouns; the prefix in- and the base forma remain visible inside. The same base produces inform, informative, informed, and informant.","cn":"information 是拉丁系名词：informare 加 -atio。这个后缀构成「动作及其结果」名词；前缀 in- 与词基 forma 在词内仍可辨认。同一词基还产生 inform、informative、informed 与 informant。"},"latinIntro":{"en":"Latin forma 'shape, mould' is the source of information, inform, informative, and also of formal and format. Note that English informal uses a homonymous in- meaning 'not', not the in- 'into' of informare.","cn":"拉丁 forma「形状、模子」是 information、inform、informative 以及 formal、format 的来源。注意英语 informal 用的是同形的 in-「不」，而不是 informare 的 in-「向内」。"},"items":[{"word":"inform","structure":"in- (into) + formare (to shape)","meaning":"to give shape to, especially the mind; to tell","meaningCN":"塑形，尤指塑造头脑；告知","example":"Please inform us of any change of address.","exampleCN":"地址如有变更，请通知我们。"},{"word":"information","structure":"informare + -atio (action and result noun)","meaning":"the act of shaping or instructing; what is communicated","meaningCN":"塑形或教导的行为；被传递的内容","example":"The file contains information on every supplier.","exampleCN":"这份档案包含关于每家供应商的信息。"},{"word":"informative","structure":"inform + -ive (having the nature of)","meaning":"giving useful facts or knowledge","meaningCN":"提供有用事实或知识的","example":"The museum tour was short but informative.","exampleCN":"博物馆的导览虽短，却很有信息量。"},{"word":"informed","structure":"inform + -ed (past participle)","meaning":"having been given facts; knowledgeable","meaningCN":"已获知事实的；有见识的","example":"An informed reader will notice the missing figure.","exampleCN":"有见识的读者会注意到缺失的数字。"},{"word":"informatively","structure":"informative + -ly","meaning":"in a way that gives useful facts","meaningCN":"以提供有用事实的方式","example":"The chart is informatively labelled.","exampleCN":"这张图表的标注提供了有用的信息。"},{"word":"informativeness","structure":"informative + -ness","meaning":"the quality of giving useful information","meaningCN":"提供有用信息的程度","example":"Readers rated the article's informativeness highly.","exampleCN":"读者对这篇文章的信息量评价很高。"},{"word":"informant","structure":"inform + -ant (agent noun)","meaning":"one who supplies information","meaningCN":"提供信息的人；线人","example":"The police protected the identity of their informant.","exampleCN":"警方保护了线人的身份。"},{"word":"uninformed","structure":"un- (not) + informed","meaning":"not having the facts","meaningCN":"不知情的；未获信息的","example":"The debate was dominated by uninformed guesses.","exampleCN":"这场辩论被不知情的猜测主导。"},{"word":"informal","structure":"in- (not) + formalis (formal)","meaning":"relaxed, unofficial; a different in- from inform","meaningCN":"非正式的；放松的（in- 意为「不」，与 inform 的 in- 不同）","example":"They reached an informal agreement over lunch.","exampleCN":"他们在午餐时达成了一项非正式协议。"}],"latinEntries":[{"word":"forma","structure":"forma (shape, mould)","meaning":"shape, figure, mould","meaningCN":"形状；外形；模子"},{"word":"informare","structure":"in- (into) + forma + -are","meaning":"to shape, mould, form the mind","meaningCN":"塑形；塑造；教导"},{"word":"informatio","structure":"informare + -tio","meaning":"a shaping; a conception; instruction","meaningCN":"塑形；概念；教导"},{"word":"-atio","structure":"Latin noun suffix -atio","meaning":"action or its result","meaningCN":"动作或其结果"}]}},{"word":"informative","ipa_uk":"/ɪnˈfɔːmətɪv/","ipa_us":"/ɪnˈfɔːrmətɪv/","definition_zh":"提供信息的；增长见识的；有教益的；内容充实的","definition_en":"giving useful facts or knowledge; instructive and rich in content","core_image":"一张折叠地图上密密标着水系、海拔和村名——看的人什么都没做，脑子里的地图却变厚了","scene":"The lecture was surprisingly informative: every slide carried a map and a number.","sceneCN":"这里 informative 是「提供有用信息的」（第 1 个义项：给出有用事实或细节的）；句意：这场讲座出乎意料地有信息量，每张幻灯片都带着地图和数字。图中可辨识物件：投影幕、幻灯片、笔记本。","pos":[{"tag":"adj.","zh":"提供信息的；增长见识的；有教益的"}],"collocations":[{"phrase":"informative talk","zh":"有信息量的讲座"},{"phrase":"highly informative","zh":"极具信息量的"},{"phrase":"informative website","zh":"资料丰富的网站"},{"phrase":"informative discussion","zh":"有启发的讨论"},{"phrase":"informative label","zh":"说明清楚的标签"},{"phrase":"informative experience","zh":"有教益的经历"}],"forms":[{"label":"比较级","form":"more informative"},{"label":"最高级","form":"most informative"},{"label":"副词","form":"informatively"},{"label":"名词","form":"informativeness"}],"derivatives":[{"word":"inform","pos":"v.","zh":"告知；通知；影响"},{"word":"information","pos":"n.","zh":"信息；资料；知识"},{"word":"informatively","pos":"adv.","zh":"以提供信息的方式"},{"word":"informativeness","pos":"n.","zh":"信息量；有教益的程度"},{"word":"uninformed","pos":"adj.","zh":"不知情的；缺乏信息的"}],"senses":[{"no":"01","title":"Giving useful facts","titleCN":"提供有用信息的：看完能多知道几件事","definition":"giving facts or details that are useful to the reader or listener","definitionCN":"向读者或听者提供有用事实或细节的","example":"The pamphlet is short but very informative.","exampleCN":"这本小册子很短，但信息量很大。","why":"Informative is inform plus -ive 'having the nature of'. To inform is to give a shape to a mind; an informative text is one that actually presses that shape in.","whyCN":"informative 是 inform 加 -ive「具有某种性质的」。inform 是给头脑塑形；一篇 informative 的文字，就是确实把形状压进去的文字。"},{"no":"02","title":"Teaching and instructive","titleCN":"有教益的：不只是知道，还学到","definition":"giving knowledge in a way that teaches or improves the reader","definitionCN":"以能教导或提升读者的方式给予知识的","example":"The documentary was an informative account of the migration.","exampleCN":"这部纪录片是对这场迁徙的有教益的记述。","why":"The oldest sense of informare is 'to instruct, form the mind'. The adjective keeps that educational tone: what is informative leaves the mind better shaped than before.","whyCN":"informare 最古老的意义是「教导、塑造头脑」。这个形容词保留着教育语调：informative 的东西让头脑比先前塑得更好。"},{"no":"03","title":"Dense with content","titleCN":"内容充实的：每一页都装得下东西","definition":"containing a large amount of information in relation to its length","definitionCN":"相对于篇幅而言含有大量信息的","example":"It is the most informative chapter in the book.","exampleCN":"这是全书内容最充实的一章。","why":"A page is informative in proportion to how much shape it puts into the reader's mind per line. Density is the modern measure of the old shaping act.","whyCN":"一页文字有多 informative，取决于每一行能给读者的头脑压进多少形状。密度是那个古老塑形动作的现代量度。"},{"no":"04","title":"Well-researched and detailed","titleCN":"资料翔实的：细节经过查证","definition":"based on thorough research and full of verified detail","definitionCN":"基于充分研究、充满经核实细节的","example":"The report is informative about costs and timelines.","exampleCN":"这份报告在成本和工期方面资料翔实。","why":"Research supplies verified particulars. The word then describes the shaping as thorough rather than merely plentiful: the details fit together.","whyCN":"研究提供经核实的细节。此时这个词描述的是塑形之彻底，而不只是数量之多：细节彼此咬合。"},{"no":"05","title":"Revealing and illuminating","titleCN":"能说明问题的：把原本看不见的照亮","definition":"helping one understand a situation by revealing something previously unclear","definitionCN":"通过揭示先前不清楚之处来帮助理解局势的","example":"The comparison is informative about how the two systems differ.","exampleCN":"这项比较能说明两个体系如何不同。","why":"Something revealing opens a closed shape: the new facts rearrange the reader's picture, so the information is felt as light rather than volume.","whyCN":"能揭示事物的东西会打开一个封闭的形状：新事实重新排列读者心中的图景，于是信息被感受为光，而不是体积。"},{"no":"06","title":"Clear in conveying data","titleCN":"标示清楚的：图表和标签一眼能读懂","definition":"of a label, chart, or sign, presenting data clearly enough to be understood","definitionCN":"指标签、图表或标志清楚呈现数据、足以被理解的","example":"The map uses informative colours instead of decoration.","exampleCN":"这张地图用的是说明性的颜色，而不是装饰。","why":"On a chart or label, informativeness is literal: the form must be legible before it can shape understanding. A beautiful label that cannot be read is not informative.","whyCN":"在图表或标签上，信息性是字面意义上的：形式必须先可读，才能塑形理解。一个漂亮却读不懂的标签并不 informative。"},{"no":"07","title":"An educational experience","titleCN":"有教益的经历：走一趟，人变了","definition":"of an experience, teaching one something lasting","definitionCN":"指一段经历，使人学到持久的东西","example":"A week in the clinic proved more informative than any textbook.","exampleCN":"在诊所的一周比任何教科书都更有教益。","why":"An experience informs when it leaves a durable shape in memory. The adjective shifts from the source to its effect on a person.","whyCN":"一段经历能 inform，是因为它在记忆里留下持久的形状。这个形容词从信息源转向了对人的效果。"},{"no":"08","title":"Conveying meaning without words","titleCN":"传达信息的：一个眼神也带着消息","definition":"of a look, gesture, or expression, communicating something to an observer","definitionCN":"指眼神、手势或表情向观察者传达某种信息的","example":"She shot him an informative glance across the table.","exampleCN":"她在桌子那头向他投去一个意味深长的眼神。","why":"A glance can inform without words: the face takes a form the other reads. The adjective extends to any sign that carries meaning.","whyCN":"一个眼神不用言语也能 inform：面部取得一种被对方读取的形状。这个形容词于是扩展到任何承载意义的信号。"},{"no":"09","title":"Telling in statistics","titleCN":"有说明力的：数字一摆，判断就变","definition":"of figures or results, revealing a pattern that changes one's judgment","definitionCN":"指数字或结果揭示出改变判断的模式","example":"The dropout rates are especially informative.","exampleCN":"辍学率尤其能说明问题。","why":"Statistics are called informative when they change a judgment, not merely when they are numerous. The old measure of effect survives inside the modern quantitative use.","whyCN":"统计数字被称为 informative，是因为它们改变了判断，而不只是数量多。古老的「效果」量度保存在现代定量用法里。"}],"etymology":{"intro":{"en":"Informative is inform plus the adjective suffix -ive, from Latin -ivus 'having the nature of'. It shares the base forma with information, but it describes the source that gives shape rather than the shape received.","cn":"informative 是 inform 加形容词后缀 -ive，后者来自拉丁 -ivus「具有某种性质的」。它与 information 共享词基 forma，但描述的是塑形的来源，而不是被接收的形状。"},"items":[{"era":"LATIN NOUN forma","en":"forma 'shape, mould' is the base. The family always keeps the idea of an outline imposed on something plastic, whether clay or a mind.","cn":"词基是 forma「形状、模子」。这个词族始终保留「把轮廓加在可塑之物上」的观念，无论那东西是黏土还是头脑。"},{"era":"VERB informare","en":"in- 'into' plus formare 'to shape' gives 'to mould, to form the mind, to instruct'. The teaching sense is the one that produced informative.","cn":"in-「向内」加 formare「塑形」得到「塑造、塑造头脑、教导」。产生 informative 的正是这个教导义。"},{"era":"SUFFIX -ivus","en":"Latin -ivus means 'having the nature of, tending to'. English -ive is its borrowed form, visible in instructive, active, and creative.","cn":"拉丁 -ivus 意为「具有某种性质的、倾向于」。英语 -ive 是它的借入形式，在 instructive、active、creative 中都能看到。"},{"era":"ENGLISH FORMATION","en":"English built informative on inform with -ive. The word is recorded from the seventeenth century, first close to 'formative', then settling into 'giving information'.","cn":"英语用 inform 加 -ive 构成 informative。这个词自 17 世纪有记录，最初接近「有塑形作用的」，后来稳定为「提供信息的」。"},{"era":"SENSE NARROWING","en":"As information shifted toward 'facts', informative shifted with it: from 'shaping the mind' to 'supplying facts that shape the mind'. The educational trace remains in the 'instructive' sense.","cn":"随着 information 转向「事实」，informative 也跟着转：从「塑造头脑」转为「提供能塑造头脑的事实」。教育痕迹仍留在「有教益」这一义项里。"},{"era":"MODERN PAIR","en":"Modern usage separates informative from informed: a book is informative, while a reader is informed. The first describes the source, the second the person who received the shape.","cn":"现代用法把 informative 与 informed 分开：书是 informative，读者是 informed。前者描述来源，后者描述接受了形状的人。"}]},"similar":{"note":{"en":"The first group is built on inform and forma, except informal, which uses a different in- meaning 'not'. The second group contains words that also praise what teaches or reveals, but from other roots.","cn":"第一组建立在 inform 与 forma 上，只有 informal 例外，它用的是另一个表示「不」的 in-。第二组是同样用来称赞「有教益、能揭示」之物、但词根不同的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"inform","ipa":"/ɪnˈfɔːm/","tag":"base verb","definition":"to tell someone facts; literally to give the mind a shape. Informative is its -ive adjective.","definitionCN":"告知某人事实；字面是给头脑塑形。informative 是它的 -ive 形容词。"},{"word":"information","ipa":"/ˌɪnfəˈmeɪʃn/","tag":"same base, noun","definition":"facts or knowledge communicated. It names the content; informative names the quality of the source.","definitionCN":"被传递的事实或知识。它指内容本身，informative 指来源的性质。"},{"word":"informed","ipa":"/ɪnˈfɔːmd/","tag":"same base, person-focused","definition":"having facts; knowledgeable. A person is informed, but a book is informative; the pair divides receiver from source.","definitionCN":"知情的；有知识的。人是 informed，书是 informative；这对词把接收者与来源分开。"},{"word":"informal","ipa":"/ɪnˈfɔːml/","tag":"false friend: in- means not","definition":"relaxed, unofficial. It is in- 'not' plus formalis, not the in- 'into' of informare; the shared letters hide two different prefixes.","definitionCN":"非正式的；放松的。它是 in-「不」加 formalis，不是 informare 的 in-「向内」；相同的字母掩盖了两个不同的前缀。"}]},{"heading":"NEAR MEANING","entries":[{"word":"instructive","ipa":"/ɪnˈstrʌktɪv/","tag":"teaching","definition":"giving instruction or a lesson. It stresses the moral or practical lesson; informative stresses the supply of facts.","definitionCN":"有指导意义的。它强调道德或实践上的教训，informative 强调事实的供给。"},{"word":"educational","ipa":"/ˌedʒuˈkeɪʃənl/","tag":"schooling purpose","definition":"intended to teach or improve. It points to a purpose, while informative points to the amount of knowledge actually delivered.","definitionCN":"有教育目的的。它指向目的，informative 指向实际传递的知识量。"},{"word":"revealing","ipa":"/rɪˈviːlɪŋ/","tag":"uncovering","definition":"making something hidden known. It stresses disclosure; informative can also mean merely full of detail.","definitionCN":"揭示隐藏之事的。它强调披露，informative 也可以只表示细节丰富。"},{"word":"illuminating","ipa":"/ɪˈluːmɪneɪtɪŋ/","tag":"making clear","definition":"helping one understand by casting light on a subject. It is closer to the 'revealing' sense of informative than to its 'fact-filled' sense.","definitionCN":"使理解变清楚的。它更接近 informative 的「揭示」义，而不是「充满事实」义。"}]}]},"mnemonics":{"normalIntro":{"en":"The family is one shaping act seen from three sides: the mould (forma), the act of pressing it in (inform), and the quality of a thing that presses it in well (informative).","cn":"这个词族是从三个方向看同一个塑形动作：模子（forma）、把形状压进去的动作（inform），以及一块能把它压进去的好材料（informative）。"},"normal":[{"en":"inform + -ive: informative = having the nature of informing, that is, of shaping the mind with facts.","cn":"inform + -ive：informative = 具有 inform 性质的，也就是能用事实给头脑塑形。"},{"en":"The base is forma 'shape', so an informative talk is one that leaves a shape behind, not one that merely makes noise.","cn":"词基是 forma「形状」，所以 informative 的讲座是留下形状的讲座，而不只是发出声音。"},{"en":"informative describes the source; informed describes the person. A book informs, and the reader becomes informed.","cn":"informative 描述来源，informed 描述人。书在 inform，读者则变得 informed。"},{"en":"If you can say 'I learned something', the thing was informative; if you can only say 'I heard a lot', it was merely long.","cn":"如果你能说「我学到了东西」，那东西就是 informative；如果你只能说「我听了许多」，那只是冗长。"},{"en":"informal looks like a sibling but carries in- 'not'; it belongs to formal, not to forma.","cn":"informal 看着像兄弟，却带着 in-「不」；它属于 formal，不属于 forma。"}],"abstract":[{"en":"Think of a mind as soft clay and a good lecture as a mould: informative is the mould's property, not the clay's.","cn":"把头脑想成软泥，把好讲座想成模子：informative 是模子的性质，不是泥的性质。"},{"en":"Think of a map that adds a contour line each time you look: every added line is a fact, and the map is informative because it becomes more navigable.","cn":"想象一张地图，每次看都多出一条等高线：每条新增的线就是一个事实，地图之所以 informative，是因为它变得更好用。"},{"en":"Think of a window opened in a dark room: informative is not the amount of glass but the amount of light that gets through.","cn":"想象在暗室里打开一扇窗：informative 不在于玻璃多少，而在于透进来多少光。"}]},"examples":[{"en":"The museum's audio guide is brief but remarkably informative.","cn":"博物馆的语音导览简短，却极有信息量。"},{"en":"We had an informative meeting with the engineers about the delays.","cn":"我们和工程师就延误问题开了一次很有收获的会。"},{"en":"The chart is informative because it compares costs per kilometre, not just totals.","cn":"这张图之所以能说明问题，是因为它比较的是每公里成本，而不只是总额。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in（向内）+ form（形状）+ ative（具有某种性质的）——能把形状压进你脑子里的东西，就是「提供信息的、有教益的」；同族 information 指压进去的那个形状。","word":"informative"},"root":"inform「告知、塑形」（拉丁 informare ← in-「向内」+ forma「形状」）+ -ive（拉丁 -ivus「具有某种性质的」）；与 information 同源，词基同为 forma。informative 描述来源，informed 描述接收者。","sensesIntro":{"en":"Nine senses all measure one thing: how much shape a source presses into a mind. A text, a chart, a class, a glance, or a statistic can each carry that shaping force.","cn":"九个义项都在衡量同一件事：一个来源能把多少形状压进头脑。一段文字、一张图表、一堂课、一个眼神或一组统计，都能携带这种塑形之力。"},"semanticMap":{"core":{"en":"CORE IMAGE: a source that leaves the receiver's mind better shaped than before.","cn":"核心意象：一个让接收者头脑比先前塑得更好的来源。"},"chain":["PUT SHAPE INTO A MIND","GIVE USEFUL FACTS","TEACH A LESSON","FILL THE PAGE","MAKE THE PICTURE CLEAR","CHANGE A JUDGMENT"],"branches":[{"senses":"S01 · S03","en":"FACT AND DENSITY: useful facts supplied, and the amount of them packed into a given space.","cn":"事实与密度：提供有用事实，以及在给定篇幅里装进多少事实。"},{"senses":"S02 · S07","en":"TEACHING: a text that instructs, and an experience that leaves a lasting lesson.","cn":"教导：教导人的文字，以及留下持久教益的经历。"},{"senses":"S04 · S06","en":"THOROUGHNESS AND CLARITY: verified detail, and a form legible enough to be read.","cn":"翔实与清楚：经核实的细节，以及清楚到足以被读懂的形式。"},{"senses":"S05 · S09","en":"REVELATION: a comparison or a set of figures that rearranges one's judgment.","cn":"揭示：重新排列判断的比较或一组数字。"},{"senses":"S08","en":"THE WORDLESS SIGN: a look or gesture that carries a message.","cn":"无言的信号：一个携带消息的眼神或手势。"}]},"affixes":{"intro":{"en":"Informative is inform plus -ive. The suffix is productive and Latin in origin; the base goes back through French to Latin informare, itself in- plus forma. The word therefore has two suffixes in its history: -ation in information and -ive in informative.","cn":"informative 是 inform 加 -ive。这个后缀能产，源自拉丁；词基经法语上溯拉丁 informare，而 informare 本身是 in- 加 forma。因此这个词的历史里有两个后缀：information 里的 -ation 与 informative 里的 -ive。"},"latinIntro":{"en":"Latin forma 'shape' and informare 'to shape, instruct' supply the base. The suffix -ivus 'having the nature of' yields English -ive, also seen in active, passive, and creative.","cn":"拉丁 forma「形状」与 informare「塑形、教导」提供词基。后缀 -ivus「具有某种性质的」产生英语 -ive，也见于 active、passive、creative。"},"items":[{"word":"inform","structure":"in- (into) + formare (to shape)","meaning":"to give the mind a shape; to tell","meaningCN":"给头脑塑形；告知","example":"The nurse informed him of the test results.","exampleCN":"护士把检验结果告诉了他。"},{"word":"information","structure":"informare + -atio","meaning":"what is communicated; the shaping of a mind","meaningCN":"被传递的内容；对头脑的塑形","example":"The website offers information on local clinics.","exampleCN":"这个网站提供本地诊所的信息。"},{"word":"informative","structure":"inform + -ive (Latin -ivus)","meaning":"having the nature of informing; giving facts","meaningCN":"具有告知性质的；提供事实的","example":"The briefing was clear and informative.","exampleCN":"这次简报清楚而富有信息。"},{"word":"informed","structure":"inform + -ed (past participle)","meaning":"having received facts; knowledgeable","meaningCN":"已获得事实的；有见识的","example":"The decision was made by an informed committee.","exampleCN":"这个决定由一个知情的委员会作出。"},{"word":"informatively","structure":"informative + -ly","meaning":"in an informative manner","meaningCN":"以有信息量的方式","example":"The report is informatively illustrated.","exampleCN":"这份报告的插图很有说明性。"},{"word":"informativeness","structure":"informative + -ness","meaning":"the quality of being informative","meaningCN":"信息量；有教益的性质","example":"They tested the informativeness of different labels.","exampleCN":"他们测试了不同标签的信息量。"},{"word":"informant","structure":"inform + -ant","meaning":"one who gives information","meaningCN":"提供信息者；线人","example":"The researcher interviewed three informants.","exampleCN":"研究者采访了三位信息提供者。"},{"word":"uninformed","structure":"un- (not) + informed","meaning":"lacking facts","meaningCN":"不知情的；缺乏信息的","example":"Uninformed rumours spread quickly online.","exampleCN":"缺乏根据的谣言在网上迅速传播。"},{"word":"informal","structure":"in- (not) + formalis (formal)","meaning":"not formal; a different prefix from inform","meaningCN":"非正式的（in- 意为「不」，与 inform 的前缀不同）","example":"They held an informal meeting in the corridor.","exampleCN":"他们在走廊里开了一次非正式会议。"}],"latinEntries":[{"word":"forma","structure":"forma (shape, mould)","meaning":"shape, figure, mould","meaningCN":"形状；外形；模子"},{"word":"informare","structure":"in- (into) + forma + -are","meaning":"to shape, mould, instruct","meaningCN":"塑形；塑造；教导"},{"word":"-ivus","structure":"Latin adjective suffix -ivus","meaning":"having the nature of, tending to","meaningCN":"具有某种性质的；倾向于"}]}},{"word":"infrastructure","ipa_uk":"/ˈɪnfrəstrʌktʃə/","ipa_us":"/ˈɪnfrəstrʌktʃər/","definition_zh":"基础设施；基础结构；公共设施；下部结构；基础架构","definition_en":"the basic physical and organizational structures and facilities that a society or enterprise needs in order to operate","core_image":"路面之下看不见的管网：水管、电缆、排水沟、光纤一层层铺在土里，托住上面所有的房子和车流","scene":"The city's infrastructure was laid a century ago and cannot carry today's traffic.","sceneCN":"这里 infrastructure 是「基础设施」总称（第 1 个义项：社会运转所依赖的道路、供水等基本系统）；句意：这座城市的基础设施是一个世纪前铺设的，已承载不了今天的车流。图中可辨识物件：老旧水管、道路剖面、施工围挡。","pos":[{"tag":"n.","zh":"基础设施；基础结构；公共设施；下部结构"}],"collocations":[{"phrase":"transport infrastructure","zh":"交通基础设施"},{"phrase":"infrastructure investment","zh":"基础设施投资"},{"phrase":"critical infrastructure","zh":"关键基础设施"},{"phrase":"infrastructure project","zh":"基建项目"},{"phrase":"digital infrastructure","zh":"数字基础设施"},{"phrase":"ageing infrastructure","zh":"老化的基础设施"}],"forms":[{"label":"复数","form":"infrastructures"}],"derivatives":[{"word":"infrastructural","pos":"adj.","zh":"基础设施的；基础结构的"},{"word":"superstructure","pos":"n.","zh":"上部结构；上层建筑"},{"word":"substructure","pos":"n.","zh":"下部结构；基础"},{"word":"cyberinfrastructure","pos":"n.","zh":"网络基础设施"},{"word":"green infrastructure","pos":"n.","zh":"绿色基础设施"}],"senses":[{"no":"01","title":"The basic systems a society runs on","titleCN":"基础设施：社会运转所依赖的基本系统","definition":"the roads, bridges, water supply, power lines, and similar works that a country or city needs to function","definitionCN":"国家或城市运转所需的道路、桥梁、供水、电力线路等工程设施","example":"The storm damaged infrastructure across three provinces.","exampleCN":"这场风暴破坏了三个省的基础设施。","why":"Infra means 'below' and structura means 'building'. The word names the layer beneath a society's visible buildings, the works that must exist before other works can stand.","whyCN":"infra 意为「在下」，structura 意为「建造」。这个词命名的是社会可见建筑之下的那一层，是其他工程能够立起来之前必须先存在的东西。"},{"no":"02","title":"The substructure below the surface","titleCN":"下部结构：地面之下承重的那一层","definition":"the lower part of a structure, especially the foundations and works below ground level","definitionCN":"结构的下部，尤指地面以下的根基与工程部分","example":"The bridge's infrastructure was reinforced with concrete piles.","exampleCN":"这座桥的下部结构用混凝土桩加固过。","why":"In nineteenth-century engineering, infrastructure was the substructure of a railway or road, the part under the visible surface. The French technical coinage is generally associated with this need.","whyCN":"在 19 世纪的工程语境中，infrastructure 指铁路或道路的下部结构，即可见表面之下的部分。一般认为这一法语技术词正是为这种需要而造的。"},{"no":"03","title":"The pipes and wires of daily life","titleCN":"公用设施：水、电、燃气、排污那套管网","definition":"the public utilities such as water, gas, electricity, and sewerage that serve homes and businesses","definitionCN":"为家庭与企业服务的水、燃气、电力、排污等公用事业设施","example":"The neighbourhood lacks basic infrastructure such as clean water.","exampleCN":"这个街区缺乏清洁供水等基本公用设施。","why":"Utilities are the pipes and wires through which water, gas, and power flow. They are infrastructure in its most literal below-the-street form.","whyCN":"公用事业就是水、燃气与电力流经的管道和电线。它们是最字面意义上的「街道之下」的基础设施。"},{"no":"04","title":"The frame beneath an organization","titleCN":"基础架构：一个组织看不见的骨架","definition":"the systems, procedures, and roles that support the work of an organization","definitionCN":"支撑一个组织运作的制度、程序与角色体系","example":"The company rebuilt its management infrastructure after the merger.","exampleCN":"合并后，公司重建了管理基础架构。","why":"An organization also has a layer beneath its visible activities: procedures, systems, and roles. The metaphor imports the engineering image into management.","whyCN":"一个组织在其可见活动之下也有一层：程序、制度与角色。这个隐喻把工程的意象搬进了管理。"},{"no":"05","title":"The networks behind computing","titleCN":"信息基础设施：服务器、电缆与协议","definition":"the hardware, networks, and systems on which computing and communications depend","definitionCN":"计算与通信所依赖的硬件、网络与系统","example":"universities share a high-speed information infrastructure","exampleCN":"多所大学共享一套高速信息基础设施。","why":"Digital networks are the new pipes: servers, cables, protocols. The name follows because nothing above can run without them.","whyCN":"数字网络是新的管道：服务器、电缆、协议。这个名字跟着来了，因为上面的一切离开它们都运行不了。"},{"no":"06","title":"Permanent military installations","titleCN":"军事设施：军队长期使用的固定基地","definition":"the permanent bases, airfields, depots, and other fixed installations used by armed forces","definitionCN":"武装部队使用的永久基地、机场、仓库等固定设施","example":"The treaty limited the infrastructure allowed near the border.","exampleCN":"该条约限制了边境附近允许设置的军事设施。","why":"Permanent bases, airfields, and depots are the fixed layer under military operations, which move above them.","whyCN":"永久基地、机场与仓库是军事行动之下的固定层，行动在其上移动。"},{"no":"07","title":"The base of an economy","titleCN":"经济基础设施：市场赖以运转的交通与能源","definition":"the transport, power, and communication systems on which economic activity depends","definitionCN":"经济活动所依赖的交通、能源与通信系统","example":"Weak infrastructure raises the cost of moving goods.","exampleCN":"薄弱的基础设施提高了货物运输成本。","why":"Economists widened the term to the transport, power, and communication base on which markets depend. The metaphor is still a supporting layer.","whyCN":"经济学家把这个词扩展到市场所依赖的交通、能源与通信基础。隐喻仍然是一层承托之物。"},{"no":"08","title":"The base of social life","titleCN":"社会基础设施：学校、医院与公园","definition":"the schools, hospitals, parks, and community services that support social well-being","definitionCN":"支撑社会福祉的学校、医院、公园与社区服务","example":"Hospitals and schools are part of social infrastructure.","exampleCN":"医院和学校属于社会基础设施。","why":"Schools, hospitals, and parks form the layer that supports social life; the word adds a social sector to the physical list.","whyCN":"学校、医院与公园构成支撑社会生活的那一层；这个词在实物的清单上又加进了社会部门。"},{"no":"09","title":"The enduring base of any system","titleCN":"根基：任何体系底下那层不易更换的东西","definition":"the underlying foundation of an idea, system, or activity, often used figuratively","definitionCN":"观念、体系或活动底下那层基础，常用于比喻","example":"Trust is the infrastructure of a working team.","exampleCN":"信任是一个能运作的团队的基础。","why":"In general use, any enduring base of an idea or system can be called its infrastructure, even when nothing is made of concrete.","whyCN":"在一般用法中，任何观念或体系持久的底座都可以称为它的 infrastructure，哪怕没有一点混凝土。"}],"etymology":{"intro":{"en":"Infrastructure joins Latin infra 'below' to structura 'a building, arrangement', from struere 'to build'. The word was coined in nineteenth-century engineering to name the substructure under a railway, then widened to the whole supporting base of a society.","cn":"infrastructure 把拉丁 infra「在下」与 structura「建造物、构造」连接起来，后者来自 struere「建造」。这个词在 19 世纪的工程语境中被造出，指铁路之下的下部结构，随后扩展到整个社会的承托底座。"},"items":[{"era":"LATIN PREFIX infra","en":"infra meant 'below, beneath'. It belongs to the same family as inferus 'lower' and inferior, and is not the negative prefix in-; the two prefixes are different morphemes that happen to look alike.","cn":"infra 意为「在下、低于」。它与 inferus「更低的」、inferior 同族，并不是否定前缀 in-；这两个前缀只是长得像，实为不同语素。"},{"era":"LATIN VERB struere","en":"struere meant 'to pile up, build'. Its noun structura named a building or the way parts are put together, the same base seen in structure, construct, and instruct.","cn":"struere 意为「堆积、建造」。其名词 structura 指建筑物或各部分的组合方式，同一词基见于 structure、construct、instruct。"},{"era":"FRENCH ENGINEERING TERM","en":"The compound infra- plus structure is generally attributed to nineteenth-century French engineering, where it named the substructure beneath a railway or road. The exact first writer is not certain.","cn":"infra- 加 structure 这一复合词一般认为出自 19 世纪法国工程语境，用来指铁路或道路之下的下部结构。最早由谁写下并不确定。"},{"era":"ENGLISH BORROWING","en":"English borrowed the term in the late nineteenth century, still in the civil-engineering sense of the layer below the visible surface.","cn":"英语在 19 世纪末借入该词，仍保留土木工程义，指可见表面之下的那一层。"},{"era":"MILITARY WIDENING","en":"In the mid-twentieth century, military and political usage applied infrastructure to permanent bases and installations, the fixed layer under moving operations.","cn":"20 世纪中叶，军事与政治用法把 infrastructure 用于永久基地与设施，即流动行动之下的固定层。"},{"era":"MODERN WIDENING","en":"Later the word spread to economic, social, and digital systems. Each new field kept the same picture: a base that must be in place before anything above it can work.","cn":"后来这个词扩展到经济、社会与数字系统。每个新领域都保留同一幅图：一层必须先就位、上面的东西才能运转的底座。"}]},"similar":{"note":{"en":"The first group shares Latin struere or the prefix infra; instruction looks close but uses in- 'into', a different prefix. The second group holds words for facilities or bases that overlap in use but not in image.","cn":"第一组共享拉丁 struere 或前缀 infra；instruction 形似，却用了另一个前缀 in-「向内」。第二组是设施或基础类词，用法重叠但意象不同。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"structure","ipa":"/ˈstrʌktʃə/","tag":"base noun","definition":"a building or the way parts are arranged. It is the plain noun behind infrastructure, without the infra- prefix.","definitionCN":"建筑物或各部分的组合方式。它是 infrastructure 背后不带 infra- 前缀的普通名词。"},{"word":"superstructure","ipa":"/ˈsuːpəstrʌktʃə/","tag":"the layer above","definition":"the part of a structure above the base or above a deck. super- 'above' is the mirror of infra- 'below'.","definitionCN":"结构基础之上或甲板之上的部分。super-「在上」正是 infra-「在下」的镜像。"},{"word":"substructure","ipa":"/ˈsʌbstrʌktʃə/","tag":"near synonym in engineering","definition":"the foundations or lower part of a building. sub- 'under' and infra- 'below' point to the same layer from different roots.","definitionCN":"建筑的根基或下部。sub-「在下」与 infra-「在下」从不同词根指向同一层。"},{"word":"instruction","ipa":"/ɪnˈstrʌkʃn/","tag":"same struere, another prefix","definition":"teaching or an order. It is in- 'into' plus struere 'build': building knowledge into a mind, not building below a road.","definitionCN":"教导；指令。它是 in-「向内」加 struere「建造」：把知识建进头脑，而不是在道路下面建造。"}]},{"heading":"NEAR MEANING","entries":[{"word":"facilities","ipa":"/fəˈsɪlətiz/","tag":"individual amenities","definition":"buildings, equipment, or services provided for a particular purpose. Facilities are countable items; infrastructure is the connected base they sit on.","definitionCN":"为特定用途提供的建筑、设备或服务。facilities 是可数的单项，infrastructure 是它们所坐落的连成一片的底座。"},{"word":"utilities","ipa":"/juːˈtɪlətiz/","tag":"water, gas, power","definition":"public services such as water, gas, and electricity. They are one sector of infrastructure, not the whole of it.","definitionCN":"水、燃气、电力等公共服务。它们是基础设施的一个部门，而不是全部。"},{"word":"framework","ipa":"/ˈfreɪmwɜːk/","tag":"organizational frame","definition":"a supporting structure of ideas or rules. It matches the organizational sense of infrastructure but usually has no physical layer.","definitionCN":"支撑性的观念或规则结构。它对应 infrastructure 的组织义，但通常没有物理层。"},{"word":"foundation","ipa":"/faʊnˈdeɪʃn/","tag":"the base itself","definition":"the solid base on which a building or an idea rests. It is the base, while infrastructure is the whole system of bases and services.","definitionCN":"建筑或观念所依托的坚固底座。它指底座本身，infrastructure 则指整套底座与服务系统。"}]}]},"mnemonics":{"normalIntro":{"en":"The word is a transparent compound: infra 'below' plus structure 'build'. Everything else is the same image applied to pipes, organizations, networks, and ideas.","cn":"这个词是透明的复合词：infra「在下」加 structure「建造」。其余义项都是同一幅图用在管道、组织、网络与观念上。"},"normal":[{"en":"infra 'below' + structure 'building': infrastructure is the building that lies below the building you can see.","cn":"infra「在下」+ structure「建造物」：infrastructure 就是躺在那栋看得见的建筑下面的建筑。"},{"en":"infra is related to inferior 'lower', not to the negative in-; do not read it as 'not structure'.","cn":"infra 与 inferior「更低的」同族，与否定前缀 in- 无关；不要把它读成「不是结构」。"},{"en":"The stru- root recurs in structure, construct, instruct, destroy: all are about putting up or pulling down a build.","cn":"stru- 词根在 structure、construct、instruct、destroy 中重现：都与搭起或拆掉一个建造物有关。"},{"en":"Water pipes under a street, servers under a website, procedures under a company: each is the layer that must exist first.","cn":"街道下的水管、网站下的服务器、公司下的流程：每一样都是必须先存在的那一层。"},{"en":"The word began with railways, moved to armies, then to economies and the internet without changing its picture.","cn":"这个词从铁路开始，转到军队，再转到经济与互联网，图景始终没变。"}],"abstract":[{"en":"Think of a tree: the canopy is what you see, but the root system is its infrastructure, and it is wider than the crown.","cn":"想象一棵树：树冠是你看见的，根系就是它的基础设施，而且比树冠更宽。"},{"en":"Think of a stage: the actors are visible, the scaffolding and trapdoors are the infrastructure that lets the play happen.","cn":"想象一个舞台：演员是看得见的，脚手架与活动地板就是让戏能发生的基础设施。"},{"en":"Think of a city at night: the lights show the surface, but the cables feeding them run unseen beneath.","cn":"想象夜里的城市：灯光显示表面，给它们供电的电缆却在下面看不见地延伸。"}]},"examples":[{"en":"Decades of underinvestment left the railway infrastructure close to collapse.","cn":"数十年的投资不足让铁路基础设施濒临崩溃。"},{"en":"The agency classified the power grid as critical infrastructure.","cn":"该机构把电网列为关键基础设施。"},{"en":"A reliable digital infrastructure is now as important as roads to a new firm.","cn":"对新公司而言，可靠的数字基础设施如今和道路一样重要。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"infra（在下）+ structure（建造物）——看得见的城市下面还有一层看不见的建造物：管道、电缆、地基，这就是「基础设施」；组织与网络的底层架构也借用了这幅图。","word":"infrastructure"},"root":"拉丁 infra「在下、低于」（与 inferior「更低的」同源，注意不是否定前缀 in-）+ 拉丁 structura「建造、构造」← struere「建造、堆积」。一般认为该复合词出自 19 世纪法语工程术语，原指铁路、道路的「下部结构」。","sensesIntro":{"en":"Nine senses all keep one picture: the layer below that carries the layer above. The layer may be made of pipes, concrete, procedures, servers, or trust.","cn":"九个义项都守住一幅图：下面那一层承托上面那一层。这一层可以是管道、混凝土、程序、服务器，也可以是信任。"},"semanticMap":{"core":{"en":"CORE IMAGE: an unseen lower layer that carries everything built above it.","cn":"核心意象：一层看不见的下层，承托着上面建起的一切。"},"chain":["THE LAYER BELOW","CARRYING THE WEIGHT","PIPES AND ROADS","THE ORGANIZATION'S FRAME","NETWORKS AND SYSTEMS","THE BASE OF ANYTHING"],"branches":[{"senses":"S01 · S03","en":"PHYSICAL BASE: the works a society needs, and the utilities that run beneath its streets.","cn":"物理底座：社会所需的工程，以及在其街道之下运行的公用设施。"},{"senses":"S02","en":"THE ENGINEERING LAYER: the substructure under a road, bridge, or railway.","cn":"工程层：道路、桥梁或铁路之下的下部结构。"},{"senses":"S04 · S09","en":"THE INVISIBLE FRAME: the systems under an organization, and the base of any idea or activity.","cn":"看不见的框架：组织之下的制度，以及任何观念或活动的底座。"},{"senses":"S05 · S07","en":"NETWORKS THAT CARRY AN ECONOMY: computing systems, and the transport and power base of markets.","cn":"承载经济的网络：计算系统，以及市场的交通与能源底座。"},{"senses":"S06 · S08","en":"INSTALLATIONS FOR A SOCIETY: fixed military bases, and the schools and hospitals that support social life.","cn":"社会的设施：固定的军事基地，以及支撑社会生活的学校与医院。"}]},"affixes":{"intro":{"en":"Infrastructure is a compound of the Latin prefix infra- and the noun structure. Both halves are still readable in English, which is why the word can be extended to organizations and software without losing its image.","cn":"infrastructure 是拉丁前缀 infra- 与名词 structure 的复合词。两半在英语里仍可辨认，所以这个词能扩展到组织与软件而不丢失意象。"},"latinIntro":{"en":"infra 'below' belongs with inferus and inferior; struere 'to build' yields structura and a large English family: structure, construct, instruct, destroy. The prefix in- in instruct is 'into', not infra.","cn":"infra「在下」与 inferus、inferior 同族；struere「建造」产生 structura 以及庞大的英语词族：structure、construct、instruct、destroy。instruct 里的 in- 是「向内」，不是 infra。"},"items":[{"word":"infrastructure","structure":"infra- (below) + structure (a building)","meaning":"the lower works on which a society or system depends","meaningCN":"社会或体系所依赖的下层工程与设施","example":"The flood exposed how fragile the infrastructure was.","exampleCN":"洪水暴露出基础设施多么脆弱。"},{"word":"infrastructural","structure":"infrastructure + -al","meaning":"relating to infrastructure","meaningCN":"与基础设施相关的","example":"The plan faces infrastructural and legal obstacles.","exampleCN":"该计划面临基础设施与法律上的障碍。"},{"word":"superstructure","structure":"super- (above) + structure","meaning":"the part built above the base","meaningCN":"建于基础之上的上部结构","example":"Steel cables tie the superstructure to the piers.","exampleCN":"钢索把上部结构系在桥墩上。"},{"word":"substructure","structure":"sub- (under) + structure","meaning":"the foundations or lower part","meaningCN":"下部结构；基础","example":"Workers inspected the substructure for cracks.","exampleCN":"工人检查了下部结构有无裂缝。"},{"word":"structure","structure":"Latin structura, from struere (to build)","meaning":"a building; the arrangement of parts","meaningCN":"建筑物；各部分的构造","example":"The structure survived the earthquake.","exampleCN":"这座建筑在地震中幸存下来。"},{"word":"instruct","structure":"in- (into) + struere (to build)","meaning":"to build knowledge into a mind; to teach","meaningCN":"把知识建进头脑；教导","example":"The coach instructed the team on the new formation.","exampleCN":"教练指导球队使用新阵型。"},{"word":"construct","structure":"con- (together) + struere","meaning":"to build by putting parts together","meaningCN":"把部件组合起来建造","example":"They constructed a footbridge over the stream.","exampleCN":"他们在溪上建了一座人行桥。"},{"word":"destruction","structure":"de- (down, away) + struere + -tion","meaning":"the tearing down of a built thing","meaningCN":"拆毁建造物；破坏","example":"The flood caused widespread destruction.","exampleCN":"洪水造成了大范围破坏。"},{"word":"cyberinfrastructure","structure":"cyber- + infrastructure","meaning":"the networks and systems behind computing","meaningCN":"计算背后的网络与系统；网络基础设施","example":"The lab applied for funds to upgrade its cyberinfrastructure.","exampleCN":"实验室申请资金升级网络基础设施。"}],"latinEntries":[{"word":"infra","structure":"Latin prefix/preposition infra","meaning":"below, beneath","meaningCN":"在下；低于"},{"word":"struere","structure":"struere (to build)","meaning":"to pile up, build, arrange","meaningCN":"堆积；建造；安排"},{"word":"structura","structure":"struere + -tura (result noun)","meaning":"a building; the way parts are put together","meaningCN":"建筑物；构造方式"}]}},{"word":"innovative","ipa_uk":"/ɪˈnɒvətɪv/","ipa_us":"/ˈɪnəveɪtɪv/","definition_zh":"创新的；革新的；有创新精神的；新颖独特的","definition_en":"introducing or using new ideas, methods, or designs; original and inventive","core_image":"旧作坊里，师傅把祖传的榫头拆下，换上自己削的新榫，第一次让那扇卡了多年的柜门合上","scene":"The firm's innovative design replaced three parts with one, and cut assembly time by half.","sceneCN":"这里 innovative 是「创新的」（第 1 个义项：引入新方法、新设计的）；句意：这家公司的创新设计用一个小零件替代了三个，还把装配时间缩短了一半。图中可辨识物件：零件图、装配台、计时器。","pos":[{"tag":"adj.","zh":"创新的；革新的；有创新精神的；新颖的"}],"collocations":[{"phrase":"innovative approach","zh":"创新方法"},{"phrase":"innovative technology","zh":"创新技术"},{"phrase":"innovative design","zh":"新颖的设计"},{"phrase":"highly innovative","zh":"极具创新性的"},{"phrase":"innovative thinking","zh":"创新思维"},{"phrase":"innovative company","zh":"创新型企业"}],"forms":[{"label":"比较级","form":"more innovative"},{"label":"最高级","form":"most innovative"},{"label":"副词","form":"innovatively"},{"label":"名词","form":"innovativeness"}],"derivatives":[{"word":"innovate","pos":"v.","zh":"创新；革新"},{"word":"innovation","pos":"n.","zh":"创新；革新；新事物"},{"word":"innovator","pos":"n.","zh":"创新者；革新者"},{"word":"innovatory","pos":"adj.","zh":"创新的；革新的"},{"word":"innovatively","pos":"adv.","zh":"以创新的方式"}],"senses":[{"no":"01","title":"Introducing new methods","titleCN":"创新的：把新办法放进旧流程里","definition":"using or introducing new ideas, methods, or processes","definitionCN":"使用或引入新观念、新方法或新流程的","example":"The team took an innovative approach to scheduling.","exampleCN":"这个团队在排班问题上采用了创新方法。","why":"Latin innovare is in- 'into' plus novare 'to make new', from novus 'new'. Innovative marks the act of putting a new thing into an existing order.","whyCN":"拉丁 innovare 是 in-「向内」加 novare「使新」，后者来自 novus「新」。innovative 标记的是把新东西放进既有秩序的动作。"},{"no":"02","title":"Original and inventive","titleCN":"有独创性的：不是抄来的","definition":"showing original thought rather than copying what already exists","definitionCN":"表现出原创思想而非照搬既有之物的","example":"Her innovative use of recycled glass won the prize.","exampleCN":"她对回收玻璃的独创性使用赢得了奖项。","why":"The verb's core is renewal: novare is to make new again. Originality is the visible sign that something has been made new rather than copied.","whyCN":"这个动词的核心是更新：novare 就是重新使新。独创性就是某物被重新做成、而非照抄的可见标志。"},{"no":"03","title":"New and unusual in form","titleCN":"新颖独特的：样子不照旧例","definition":"new, different, and rather unusual in form or style","definitionCN":"在形式或风格上新奇、不同、颇为少见的","example":"The chairs have an innovative shape that saves space.","exampleCN":"这些椅子的造型新颖，能节省空间。","why":"Novus simply means new. When the new thing is also strange to the old order, the adjective carries the extra sense of 'unfamiliar in form'.","whyCN":"novus 本义就是「新」。当新东西同时对旧秩序显得陌生时，这个形容词就多出「形式不熟悉」的含义。"},{"no":"04","title":"Forward-looking and reform-minded","titleCN":"革新进取的：愿意改动旧规矩","definition":"favoring change and improvement rather than keeping things as they are","definitionCN":"倾向改变与改进、而非维持现状的","example":"The mayor ran on an innovative housing plan.","exampleCN":"市长以一份革新的住房计划参加竞选。","why":"Innovare also meant to alter, to change an established arrangement. A forward-looking policy keeps putting new material into the old frame.","whyCN":"innovare 也有「改动、改变既定安排」之义。进取的政策就是不断把新材料放进旧框架。"},{"no":"05","title":"Creative by habit","titleCN":"有创新精神的：这个人习惯另想一条路","definition":"of a person, naturally creative and resourceful in solving problems","definitionCN":"指人天生善于创造、能灵活解决问题的","example":"She is an innovative engineer who never accepts the first answer.","exampleCN":"她是一位有创新精神的工程师，从不接受第一个答案。","why":"A person is called innovative when renewing is a habit, not a single act. The suffix -ive marks a disposition, not one event.","whyCN":"一个人被称为 innovative，是因为「更新」是他的习惯，而不是一次行为。-ive 后缀标记的是性情，不是单个事件。"},{"no":"06","title":"Original in construction","titleCN":"设计新颖的：零件摆法本身就是新的","definition":"of a product or design, built in a new way rather than merely decorated","definitionCN":"指产品或设计以新方式构造，而不只是换了外观","example":"The phone's innovative hinge removes the need for a case.","exampleCN":"这款手机新颖的铰链设计省去了保护壳。","why":"In design, newness must be built into the object's construction. The word is used of products whose arrangement of parts is itself new.","whyCN":"在设计里，新必须被建进物体的构造之中。这个词用于那些零件排列本身就是新的产品。"},{"no":"07","title":"Ingenious and unexpected","titleCN":"别出心裁的：绕开老堵点的新路线","definition":"of a solution or idea, clever and not obvious","definitionCN":"指解决办法或想法巧妙而不显而易见的","example":"An innovative fix cut the queue without adding staff.","exampleCN":"一个别出心裁的解决办法在没加人的情况下缩短了排队。","why":"A solution is ingenious when a new route is found around an old block. Innovation is the route, not necessarily new technology.","whyCN":"当一条新路线绕过老堵点时，办法就显得巧妙。创新的重点是那条路线，不一定是新技术。"},{"no":"08","title":"Willing to remake itself","titleCN":"勇于变革的：组织肯改自己的流程","definition":"of an organization, willing to change its own procedures and products","definitionCN":"指组织愿意改变自身流程与产品的","example":"An innovative firm will test a bad idea quickly and drop it.","exampleCN":"勇于变革的公司会快速试验一个坏主意，然后放弃它。","why":"An organization is innovative when it keeps changing its own procedures. The word measures willingness to renew, not size or age.","whyCN":"一个组织不断改变自己的流程，就是 innovative。这个词衡量的是更新的意愿，不是规模或年龄。"},{"no":"09","title":"Fresh in performance","titleCN":"别开生面的：旧文本被读出新东西","definition":"of a performance or interpretation, presented in a fresh and original way","definitionCN":"指表演或诠释以新鲜、原创的方式呈现的","example":"The director gave the old play an innovative reading.","exampleCN":"导演为这部老戏作出了别开生面的诠释。","why":"A performance is fresh when the old text is renewed by a new reading. The root sense of making new again fits exactly.","whyCN":"当旧文本被新的读法更新时，表演就显得新鲜。词根「重新使新」的意义在这里正好吻合。"}],"etymology":{"intro":{"en":"Innovative is innovate plus -ive. Innovate comes from Latin innovare 'to make new, renew, alter', built on novus 'new'. The word is about renewal inside an existing order, not about coming upon something for the first time.","cn":"innovative 是 innovate 加 -ive。innovate 来自拉丁 innovare「使新、更新、改变」，建立在 novus「新」上。这个词讲的是在既有秩序内部更新，而不是第一次碰见某物。"},"items":[{"era":"LATIN ADJECTIVE novus","en":"novus meant 'new, fresh, recent'. It is the source of novel, novelty, renovate, and novice, all built on the same idea of freshness.","cn":"novus 意为「新的、新鲜的、近期的」。它是 novel、novelty、renovate、novice 的来源，全部建立在同一个「新鲜」观念上。"},{"era":"LATIN VERB novare","en":"novare meant 'to make new, renew'. It takes an existing thing and freshens it, rather than creating out of nothing.","cn":"novare 意为「使新、更新」。它取来一个已存在之物并使其新鲜，而不是从无到有地创造。"},{"era":"LATIN VERB innovare","en":"in- 'into' plus novare gives 'to renew, alter, bring in something new'. This verb is not related to invent, which is in- plus venire 'to come': coming upon versus making new.","cn":"in-「向内」加 novare 得到「更新、改变、引入新物」。这个动词与 invent 无关，后者是 in- 加 venire「来」：一个是碰见，一个是使新。"},{"era":"LATIN NOUN innovatio","en":"innovatio named the act of renewing. English innovation, borrowed in the sixteenth century, first meant a new thing introduced into an order.","cn":"innovatio 指更新的动作。英语 innovation 于 16 世纪借入，最初指被引入某种秩序的新事物。"},{"era":"SUFFIX -ive","en":"Latin -ivus 'having the nature of' gives English -ive. Innovative therefore means 'having the nature of renewing', a disposition or quality rather than a single deed.","cn":"拉丁 -ivus「具有某种性质的」产生英语 -ive。因此 innovative 意为「具有更新性质的」，是一种性情或品质，而不是单次行为。"},{"era":"MODERN KEYWORD","en":"In the twentieth century innovation became a keyword in economics and management, and innovative became a standard term of praise for firms, designs, and people.","cn":"20 世纪，innovation 成为经济学与管理学的关键词，innovative 则成为称赞企业、设计与人的常用词。"}]},"similar":{"note":{"en":"The first group contrasts two Latin roots that English speakers often confuse: novare 'make new' and venire 'come'. The second group holds words for newness or creativity that do not share the renewal image.","cn":"第一组对照两个英语使用者常混淆的拉丁词根：novare「使新」与 venire「来」。第二组是表示「新」或「有创造力」、但不共享「更新」意象的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"innovate","ipa":"/ɪˈnəʊveɪt/","tag":"base verb","definition":"to introduce new methods or ideas. It is the verb behind innovative, built on novus 'new'.","definitionCN":"引入新方法或新观念。它是 innovative 所依据的动词，建立在 novus「新」上。"},{"word":"innovation","ipa":"/ˌɪnəˈveɪʃn/","tag":"same base, noun","definition":"the act of renewing, or the new thing introduced. It names the deed or the result; innovative names the quality.","definitionCN":"更新的行为，或被引入的新事物。它指行为或结果，innovative 指性质。"},{"word":"invent","ipa":"/ɪnˈvent/","tag":"different root: venire","definition":"to create something not existing before. It is in- plus venire 'to come upon', not in- plus novare; finding is not the same as renewing.","definitionCN":"创造此前不存在之物。它是 in- 加 venire「碰见」，不是 in- 加 novare；发现与更新不是一回事。"},{"word":"inventive","ipa":"/ɪnˈventɪv/","tag":"same -ive, different root","definition":"skilled at inventing. It looks like innovative and shares the suffix, but its base is invent, with venire behind it.","definitionCN":"善于发明的。它形似 innovative、共享后缀，但词基是 invent，背后是 venire。"}]},{"heading":"NEAR MEANING","entries":[{"word":"creative","ipa":"/kriˈeɪtɪv/","tag":"making new things","definition":"able to produce original ideas or works. Creative is broader; innovative usually implies putting the new idea to practical use.","definitionCN":"能产生原创观念或作品的。creative 更宽，innovative 通常意味着把新观念投入实际使用。"},{"word":"original","ipa":"/əˈrɪdʒənl/","tag":"not derived","definition":"not copied or derived from something else. It stresses source; innovative stresses the act of renewal and its usefulness.","definitionCN":"不是抄来或派生而来的。它强调来源，innovative 强调更新的动作及其用处。"},{"word":"novel","ipa":"/ˈnɒvl/","tag":"newness alone","definition":"new and unusual. It shares the novus root but stops at newness; innovative adds the sense of a working change.","definitionCN":"新的、不寻常的。它共享 novus 词根，但只停在「新」；innovative 还包含「能运作的改变」。"},{"word":"groundbreaking","ipa":"/ˈɡraʊndbreɪkɪŋ/","tag":"first of its kind","definition":"pioneering, opening a new field. It is stronger and rarer than innovative, and it pictures breaking new ground rather than renewing an old thing.","definitionCN":"开创性的；开辟新领域的。它比 innovative 更强、更少见，画面是破开新地，而不是更新旧物。"}]}]},"mnemonics":{"normalIntro":{"en":"The family turns on novus 'new': novare makes a thing new, innovare brings the new into an order, and innovative describes the quality of doing so.","cn":"这个词族围绕 novus「新」转动：novare 使某物变新，innovare 把新带入某种秩序，innovative 描述这样做的性质。"},"normal":[{"en":"in- 'into' + novus 'new': innovative means putting something new into what already exists.","cn":"in-「向内」+ novus「新」：innovative 就是把新东西放进已经存在的东西里。"},{"en":"The nov- root recurs in novel, novelty, renovate, and novice; each keeps the idea of freshness.","cn":"nov- 词根在 novel、novelty、renovate、novice 中重现，每一个都保留「新鲜」的观念。"},{"en":"innovate is not invent: novare is 'make new', venire is 'come'. Renewing an old order differs from finding something new.","cn":"innovate 不是 invent：novare 是「使新」，venire 是「来」。更新旧秩序不同于发现新东西。"},{"en":"-ive marks a habit or quality, so an innovative person is one who renews repeatedly, not once.","cn":"-ive 标记习惯或品质，所以 innovative 的人是一再更新的人，而不是只做一次的人。"},{"en":"An innovator is the person; innovation is the deed or the new thing; innovative is the adjective that praises either.","cn":"innovator 是人；innovation 是行为或新事物；innovative 是用来称赞二者的形容词。"}],"abstract":[{"en":"Think of a new graft on an old tree: the tree is not replaced, but it bears fruit it could not bear before.","cn":"想象在一棵老树上嫁接新枝：树没有被换掉，却结出了从前结不出的果子。"},{"en":"Think of a door that has stuck for years: innovative is not a new house, just a new hinge that finally lets the old door move.","cn":"想象一扇卡了多年的门：innovative 不是新房子，只是一个终于让旧门动起来的新铰链。"},{"en":"Think of a wall across a road: innovative is the narrow path found around it, not a faster car.","cn":"想象路中央有一堵墙：innovative 是绕过去的那条窄路，而不是更快的车。"}]},"examples":[{"en":"The clinic introduced an innovative system for booking appointments by text message.","cn":"这家诊所引入了一套通过短信预约的创新系统。"},{"en":"Her innovative thesis combined two fields that had never spoken to each other.","cn":"她那篇有独创性的论文把两个从未交流过的领域结合了起来。"},{"en":"The company is innovative not because it buys new machines, but because it questions its own routines.","cn":"这家公司勇于变革，不是因为它买新机器，而是因为它质疑自己的惯例。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in（进入）+ nov（新）+ ative（具有某种性质的）——把「新」带进旧东西里，就是「创新的」；nov 同族见 novel、renovate。别和 invent 混：invent 的词根是 venire「来」，指碰见、发明。","word":"innovative"},"root":"拉丁 innovare「使更新、改变」（in-「进入」+ novus「新」，novare「使新」）+ -ive（拉丁 -ivus「具有某种性质的」）；nov- 与 novel、renovate、novice 同源。注意 innovate 与 invent（in- + venire「来」）不同源。","sensesIntro":{"en":"Nine senses all turn on making something new inside an existing order: a method, an object, a habit, an institution, or a reading of an old text.","cn":"九个义项都围绕「在既有秩序里使某物变新」：方法、物件、习惯、机构，或对旧文本的一种读法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a new part fitted into an old whole so that the whole works better.","cn":"核心意象：把一个新的部件装进旧整体，让整体运转得更好。"},"chain":["MAKE NEW","PUT IN A NEW METHOD","THINK DIFFERENTLY","DESIGN SOMETHING UNSEEN","LEAD CHANGE","FRESHEN WHAT EXISTS"],"branches":[{"senses":"S01 · S03","en":"THE NEW ENTERS: a new method put into use, and a form that looks unfamiliar beside the old one.","cn":"新的进入：被投入使用的新方法，以及在旧形式旁显得陌生的新形式。"},{"senses":"S02 · S05","en":"ORIGINALITY: work that is not copied, and a person whose habit is to renew.","cn":"独创性：不是抄来的作品，以及以更新为习惯的人。"},{"senses":"S04 · S08","en":"THE WILL TO CHANGE: a reform-minded policy, and an organization that remakes its own routines.","cn":"改变的意愿：倾向改革的政策，以及重塑自身惯例的组织。"},{"senses":"S06 · S07","en":"BUILT DIFFERENTLY: a product whose parts are newly arranged, and a solution that finds an unexpected route.","cn":"不同的造法：零件被重新排列的产品，以及找到意外路线的办法。"},{"senses":"S09","en":"THE OLD TEXT RENEWED: a performance that makes a familiar work feel new.","cn":"旧文本被更新：让熟悉作品显得新鲜的演绎。"}]},"affixes":{"intro":{"en":"Innovative is innovate plus -ive. The base verb is Latin innovare, from novus 'new'; the suffix -ive marks a quality. The word family around nov- is large and still productive.","cn":"innovative 是 innovate 加 -ive。词基动词是拉丁 innovare，来自 novus「新」；后缀 -ive 标记性质。围绕 nov- 的词族庞大且仍有能产性。"},"latinIntro":{"en":"Latin novus 'new' yields novare 'make new', innovare 'renew, alter', and novitas 'newness'. English novel, renovate, and novice descend from the same base; invent belongs to venire 'come' and must be kept apart.","cn":"拉丁 novus「新」产生 novare「使新」、innovare「更新、改变」与 novitas「新奇」。英语 novel、renovate、novice 出自同一词基；invent 属于 venire「来」，必须分开。"},"items":[{"word":"innovate","structure":"in- (into) + novare (to make new)","meaning":"to bring in new methods or ideas","meaningCN":"引入新方法或新观念","example":"Small firms often innovate faster than large ones.","exampleCN":"小公司往往比大公司创新更快。"},{"word":"innovation","structure":"innovare + -atio (action and result noun)","meaning":"the act of renewing; a new thing introduced","meaningCN":"更新的行为；被引入的新事物","example":"The design was hailed as a genuine innovation.","exampleCN":"这项设计被誉为真正的创新。"},{"word":"innovative","structure":"innovate + -ive (Latin -ivus)","meaning":"having the quality of renewing or introducing new things","meaningCN":"具有更新或引入新物之性质的","example":"They built an innovative low-cost sensor.","exampleCN":"他们造出了一个创新的低成本传感器。"},{"word":"innovatively","structure":"innovative + -ly","meaning":"in an innovative way","meaningCN":"以创新的方式","example":"The space is innovatively used as both office and gallery.","exampleCN":"这个空间被创新地同时用作办公室与画廊。"},{"word":"innovativeness","structure":"innovative + -ness","meaning":"the quality of being innovative","meaningCN":"创新性；创新程度","example":"The survey ranked countries by innovativeness.","exampleCN":"这项调查按创新性对各国进行排名。"},{"word":"innovator","structure":"innovate + -or (agent noun)","meaning":"one who introduces new methods","meaningCN":"创新者；革新者","example":"She is remembered as an innovator in battery design.","exampleCN":"她作为电池设计领域的创新者而被铭记。"},{"word":"innovatory","structure":"innovate + -ory (adjective)","meaning":"having the character of innovation","meaningCN":"有创新性质的","example":"The scheme was innovatory for its time.","exampleCN":"这项方案在当时颇具创新性。"},{"word":"novel","structure":"Latin novellus, diminutive of novus (new)","meaning":"new and unusual; a long story","meaningCN":"新奇的；长篇小说（词根同为「新」）","example":"They tried a novel way of cooling the roof.","exampleCN":"他们尝试了一种给屋顶降温的新奇方法。"},{"word":"renovate","structure":"re- (again) + novare (make new)","meaning":"to make an old building new again","meaningCN":"翻新；修复（重新使新）","example":"The trust renovated the old mill into a museum.","exampleCN":"该基金会把老磨坊翻新成了博物馆。"}],"latinEntries":[{"word":"novus","structure":"novus (new)","meaning":"new, fresh, recent","meaningCN":"新的；新鲜的；近期的"},{"word":"novare","structure":"novus + -are (verb)","meaning":"to make new, renew","meaningCN":"使新；更新"},{"word":"innovare","structure":"in- (into) + novare","meaning":"to renew, alter, bring in new things","meaningCN":"更新；改变；引入新物"},{"word":"-ivus","structure":"Latin adjective suffix -ivus","meaning":"having the nature of, tending to","meaningCN":"具有某种性质的；倾向于"}]}},{"word":"institutional","ipa_uk":"/ˌɪnstɪˈtjuːʃənl/","ipa_us":"/ˌɪnstɪˈtuːʃənl/","definition_zh":"机构的；制度的；体制化的；机构投资者的；机构照护的","definition_en":"relating to an institution (an established organization, custom, or system); typical of large organizations; also used in fixed phrases such as institutional investor or institutional care","core_image":"一栋挂着门牌、贴满规章、编好序列号的大楼：人一进门，就被同一套流程接住","scene":"The reform was blocked less by law than by institutional inertia inside the ministry.","sceneCN":"这里 institutional 是「机构化的、大型机构特有的」（第 3 个义项：按规章办事而缺乏人情味的作风）；句意：改革与其说被法律挡住，不如说被部委内部那种机构惰性挡住。图中可辨识物件：部委走廊、成堆文件、停滞的印章。","pos":[{"tag":"adj.","zh":"机构的；制度的；体制化的；机构投资者的"}],"collocations":[{"phrase":"institutional framework","zh":"制度框架"},{"phrase":"institutional investor","zh":"机构投资者"},{"phrase":"institutional care","zh":"机构照护"},{"phrase":"institutional racism","zh":"制度性种族主义"},{"phrase":"institutional memory","zh":"机构记忆"},{"phrase":"institutional review board","zh":"机构审查委员会"}],"forms":[{"label":"比较级","form":"more institutional"},{"label":"最高级","form":"most institutional"},{"label":"副词","form":"institutionally"}],"derivatives":[{"word":"institution","pos":"n.","zh":"机构；制度；设立"},{"word":"institutionally","pos":"adv.","zh":"在制度上；以机构方式"},{"word":"institutionalize","pos":"v.","zh":"使制度化；把某人送入机构"},{"word":"institutionalization","pos":"n.","zh":"制度化；机构化"},{"word":"institutionalism","pos":"n.","zh":"制度主义；对机构的依赖"}],"senses":[{"no":"01","title":"Relating to an established organization","titleCN":"机构的；组织上的","definition":"connected with an institution such as a university, bank, hospital, or government body","definitionCN":"与大学、银行、医院或政府机关等机构相关的","example":"The report examines the institutional structure of the university.","exampleCN":"该报告考察这所大学的机构结构。","why":"Latin instituere means 'to set in place'. An institution is something set up and left standing; institutional describes whatever belongs to that set-up organization.","whyCN":"拉丁 instituere 意为「安置、设立」。institution 是被设立并持续站立的东西；institutional 描述属于这一已设立组织的事物。"},{"no":"02","title":"Relating to an established custom or system","titleCN":"制度上的；体制性的","definition":"connected with a long-established custom, rule, or social system rather than with a single organization","definitionCN":"与长期确立的习俗、规则或社会制度相关，而非与单一组织相关","example":"Institutional resistance to change can outlast any single government.","exampleCN":"制度层面对变革的抵制可能比任何一届政府都更持久。","why":"The noun institution also names a custom or system that society sets up and keeps standing; the adjective simply extends to that abstract level.","whyCN":"名词 institution 也指社会设立并维持的习俗或制度；形容词只是把意义扩展到这一抽象层面。"},{"no":"03","title":"Typical of a large organization","titleCN":"机构化的；大型机构特有的（常含贬义）","definition":"showing the impersonal, rule-bound habits typical of large organizations","definitionCN":"表现出大型组织特有的、按规章办事而缺乏人情味的作风","example":"His institutional tone made the apology sound like an internal circular.","exampleCN":"他那套机构化的腔调让道歉听起来像一份内部通函。","why":"When an organization grows, its procedures harden; the adjective then describes behaviour shaped by the machinery of the place rather than by a person.","whyCN":"组织变大后，其程序会硬化；这个形容词于是描述由该处机器般流程而非个人塑造的行为。"},{"no":"04","title":"Of an institutional investor","titleCN":"机构投资者的","definition":"relating to a large organization that invests funds on behalf of others, such as a pension fund or an insurance company","definitionCN":"与代表他人投资的大型组织（如养老基金或保险公司）相关的","example":"Institutional buying pushed the share price up sharply.","exampleCN":"机构买盘把股价迅速推高。","why":"Finance narrows the word to organizations that invest professionally; the actor is the institution, not a private person.","whyCN":"金融领域把该词窄化为专业投资的机构；行动者是机构，而非私人。"},{"no":"05","title":"Provided by an institution rather than a family","titleCN":"机构照护的；由机构提供的","definition":"describing care given in a residential institution rather than at home","definitionCN":"描述在住宿制机构而非在家中提供的照护","example":"Demand for institutional care rose as families grew smaller.","exampleCN":"随着家庭规模变小，对机构照护的需求上升。","why":"The word marks the provider: care is supplied by an institution, a place set up for that purpose.","whyCN":"该词标明提供者：照护由机构提供，而机构正是为该目的设立的地方。"},{"no":"06","title":"Fixed by convention; routinized","titleCN":"已成惯例的；例行化的","definition":"established as a routine or convention, so that it is no longer questioned","definitionCN":"已作为例行程序或惯例确立，因此不再受到质疑","example":"The Friday meeting had become an institutional habit no one dared cancel.","exampleCN":"周五的会议已变成一种没人敢取消的机构惯例。","why":"What has been set up long enough becomes part of the furniture; institutional here means built into the routine.","whyCN":"被设立得足够久的东西会成为固定陈设；此处 institutional 意为已嵌入例行程序。"},{"no":"07","title":"Relating to institutional advertising","titleCN":"机构形象广告的","definition":"relating to advertising that promotes the image of a company or organization rather than a particular product","definitionCN":"与推广公司或组织形象而非特定产品的广告相关的","example":"The firm spent more on institutional advertising than on product campaigns.","exampleCN":"这家公司在机构形象广告上的投入超过产品推广。","why":"Such advertising sells the institution itself, its reputation and standing, not a single product on a shelf.","whyCN":"这类广告卖的是机构本身，即其声誉与地位，而非货架上的单一产品。"},{"no":"08","title":"Of an ethics or review board","titleCN":"机构审查（委员会）的","definition":"relating to a formal committee that reviews research or ethics within an institution","definitionCN":"与机构内部审查研究或伦理的正式委员会相关的","example":"All proposals must pass institutional review before data collection begins.","exampleCN":"所有提案在开始收集数据前都必须通过机构审查。","why":"The board acts as the institution in miniature; its authority comes from the organization that sets it up.","whyCN":"该委员会是机构权力的缩影；其权限来自设立它的组织。"},{"no":"09","title":"Built into social structures","titleCN":"制度性的；结构性根源的","definition":"describing disadvantages or advantages embedded in the normal workings of social systems","definitionCN":"描述嵌入社会系统正常运作中的劣势或优势","example":"The study traces health gaps to institutional factors rather than individual choices.","exampleCN":"该研究把健康差距追溯到制度性因素，而非个人选择。","why":"Here the institution is not one building but the whole set of standing arrangements; what such arrangements produce is called institutional.","whyCN":"此处的 institution 不是一栋建筑，而是整套长期维持的安排；由这些安排产生的东西便被称为 institutional。"}],"etymology":{"intro":{"en":"Institutional is the adjective of institution with the suffix -al. The chain runs from a reconstructed Indo-European root for 'stand' through Latin stare and statuere to instituere 'set in place', then to Latin institutio, French, and English institution.","cn":"institutional 是 institution 加后缀 -al 构成的形容词。链条从表示「站立」的原始印欧语重构词根，经拉丁 stare 与 statuere，到 instituere「安置、设立」，再到拉丁 institutio、法语和英语 institution。"},"items":[{"era":"PROTO-INDO-EUROPEAN *sta-","en":"The reconstructed root *sta- 'to stand' is generally thought to underlie Latin stare. The star marks a reconstructed form, not a recorded word.","cn":"原始印欧语重构形式 *sta- 意为「站立」，一般认为它是拉丁 stare 的来源；星号表示重构，并非实际记录的词。"},{"era":"LATIN stare","en":"stare meant 'to stand, be standing'. It is the simple verb of standing that all the stat- words grow from.","cn":"stare 意为「站立、站着」。它是所有 stat- 词族所生长的最简动词。"},{"era":"LATIN statuere","en":"statuere is the causative of stare: 'to cause to stand, set up, place'. What is set up is made to stand.","cn":"statuere 是 stare 的使动形式：「使站立、设立、放置」。被设立的东西就是被使其站立。"},{"era":"LATIN instituere","en":"in- 'into, upon' + statuere gives instituere 'to set in place, establish, arrange'. Here in- means 'into or upon', not the negative 'not'.","cn":"in-「进入、在上」+ statuere 构成 instituere「安置、设立、安排」。这里的 in- 表示「进入、在上」，不是否定前缀「不」。"},{"era":"LATIN institutio","en":"institutio meant 'an arrangement, establishment, instruction'. It named both the act of setting up and the thing set up.","cn":"institutio 意为「安排、设立、教导」。它既指设立的动作，也指被设立的东西。"},{"era":"FRENCH AND ENGLISH -al","en":"Old French passed institution to English in the 14th century. English later added -al to form the adjective institutional, meaning 'of an institution'.","cn":"古法语把 institution 传入英语，时为 14 世纪。英语后来加上 -al 构成形容词 institutional，意为「属于机构的」。"}]},"similar":{"note":{"en":"The first group contains near-identical forms whose Latin prefixes or roots differ; the second contains words close in meaning.","cn":"第一组是形式相近但拉丁前缀或词根不同的词；第二组是意义相近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"institution","ipa":"/ˌɪnstɪˈtjuːʃn/","tag":"base noun","definition":"an established organization or custom; the noun behind institutional","definitionCN":"已建立的组织或习俗；institutional 所源自的名词"},{"word":"constitutional","ipa":"/ˌkɒnstɪˈtjuːʃənl/","tag":"shares *sta- but different prefix","definition":"relating to a constitution; from con- 'together' + statuere, not in- 'into', and about founding law rather than an organization","definitionCN":"与宪法相关的；来自 con-「一起」+ statuere，而非 in-「进入」，讲的是立国法律而非组织"},{"word":"institute","ipa":"/ˈɪnstɪtjuːt/","tag":"same verb, narrower noun","definition":"a learned society or research body; from the same instituere, but the noun usually names one specific body, not a custom","definitionCN":"学会或研究机构；来自同一 instituere，但名词通常指某个特定团体，而非习俗"},{"word":"instructional","ipa":"/ɪnˈstrʌkʃənl/","tag":"looks parallel, different root","definition":"relating to teaching; from struere 'build', not from stare 'stand', so the shared -ctional shape is misleading","definitionCN":"与教学相关的；来自 struere「建造」，而非 stare「站立」，因此相似的 -ctional 外形具有误导性"}]},{"heading":"NEAR MEANING","entries":[{"word":"organizational","ipa":"/ˌɔːɡənaɪˈzeɪʃənl/","tag":"organization-focused","definition":"relating to the structure of an organization; narrower than institutional, which also covers customs and systems","definitionCN":"与组织结构相关的；比 institutional 窄，后者还涵盖习俗与制度"},{"word":"systemic","ipa":"/sɪˈstemɪk/","tag":"system-wide","definition":"affecting the whole system; close to sense 09 but stresses the system rather than the established institution","definitionCN":"影响整个系统的；接近第 9 个义项，但强调系统而非已确立的制度"},{"word":"conventional","ipa":"/kənˈvenʃənl/","tag":"established by custom","definition":"following long-accepted practice; close to sense 06 but without the bureaucratic flavour","definitionCN":"遵循长期接受的做法的；接近第 6 个义项，但没有官僚色彩"},{"word":"bureaucratic","ipa":"/ˌbjʊərəˈkrætɪk/","tag":"rule-bound","definition":"run by officials and rules; close to sense 03 but names the administrative machine directly","definitionCN":"由官员和规章运转的；接近第 3 个义项，但直接点明行政机器"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'into, upon' + statuere 'set, stand' -> set into place -> institutional: of an institution. The in- is not the negative 'not'.","cn":"in-「进入、在上」+ statuere「设立、站立」→ 设立进去 → institutional 机构的、制度的。这里的 in- 不是否定「不」。"},{"en":"institution is the noun, -al makes the adjective, parallel to constitution and constitutional but with a different prefix.","cn":"institution 是名词，-al 构成形容词，与 constitution 和 constitutional 结构平行，但前缀不同。"},{"en":"institute is one learned body; institution is the standing arrangement; institutional belongs to the latter and to the wider system.","cn":"institute 是某一个学会；institution 是长期维持的安排；institutional 属于后者以及更广的制度。"},{"en":"institutionalize = make into an institution; -ize adds 'make', so the suffix marks a change of state.","cn":"institutionalize = 使成为制度；-ize 表示「使成为」，标记状态变化。"},{"en":"institutional memory means an organization remembers through files, habits, and old staff, not through one mind.","cn":"institutional memory 指组织通过档案、习惯和老员工记忆，而不是靠某一个头脑。"}],"abstract":[{"en":"Think of a building with a filing system: the building is the institution, and the air inside that shapes everyone is institutional.","cn":"把机构想象成一栋带档案系统的楼：楼是 institution，楼内塑造每个人的空气是 institutional。"},{"en":"Think of a river bed and its water: the institution is the channel, institutional is the direction the water is forced to take.","cn":"把制度想象成河床与水：institution 是河道，institutional 是水被迫流去的方向。"},{"en":"Think of a uniform issued by the place: institutional behaviour is the uniform speaking instead of the person.","cn":"把机构想象成发放制服的地方：机构化行为就是制服在说话，而不是人在说话。"}]},"examples":[{"en":"Institutional rules slowed the hiring process to a crawl.","cn":"机构规章把招聘流程拖得极慢。"},{"en":"The foundation is an institutional investor with a very long horizon.","cn":"该基金会是一家投资期限很长的机构投资者。"},{"en":"Researchers submitted the plan to the institutional review board.","cn":"研究人员把方案提交给机构审查委员会。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（向内）+ stituere（设立）：把规矩设立到组织内部 → institutional 机构的、制度的；注意 in- 在此不是「不」","word":"institutional"},"root":"拉丁 instituere「安置、设立」（in-「进入、在上」+ statuere「使站立」，statuere 出自 stare「站立」）；与 constitutional、statute、statue 同出原始印欧语重构词根 *sta-；此处 in- 不是否定前缀。","sensesIntro":{"en":"Nine senses radiate from one picture: something set up and left standing. An organization, a custom, a routine, a review board, and a social structure are all things that stand because they were instituted.","cn":"九个义项从一个画面辐射开来：被设立并持续站立的东西。组织、习俗、例行程序、审查委员会和社会结构，都是因为被设立才得以站立。"},"semanticMap":{"core":{"en":"CORE IMAGE: a set-up structure that stands and shapes whatever passes through it.","cn":"核心意象：一个被设立起来、持续站立并塑造经过其内部一切的结构。"},"chain":["SET IN PLACE","A STRUCTURE THAT STANDS","THE ORGANIZATION","THE CUSTOM OR SYSTEM","THE ROUTINE THAT HARDENS","THE SOCIAL STRUCTURE"],"branches":[{"senses":"S01 · S08","en":"ORGANIZATION: the institution as a body, including the board that acts in its name.","cn":"组织：作为团体的机构，包括以其名义行事的委员会。"},{"senses":"S02 · S06","en":"STANDING ARRANGEMENT: customs and routines that stay in place until they feel natural.","cn":"长期安排：习俗与例行程序长期在位，直到显得理所当然。"},{"senses":"S03 · S07","en":"ORGANIZATIONAL MACHINE: the impersonal tone and the image advertising of a large body.","cn":"组织机器：大型机构的非人格化腔调与形象广告。"},{"senses":"S04","en":"FINANCIAL ACTOR: an institution that invests on behalf of others.","cn":"金融行动者：代表他人投资的机构。"},{"senses":"S05 · S09","en":"EMBEDDED CARE AND STRUCTURE: care provided by a body, and advantages built into society.","cn":"嵌入的照护与结构：由机构提供的照护，以及嵌入社会的优势或劣势。"}]},"affixes":{"intro":{"en":"Institutional is institution plus the productive adjective suffix -al, from Latin -alis. The inner in- and statuere are fossilized inside the base.","cn":"institutional 是 institution 加能产的形容词后缀 -al（来自拉丁 -alis）。内部的 in- 与 statuere 已凝固在词基中。"},"latinIntro":{"en":"Latin stare 'to stand' and statuere 'set up' produced state, status, statue, statute, institute, institution, constitution, and constant. The reconstructed Indo-European root *sta- is a scholarly reconstruction, not an attested word.","cn":"拉丁 stare「站立」与 statuere「设立」产生了 state、status、statue、statute、institute、institution、constitution、constant。原始印欧语重构词根 *sta- 是学术重构，并非有记录的实际词。"},"items":[{"word":"institution","structure":"in- (into) + statuere + -tion","meaning":"an established organization or custom; -tion marks the result of setting up","meaningCN":"机构；制度（in-「进入」+ statuere + -tion，-tion 标记设立的结果）","example":"The university is an old institution.","exampleCN":"这所大学是一座古老的机构。"},{"word":"institutional","structure":"institution + -al (Latin -alis)","meaning":"of or belonging to an institution","meaningCN":"机构的；制度的（institution + -al 形容词后缀）","example":"Institutional rules govern the process.","exampleCN":"机构规章管理这一流程。"},{"word":"institute","structure":"in- + statuere","meaning":"to set up; as a noun, a learned society or research body","meaningCN":"设立；学会或研究机构（由动作名词转为特定团体）","example":"The institute funds basic research.","exampleCN":"该研究所资助基础研究。"},{"word":"institutionalize","structure":"institutional + -ize","meaning":"to make something into an institution, or to place someone in one","meaningCN":"使制度化；把某人送入机构（-ize 表示「使成为」）","example":"The practice was institutionalized in the 1950s.","exampleCN":"这种做法在 20 世纪 50 年代被制度化。"},{"word":"institutionalization","structure":"institutionalize + -ation","meaning":"the process of becoming institutional","meaningCN":"制度化；机构化（-ation 构成过程名词）","example":"Critics warned against the institutionalization of care.","exampleCN":"批评者警告照护过度机构化的风险。"},{"word":"constitution","structure":"con- (together) + statuere + -tion","meaning":"the founding law that sets up a state; con- means together, unlike the in- of institution","meaningCN":"宪法（con-「一起」+ statuere + -tion；con- 表示「一起」，不同于 institution 的 in-）","example":"The constitution sets out basic rights.","exampleCN":"宪法规定基本权利。"},{"word":"statute","structure":"statuere + -tum","meaning":"a law set in place by authority","meaningCN":"法规；成文法（被权威设立之物）","example":"The statute was passed last year.","exampleCN":"该法规去年获得通过。"},{"word":"statue","structure":"statuere + -a","meaning":"a figure set up in a place","meaningCN":"雕像（被设立在某处的人像）","example":"A statue stands in the square.","exampleCN":"广场上立着一座雕像。"},{"word":"instruction","structure":"in- + struere + -tion","meaning":"teaching or an order; root struere means build, not stand","meaningCN":"教导；指令（词根 struere 意为建造，而非站立）","example":"Follow the instructions carefully.","exampleCN":"请仔细遵照指示。"}],"latinEntries":[{"word":"stare","structure":"stare (to stand)","meaning":"to stand, be standing","meaningCN":"站立；处于站立状态"},{"word":"statuere","structure":"statuere (to set up)","meaning":"to set up, place, establish","meaningCN":"设立；放置；建立"},{"word":"instituere","structure":"in- (into) + statuere","meaning":"to set in place, establish, arrange","meaningCN":"安置；设立；安排"},{"word":"institutio","structure":"instituere + -tio","meaning":"an arrangement, establishment, instruction","meaningCN":"安排；设立；教导"}]}},{"word":"institution","ipa_uk":"/ˌɪnstɪˈtjuːʃn/","ipa_us":"/ˌɪnstɪˈtuːʃn/","definition_zh":"机构；制度；习俗；设立；公共机构；金融机构","definition_en":"an established organization or public body; a long-established custom or system; the act of setting something up; also a building or body devoted to a public purpose","core_image":"一枚反复使用的公章：同一块印章，既压出组织，也压出规矩","scene":"The university is an old institution with a chapel at its centre.","sceneCN":"这里 institution 是「机构」（第 1 个义项：已建立的组织）；句意：这所大学是一座古老的机构，中心有一座礼拜堂。图中可辨识物件：校园拱门、礼拜堂尖顶、石墙。","pos":[{"tag":"n.","zh":"机构；制度；习俗；设立"}],"collocations":[{"phrase":"financial institution","zh":"金融机构"},{"phrase":"academic institution","zh":"学术机构"},{"phrase":"institution of higher learning","zh":"高等教育机构"},{"phrase":"social institution","zh":"社会制度"},{"phrase":"mental institution","zh":"精神病院"},{"phrase":"establish an institution","zh":"设立机构"}],"forms":[{"label":"复数","form":"institutions"}],"derivatives":[{"word":"institutional","pos":"adj.","zh":"机构的；制度的"},{"word":"institutionalize","pos":"v.","zh":"使制度化；把某人送入机构"},{"word":"institutionalization","pos":"n.","zh":"制度化；机构化"},{"word":"institute","pos":"n./v.","zh":"学会；研究所；设立"},{"word":"institutionally","pos":"adv.","zh":"在制度上；以机构方式"}],"senses":[{"no":"01","title":"An established organization","titleCN":"机构；组织","definition":"a large organization founded for a public, educational, religious, or charitable purpose","definitionCN":"为公共、教育、宗教或慈善目的而建立的大型组织","example":"The bank has grown into a major financial institution.","exampleCN":"这家银行已发展成一家大型金融机构。","why":"Latin instituere means 'set in place'. An institution is something set up and left standing, with a life longer than the people inside it.","whyCN":"拉丁 instituere 意为「安置、设立」。institution 是被设立并持续站立的东西，其寿命长于身处其中的人。"},{"no":"02","title":"A long-established custom or system","titleCN":"制度；习俗","definition":"a custom, practice, or system that has become firmly established in a society","definitionCN":"在社会中已牢固确立的习俗、做法或制度","example":"The family remains a basic institution in almost every culture.","exampleCN":"家庭在几乎每种文化中仍是基本制度。","why":"The same noun names not only buildings but standing arrangements; what a society sets up and keeps is an institution.","whyCN":"同一个名词不仅指建筑，也指长期维持的安排；社会设立并保留的东西就是 institution。"},{"no":"03","title":"The act of founding or setting up","titleCN":"设立；建立","definition":"the formal act of establishing something, especially in law or religion","definitionCN":"正式建立某物的行为，尤指在法律或宗教中","example":"The institution of the new court took place in 1875.","exampleCN":"新法院的设立发生于 1875 年。","why":"This is the original verbal sense: the act of setting in place, before the result hardens into an organization.","whyCN":"这是最初的动词义：设立的动作，尚在结果固化为组织之前。"},{"no":"04","title":"A public or charitable body","titleCN":"公共机构；公益机构","definition":"a public body such as a hospital, school, prison, or charity","definitionCN":"医院、学校、监狱或慈善组织等公共机构","example":"The old almshouse is now a charitable institution.","exampleCN":"这座旧济贫院现在是一所慈善机构。","why":"A body founded for a public purpose is an institution by definition: it was set up to serve people beyond its own members.","whyCN":"为公共目的建立的团体按定义就是 institution：它被设立是为了服务成员之外的人。"},{"no":"05","title":"A bank or financial body","titleCN":"金融机构","definition":"a financial organization such as a bank, insurer, or investment fund","definitionCN":"银行、保险公司或投资基金等金融组织","example":"Regulators examined the solvency of each institution.","exampleCN":"监管机构检查了每家机构的偿付能力。","why":"Finance uses the general word for an organization and narrows it to bodies that handle money.","whyCN":"金融领域使用这个表示组织的通用词，并把它窄化为处理资金的机构。"},{"no":"06","title":"A mental hospital","titleCN":"精神病院（旧称）","definition":"a hospital for people with mental illness, now often avoided as a term","definitionCN":"收治精神疾病患者的医院，如今该说法常被回避","example":"The Victorian institution was closed in the 1980s.","exampleCN":"那所维多利亚时代的精神病院在 20 世纪 80 年代关闭。","why":"The word names the place by its legal status as an established public body; that respectable cover made it the standard term for asylums.","whyCN":"该词以「已设立的公共机构」这一法律身份来命名场所；这层体面的外衣使它成为精神病院的标准说法。"},{"no":"07","title":"A well-known person or place","titleCN":"（口语）标志性人物；老字号","definition":"a familiar person or place that has become part of the life of a community","definitionCN":"已成为社区生活一部分的熟悉人物或场所","example":"The corner bookshop is a local institution.","exampleCN":"街角书店是当地的老字号。","why":"If something is so long established that the community cannot imagine life without it, it is called an institution.","whyCN":"如果某物确立得如此之久，以至于社区无法想象没有它的生活，它就被称为 institution。"},{"no":"08","title":"An institution's building","titleCN":"机构建筑；院所","definition":"the building or set of buildings used by an established organization","definitionCN":"已建立组织所使用的建筑或建筑群","example":"The institution was rebuilt after the fire.","exampleCN":"该机构建筑在火灾后重建。","why":"Metonymy: the name of the organization transfers to the place it occupies.","whyCN":"这是转喻：组织的名称转移到它所占据的场所。"},{"no":"09","title":"A formally established rule in law","titleCN":"（法律上的）制度；设立","definition":"a legally established arrangement, right, or procedure","definitionCN":"依法确立的安排、权利或程序","example":"The institution of habeas corpus protects against unlawful detention.","exampleCN":"人身保护令制度防止非法拘禁。","why":"Law speaks of the institution of a right when it sets the right in place as a standing rule.","whyCN":"法律谈到某项权利的 institution，就是把它作为长期规则设立到位。"}],"etymology":{"intro":{"en":"Institution comes from Latin institutio, from instituere 'to set in place'. The root chain begins with a reconstructed Indo-European form for 'stand' and passes through stare and statuere.","cn":"institution 来自拉丁 institutio，源自动词 instituere「安置、设立」。词根链条始于表示「站立」的原始印欧语重构形式，经 stare 与 statuere 而来。"},"items":[{"era":"PROTO-INDO-EUROPEAN *sta-","en":"The reconstructed root *sta- 'to stand' is generally thought to lie behind Latin stare. It is a reconstruction, not an attested word.","cn":"原始印欧语重构形式 *sta- 意为「站立」，一般认为它是拉丁 stare 的来源。它是重构形式，并非有记录的实际词。"},{"era":"LATIN stare","en":"stare 'to stand' is the simple verb of standing; statue, status, and station all descend from it.","cn":"stare「站立」是最简单的站立动词；statue、status、station 都由它而来。"},{"era":"LATIN statuere","en":"statuere 'to cause to stand, set up' adds a causative force: someone makes something stand.","cn":"statuere「使站立、设立」增加使动意义：某人使某物站立起来。"},{"era":"LATIN instituere","en":"in- 'into, upon' + statuere gives 'to set in place, establish'. The in- is locative, not negative.","cn":"in-「进入、在上」+ statuere 构成「安置、设立」。这里的 in- 表位置，不是否定。"},{"era":"LATIN institutio","en":"institutio named the act of establishing and the arrangement established; -tio forms an action or result noun.","cn":"institutio 既指设立动作，也指被设立的制度；-tio 构成动作或结果名词。"},{"era":"FRENCH AND ENGLISH institution","en":"Old French institution reached English in the 14th century, first as 'establishment' and then as the body or custom established.","cn":"古法语 institution 于 14 世纪进入英语，先表示「设立」，后表示被设立的组织或习俗。"}]},"similar":{"note":{"en":"The first group contains forms easily confused with institution; the second contains words close in meaning.","cn":"第一组是容易与 institution 混淆的形式；第二组是意义相近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"institutional","ipa":"/ˌɪnstɪˈtjuːʃənl/","tag":"adjective of the same base","definition":"relating to an institution; the -al suffix makes it an adjective, so it cannot replace the noun","definitionCN":"与机构相关的；-al 后缀使其成为形容词，不能替代名词"},{"word":"institute","ipa":"/ˈɪnstɪtjuːt/","tag":"same verb, narrower noun","definition":"a learned society or research body; the same Latin verb, but the noun names a specific body rather than a custom or system","definitionCN":"学会或研究机构；同一拉丁动词，但名词指特定团体，而非习俗或制度"},{"word":"constitution","ipa":"/ˌkɒnstɪˈtjuːʃn/","tag":"same root, con- prefix","definition":"the founding law of a state; from con- 'together' + statuere, not in- 'into', and it is a document, not an organization","definitionCN":"国家立国之法；来自 con-「一起」+ statuere，而非 in-「进入」，且是文件而非组织"},{"word":"instruction","ipa":"/ɪnˈstrʌkʃn/","tag":"looks parallel, different root","definition":"teaching or an order; from struere 'build', not stare 'stand', so the similar shape is accidental","definitionCN":"教导或指令；来自 struere「建造」，而非 stare「站立」，外形相似只是巧合"}]},{"heading":"NEAR MEANING","entries":[{"word":"organization","ipa":"/ˌɔːɡənaɪˈzeɪʃn/","tag":"structured body","definition":"a body with members and a structure; narrower than institution, which also covers customs","definitionCN":"有成员和结构的团体；比 institution 窄，后者还涵盖习俗"},{"word":"establishment","ipa":"/ɪˈstæblɪʃmənt/","tag":"founding or founded body","definition":"the act of founding or the body founded; close to senses 01 and 03","definitionCN":"创立行为或被创立的机构；接近第 1 与第 3 个义项"},{"word":"custom","ipa":"/ˈkʌstəm/","tag":"usual practice","definition":"a usual practice; close to sense 02 but without the sense of formal setup","definitionCN":"惯常做法；接近第 2 个义项，但缺少正式设立的含义"},{"word":"foundation","ipa":"/ˌfaʊnˈdeɪʃn/","tag":"endowed body","definition":"an endowed charitable body; close to sense 04 but specifically funded by an endowment","definitionCN":"有捐赠基金的慈善机构；接近第 4 个义项，但特指有基金资助者"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'into' + statuere 'set, stand': an institution is a thing set into place and kept standing. The in- is not 'not'.","cn":"in-「进入」+ statuere「设立、站立」：institution 是被设立到位并保持站立的东西。这里的 in- 不是「不」。"},{"en":"institute is a learned body; institution is the broader standing arrangement, whether an organization or a custom.","cn":"institute 是学会；institution 是更广的长期安排，可以是组织也可以是习俗。"},{"en":"institutional is the adjective; institution is the noun; adding -al does not change the base meaning.","cn":"institutional 是形容词，institution 是名词；加 -al 不改变词基意义。"},{"en":"institutionalize turns the noun into a verb meaning 'make into an institution'.","cn":"institutionalize 把名词变成动词，意为「使成为制度」。"},{"en":"A mental institution is still an institution in the legal sense: a public body set up for care.","cn":"精神病院在法律意义上仍是 institution：为照护而设立的公共机构。"}],"abstract":[{"en":"Think of a stamp used again and again: the same mark creates both the organization and the rules it lives by.","cn":"把 institution 想象成一枚反复使用的印章：同一个印记既造出组织，也造出组织赖以生存的规矩。"},{"en":"Think of a river whose old channel still directs new water: the custom is the channel, the institution is the channel itself.","cn":"把制度想象成一条老河道仍在引导新水：习俗是水流，institution 是河道本身。"},{"en":"Think of a chair everyone sits in without asking: long use turns an object into an institution.","cn":"把 institution 想象成一把谁都不问就坐下的椅子：长久使用把物件变成了制度。"}]},"examples":[{"en":"The university is one of the oldest institutions in the country.","cn":"这所大学是该国最古老的机构之一。"},{"en":"Marriage is a social institution that varies across cultures.","cn":"婚姻是一种因文化而异的社会制度。"},{"en":"The charity has become a national institution for disaster relief.","cn":"该慈善机构已成为全国性的救灾机构。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（向内）+ stituere（设立）+ -tion（结果）：被设立在内部并长期站立的东西 → institution 机构、制度","word":"institution"},"root":"拉丁 instituere「安置、设立」（in-「进入、在上」+ statuere「使站立」，statuere 出自 stare「站立」）；institutio 为动作或结果名词；与 constitution、statute、statue 同出原始印欧语重构词根 *sta-，此处 in- 非否定前缀。","sensesIntro":{"en":"Nine senses all name something set up and kept standing: an organization, a custom, a legal rule, a building, or even a beloved local shop.","cn":"九个义项都指被设立并长期维持的东西：组织、习俗、法律规则、建筑，甚至一家受人喜爱的本地店铺。"},"semanticMap":{"core":{"en":"CORE IMAGE: a stamp pressed again and again, making both bodies and rules stand.","cn":"核心意象：一枚反复压下的印章，既造出团体，也造出规矩。"},"chain":["SET IN PLACE","THE ACT OF FOUNDING","THE BODY FOUNDED","THE CUSTOM ESTABLISHED","THE PLACE IT OCCUPIES","THE MARK IT LEAVES"],"branches":[{"senses":"S01 · S04","en":"BODY: an organization or public body founded for a purpose.","cn":"团体：为某目的建立的机构或公共机构。"},{"senses":"S02","en":"CUSTOM: a practice or system that society keeps standing.","cn":"习俗：社会长期维持的做法或制度。"},{"senses":"S03 · S09","en":"FOUNDING: the formal act of setting up a body or a legal rule.","cn":"设立：建立机构或法律规则的正式行为。"},{"senses":"S05 · S06","en":"SPECIAL BODIES: financial institutions and the old mental hospital.","cn":"专门机构：金融机构与旧称的精神病院。"},{"senses":"S07 · S08","en":"FAMILIAR PRESENCE: a local landmark or the building of an organization.","cn":"熟悉的存在：地方标志物或机构的建筑。"}]},"affixes":{"intro":{"en":"Institution is the noun from Latin instituere, with the action-result suffix -tion. The prefix in- and the root statuere are fossilized inside the word.","cn":"institution 是来自拉丁 instituere 的名词，带动作—结果后缀 -tion。前缀 in- 与词根 statuere 已凝固在词内。"},"latinIntro":{"en":"Latin stare and statuere also give state, status, statue, statute, institute, constitution, and constant. The reconstructed *sta- is a scholarly form, not a recorded word.","cn":"拉丁 stare 与 statuere 还产生 state、status、statue、statute、institute、constitution、constant。重构形式 *sta- 是学术构拟，并非有记录的实际词。"},"items":[{"word":"institution","structure":"in- (into) + statuere + -tion (Latin -tio)","meaning":"an established organization or custom; -tion marks the result","meaningCN":"机构；制度（-tion 标记结果）","example":"The institution dates back to the twelfth century.","exampleCN":"该机构可追溯到 12 世纪。"},{"word":"institutional","structure":"institution + -al (Latin -alis)","meaning":"of or belonging to an institution","meaningCN":"机构的；制度的（-al 形容词后缀）","example":"Institutional change is slow.","exampleCN":"制度变革缓慢。"},{"word":"institute","structure":"in- + statuere","meaning":"to set up; a learned society or research body","meaningCN":"设立；学会或研究机构（动作转指特定团体）","example":"She joined a research institute.","exampleCN":"她加入了一家研究所。"},{"word":"institutionalize","structure":"institutional + -ize","meaning":"to make into an institution or place someone in one","meaningCN":"使制度化；把某人送入机构（-ize 使动后缀）","example":"The government institutionalized the review.","exampleCN":"政府把审查制度化。"},{"word":"institutionalization","structure":"institutionalize + -ation","meaning":"the process or result of becoming institutional","meaningCN":"制度化；机构化（-ation 过程名词后缀）","example":"Long stays led to institutionalization.","exampleCN":"长期住院导致机构化。"},{"word":"constitution","structure":"con- (together) + statuere + -tion","meaning":"the founding law of a state; con- means together, not the in- of institution","meaningCN":"宪法（con-「一起」+ statuere + -tion；不同于 institution 的 in-）","example":"The constitution protects free speech.","exampleCN":"宪法保护言论自由。"},{"word":"statute","structure":"statuere + -tum","meaning":"a law set in place","meaningCN":"法规；成文法（被设立之物）","example":"The statute bans the practice.","exampleCN":"该法规禁止这种做法。"},{"word":"statue","structure":"statuere + -a","meaning":"a figure set up in a place","meaningCN":"雕像（被设立的人像）","example":"The statue honors the founder.","exampleCN":"这座雕像纪念创始人。"},{"word":"instruction","structure":"in- + struere + -tion","meaning":"teaching or an order; root struere means build","meaningCN":"教导；指令（词根 struere 意为建造）","example":"The instructions are on the box.","exampleCN":"说明在盒子上。"}],"latinEntries":[{"word":"stare","structure":"stare (to stand)","meaning":"to stand","meaningCN":"站立"},{"word":"statuere","structure":"statuere (to set up)","meaning":"to set up, establish","meaningCN":"设立；建立"},{"word":"instituere","structure":"in- (into) + statuere","meaning":"to set in place, establish","meaningCN":"安置；设立"},{"word":"institutio","structure":"instituere + -tio","meaning":"an establishment, arrangement","meaningCN":"设立；安排；制度"}]}},{"word":"instructional","ipa_uk":"/ɪnˈstrʌkʃənl/","ipa_us":"/ɪnˈstrʌkʃənl/","definition_zh":"教学的；指导的；教学用的；培训的","definition_en":"relating to teaching or instruction; designed to teach a skill or subject; giving directions on how to do something","core_image":"一张施工图：把知识一块一块垒进学习者的头脑","scene":"The teacher redesigned the course around clear instructional goals.","sceneCN":"这里 instructional 是「教学的」（第 1 个义项：与教学相关的）；句意：老师围绕清晰的教学目标重设了课程。图中可辨识物件：教案、黑板、课程大纲。","pos":[{"tag":"adj.","zh":"教学的；指导的；教学用的"}],"collocations":[{"phrase":"instructional materials","zh":"教学材料"},{"phrase":"instructional design","zh":"教学设计"},{"phrase":"instructional strategy","zh":"教学策略"},{"phrase":"instructional video","zh":"教学视频"},{"phrase":"instructional staff","zh":"教学人员"},{"phrase":"instructional coaching","zh":"教学辅导"}],"forms":[{"label":"比较级","form":"more instructional"},{"label":"最高级","form":"most instructional"},{"label":"副词","form":"instructionally"}],"derivatives":[{"word":"instruct","pos":"v.","zh":"教导；指示"},{"word":"instruction","pos":"n.","zh":"教学；指令；说明"},{"word":"instructor","pos":"n.","zh":"教师；教练"},{"word":"instructive","pos":"adj.","zh":"有教益的；启发性的"},{"word":"instructionally","pos":"adv.","zh":"在教学上"}],"senses":[{"no":"01","title":"Relating to teaching","titleCN":"教学的；讲授的","definition":"connected with teaching or the act of instructing","definitionCN":"与教学或讲授行为相关的","example":"The department reviews its instructional methods every year.","exampleCN":"该系每年审查其教学方法。","why":"Latin instruere means 'to build into'. With -tion and -al, instructional describes what belongs to the work of building knowledge into a learner.","whyCN":"拉丁 instruere 意为「建造进去」。加上 -tion 与 -al 后，instructional 描述属于「把知识建入学习者」这项工作的事物。"},{"no":"02","title":"Used for teaching","titleCN":"教学用的","definition":"designed or produced to be used in teaching","definitionCN":"为用于教学而设计或制作的","example":"The library keeps a collection of instructional materials.","exampleCN":"图书馆收藏了一批教学材料。","why":"The suffix -al marks belonging or purpose: materials that belong to instruction are instructional materials.","whyCN":"后缀 -al 标记归属或用途：属于教学的材料就是教学材料。"},{"no":"03","title":"Giving directions or explanation","titleCN":"指导性的；说明性的","definition":"serving to explain how something is done or how to use it","definitionCN":"用于说明某事如何做或如何使用某物","example":"The instructional leaflet explains how to reset the device.","exampleCN":"这份说明性折页解释了如何重置设备。","why":"instruere also meant 'equip': instructions equip you with the steps. Instructional describes that equipping.","whyCN":"instruere 也有「装备」义：说明为你装备步骤。instructional 描述这种装备作用。"},{"no":"04","title":"Relating to instructional design","titleCN":"教学设计的","definition":"connected with the systematic planning of teaching and learning experiences","definitionCN":"与教学和学习体验的系统规划相关的","example":"She works as an instructional designer for an online programme.","exampleCN":"她为一个在线项目担任教学设计者。","why":"Design is the modern extension: the builder metaphor turns into planning how knowledge will be built.","whyCN":"设计是现代延伸：建造者的隐喻转为规划知识将如何被建造。"},{"no":"05","title":"Relating to training","titleCN":"培训的；技能训练的","definition":"connected with organized training in a practical skill","definitionCN":"与有组织的实用技能训练相关的","example":"New staff complete an instructional programme before they handle clients.","exampleCN":"新员工在接触客户前完成一项培训项目。","why":"Training is instruction aimed at a skill; the same adjective covers the programme that equips workers.","whyCN":"培训是以技能为目标的教导；同一个形容词覆盖为员工装备技能的项目。"},{"no":"06","title":"Relating to coaching","titleCN":"辅导的；教练式指导的","definition":"connected with individual guidance that helps someone improve performance","definitionCN":"与帮助某人提升表现的个别指导相关的","example":"The school introduced instructional coaching for new teachers.","exampleCN":"学校为新教师引入了教学辅导。","why":"Instruction need not be a lecture: a coach also builds ability step by step, so the adjective extends to coaching.","whyCN":"教导不必是讲课：教练同样一步步建起能力，因此该形容词扩展到辅导。"},{"no":"07","title":"Relating to a manual or set of rules","titleCN":"操作规程的；说明书的","definition":"belonging to a manual, set of rules, or operating procedure","definitionCN":"属于手册、规则或操作程序的","example":"The instructional section runs to forty pages.","exampleCN":"说明部分长达四十页。","why":"From 'teaching' to 'written directions': a manual instructs the reader in how to operate something.","whyCN":"从「教导」到「书面指示」：手册教读者如何操作某物。"},{"no":"08","title":"Relating to teaching methods","titleCN":"教学法的","definition":"connected with the methods and theory of teaching","definitionCN":"与教学方法和教学理论相关的","example":"The study compares instructional approaches in large classes.","exampleCN":"该研究比较大班中的教学法。","why":"-al turns instruction into 'of instruction'; method is how the building work is done.","whyCN":"-al 把 instruction 变成「属于教学的」；方法就是建造工作如何进行。"},{"no":"09","title":"Relating to teaching staff","titleCN":"教学人员的","definition":"connected with the teaching staff of a school or college","definitionCN":"与学校或学院教学人员相关的","example":"Instructional staff were consulted before the timetable changed.","exampleCN":"在课表变更前咨询了教学人员。","why":"Staff are named by their function: they belong to instruction, hence instructional staff.","whyCN":"人员按职能命名：他们属于教学，故称教学人员。"}],"etymology":{"intro":{"en":"Instructional is instruction plus -al. Instruction comes from Latin instructio, from instruere 'to build into, equip, teach', built on struere 'to heap up, build'.","cn":"instructional 是 instruction 加 -al。instruction 来自拉丁 instructio，源自 instruere「建入、装备、教导」，其词根为 struere「堆积、建造」。"},"items":[{"era":"LATIN struere","en":"struere meant 'to heap up, pile, build'. It is the same root behind construction, structure, and instrument, where the idea is arranging materials into a form.","cn":"struere 意为「堆积、堆起、建造」。它与 construction、structure、instrument 同根，核心观念是把材料安排成一个形态。"},{"era":"LATIN instruere","en":"in- 'into' + struere gives instruere 'to build into, equip, teach'. Knowledge is pictured as material built into the learner's mind.","cn":"in-「进入」+ struere 构成 instruere「建入、装备、教导」。知识被想象成建入学习者头脑的材料。"},{"era":"PAST PARTICIPLE instructus","en":"instructus 'equipped, taught' supplied the stem instruct-, which English uses in instruct, instructor, and instructive.","cn":"instructus「被装备的、被教导的」提供词干 instruct-，英语用于 instruct、instructor、instructive。"},{"era":"LATIN instructio","en":"instructio meant 'a building, arrangement, teaching'. The -tio suffix turns the act into a noun.","cn":"instructio 意为「建造、安排、教导」。-tio 后缀把动作变成名词。"},{"era":"FRENCH AND ENGLISH instruction","en":"English borrowed instruction in the 14th century for teaching, and later for a written order; the 'command' sense grows out of 'something laid down for you'.","cn":"英语在 14 世纪借入 instruction，表示教学，后来也表示书面命令；「指令」义由「为你规定下来的东西」发展而来。"},{"era":"ENGLISH -al","en":"Adding -al in the 19th century produced instructional, meaning 'of or for instruction'. The suffix adds belonging, not a new root meaning.","cn":"19 世纪加上 -al 构成 instructional，意为「属于教学或用于教学的」。该后缀只加归属义，不改变词根意义。"}]},"similar":{"note":{"en":"The first group shares the shape or the root struere but differs in meaning; the second contains words close in teaching meaning.","cn":"第一组共享外形或词根 struere，但意义不同；第二组是教学意义相近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"instruction","ipa":"/ɪnˈstrʌkʃn/","tag":"base noun","definition":"the act of teaching; also an order or written direction. The noun covers both, while instructional usually describes teaching","definitionCN":"教学行为；也指命令或书面指示。名词兼含两义，instructional 通常描述教学"},{"word":"instructive","ipa":"/ɪnˈstrʌktɪv/","tag":"same root, -ive suffix","definition":"giving useful information or teaching a lesson; -ive describes a quality, -al describes belonging or purpose","definitionCN":"提供有用信息或给人教益的；-ive 描述性质，-al 描述归属或用途"},{"word":"construction","ipa":"/kənˈstrʌkʃn/","tag":"same struere root, con- prefix","definition":"the act or result of building; con- 'together' + struere, so it is about piling materials, not teaching","definitionCN":"建造行为或结果；con-「一起」+ struere，讲堆材料，而非教学"},{"word":"instrument","ipa":"/ɪnˈstrʌmənt/","tag":"same instru- shape, different suffix","definition":"a tool or device; in- + struere + -ment, 'something built or equipped', not a mode of teaching","definitionCN":"工具或器械；in- + struere + -ment，指被建造或装备之物，不是教学方式"}]},{"heading":"NEAR MEANING","entries":[{"word":"educational","ipa":"/ˌedjʊˈkeɪʃənl/","tag":"broadly teaching-related","definition":"relating to education in general; broader than instructional, which focuses on instruction and its methods","definitionCN":"与一般教育相关的；比 instructional 更广，后者聚焦教学及其方法"},{"word":"pedagogic","ipa":"/ˌpedəˈɡɒdʒɪk/","tag":"theory of teaching","definition":"relating to the theory and practice of teaching; more academic than instructional","definitionCN":"与教学理论和实践相关的；比 instructional 更学术"},{"word":"didactic","ipa":"/daɪˈdæktɪk/","tag":"intended to teach, often moralizing","definition":"intended to teach, often with a moralizing tone; instructional is neutral about tone","definitionCN":"意在教导，常带说教语气；instructional 对语气保持中性"},{"word":"training","ipa":"/ˈtreɪnɪŋ/","tag":"skill practice","definition":"relating to practical skill training; narrower than instructional, which also covers school subjects","definitionCN":"与实践技能培训相关的；比 instructional 窄，后者也涵盖学校科目"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'into' + struere 'build' + -tion + -al: instructional is about building knowledge into someone.","cn":"in-「进入」+ struere「建造」+ -tion + -al：instructional 就是把知识建入某人之中的。"},{"en":"instruction is the noun; instructional is the adjective; instructionally is the adverb.","cn":"instruction 是名词，instructional 是形容词，instructionally 是副词。"},{"en":"instructive (-ive) describes a quality, instructional (-al) describes belonging or purpose.","cn":"instructive（-ive）描述性质，instructional（-al）描述归属或用途。"},{"en":"instrument shares the same build root: a tool is something equipped; instruction equips the mind.","cn":"instrument 共享同一建造词根：工具是被装备之物；instruction 装备头脑。"},{"en":"instruction can also mean an order, because what is taught can be laid down as a rule.","cn":"instruction 也可指命令，因为所教的内容可以被规定为规则。"}],"abstract":[{"en":"Think of a lesson as a wall: each step is a brick, and instructional design is the blueprint for laying it.","cn":"把一堂课想象成一堵墙：每一步是一块砖，教学设计就是砌砖的图纸。"},{"en":"Think of a manual as a teacher made of paper: it instructs without a voice.","cn":"把手册想象成纸做的老师：它没有声音却在教导。"},{"en":"Think of a coach beside a learner: the coach builds ability one rep at a time, which is instruction in motion.","cn":"把教练想象在学习者身旁：教练一次次重复建起能力，这就是行动中的 instruction。"}]},"examples":[{"en":"The school invests in instructional materials for every grade.","cn":"学校为每个年级购置教学材料。"},{"en":"Good instructional design makes complex ideas easier to follow.","cn":"良好的教学设计让复杂概念更易理解。"},{"en":"The instructional video walks viewers through the first experiment.","cn":"这段教学视频带观看者完成第一个实验。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（进入）+ struct（建造）+ -ion + -al：把知识建进头脑的 → instructional 教学的、指导的","word":"instructional"},"root":"拉丁 instruere「建入、装备、教导」（in-「进入」+ struere「建造、堆积」）；instruct- 词干 + -ion（拉丁 -tio）+ -al；与 construction、instrument 同出 struere 词根。","sensesIntro":{"en":"Nine senses share one idea: building something into a learner. A method, a video, a manual, a coach, and a whole school can all be instructional.","cn":"九个义项共享一个观念：把某物建入学习者。方法、视频、手册、教练乃至整所学校，都可以是 instructional 的。"},"semanticMap":{"core":{"en":"CORE IMAGE: a blueprint for laying knowledge brick by brick into a mind.","cn":"核心意象：把知识一砖一砖砌进头脑的施工图。"},"chain":["BUILD INTO","TEACHING","TEACHING MATERIALS","WRITTEN DIRECTIONS","PLANNED DESIGN","TRAINING AND COACHING"],"branches":[{"senses":"S01 · S02","en":"TEACHING AND ITS TOOLS: the act of teaching and the materials made for it.","cn":"教学及其工具：教学行为与为其制作的材料。"},{"senses":"S03 · S07","en":"DIRECTIONS: spoken explanation and written operating instructions.","cn":"指示：口头说明与书面操作规程。"},{"senses":"S04 · S08","en":"METHOD: systematic design and the theory of teaching approaches.","cn":"方法：系统设计与教学方法理论。"},{"senses":"S05 · S09","en":"INSTITUTIONAL TEACHING: training programmes and teaching staff.","cn":"机构教学：培训项目与教学人员。"},{"senses":"S06","en":"COACHING: individual guidance that builds performance step by step.","cn":"辅导：一步步建起表现的个别指导。"}]},"affixes":{"intro":{"en":"Instructional is instruction plus -al. The productive part is -al; the base instruction is itself a Latin-derived noun with -tion, and struere is fossilized inside it.","cn":"instructional 是 instruction 加 -al。能产部分是 -al；词基 instruction 本身是带 -tion 的拉丁来源名词，struere 凝固其中。"},"latinIntro":{"en":"Latin struere 'to build' produced structure, construct, destruction, instruct, obstruct, and instrument. The root appears as stru-, struct-, or stroy-.","cn":"拉丁 struere「建造」产生了 structure、construct、destruction、instruct、obstruct、instrument。词根以 stru-、struct- 或 stroy- 形式出现。"},"items":[{"word":"instruct","structure":"in- + struere","meaning":"to teach or give an order","meaningCN":"教导；指示（in-「进入」+ struere「建造」）","example":"The coach will instruct the group.","exampleCN":"教练将指导这组人。"},{"word":"instruction","structure":"instruct- + -tion","meaning":"teaching; a direction or order","meaningCN":"教学；指令（-tion 动作或结果名词）","example":"The instructions were clear.","exampleCN":"指示很清楚。"},{"word":"instructor","structure":"instruct- + -or","meaning":"a person who teaches","meaningCN":"教师；教练（-or 表示施动者）","example":"The instructor corrected her posture.","exampleCN":"教练纠正了她的姿势。"},{"word":"instructive","structure":"instruct- + -ive","meaning":"giving useful information or a lesson","meaningCN":"有教益的；启发性的（-ive 性质形容词）","example":"The failure was instructive.","exampleCN":"这次失败很有教益。"},{"word":"instructional","structure":"instruction + -al (Latin -alis)","meaning":"of or for teaching","meaningCN":"教学的；教学用的（-al 归属或用途形容词）","example":"The instructional plan is detailed.","exampleCN":"教学计划很详细。"},{"word":"construct","structure":"con- + struere","meaning":"to build or put together","meaningCN":"建造；组合（con-「一起」+ struere）","example":"They construct a model.","exampleCN":"他们建造一个模型。"},{"word":"construction","structure":"construct- + -ion","meaning":"the act or result of building","meaningCN":"建造；结构（-ion 动作或结果名词）","example":"The construction took a year.","exampleCN":"建造花了一年。"},{"word":"instrument","structure":"in- + struere + -ment","meaning":"a tool or device","meaningCN":"工具；器械（-ment 表示物）","example":"The kit contains several instruments.","exampleCN":"工具包里有几件器械。"},{"word":"obstruct","structure":"ob- + struere","meaning":"to block or stand in the way","meaningCN":"阻碍（ob-「对着」+ struere，原义为在前面堆起来挡住）","example":"Fallen trees obstructed the road.","exampleCN":"倒下的树挡住了路。"}],"latinEntries":[{"word":"struere","structure":"struere (to build)","meaning":"to heap up, arrange, build","meaningCN":"堆积；安排；建造"},{"word":"instruere","structure":"in- (into) + struere","meaning":"to build into, equip, teach","meaningCN":"建入；装备；教导"},{"word":"instructio","structure":"instruere + -tio","meaning":"a building, arrangement, teaching","meaningCN":"建造；安排；教导"},{"word":"instrumentum","structure":"instruere + -mentum","meaning":"equipment, tool","meaningCN":"装备；工具"}]}},{"word":"integration","ipa_uk":"/ˌɪntɪˈɡreɪʃn/","ipa_us":"/ˌɪntɪˈɡreɪʃn/","definition_zh":"整合；一体化；融入；积分；系统集成","definition_en":"the process of combining parts into a whole; the joining of groups into a society; the mathematical operation of finding an integral; the linking of systems or data","core_image":"散落的零件被装回同一台机器，接缝处不再漏光","scene":"In calculus, integration adds infinitely many thin slices into one area.","sceneCN":"这里 integration 是「积分」（第 5 个义项：求曲线下总面积或原函数的数学运算）；句意：在微积分中，积分把无穷多个薄片相加成一个面积。图中可辨识物件：曲线、切片、坐标轴。","pos":[{"tag":"n.","zh":"整合；一体化；融入；积分"}],"collocations":[{"phrase":"economic integration","zh":"经济一体化"},{"phrase":"social integration","zh":"社会融合"},{"phrase":"system integration","zh":"系统集成"},{"phrase":"data integration","zh":"数据整合"},{"phrase":"cultural integration","zh":"文化融合"},{"phrase":"integration process","zh":"整合过程"}],"forms":[{"label":"复数","form":"integrations"}],"derivatives":[{"word":"integrate","pos":"v.","zh":"整合；融入；求积分"},{"word":"integrated","pos":"adj.","zh":"综合的；融合的"},{"word":"integral","pos":"adj./n.","zh":"不可或缺的；积分"},{"word":"integrationist","pos":"n./adj.","zh":"主张融合者；融合主义的"},{"word":"reintegration","pos":"n.","zh":"重新融入；重新整合"}],"senses":[{"no":"01","title":"Combining parts into a whole","titleCN":"整合；结合成整体","definition":"the act or process of bringing separate parts together into a single whole","definitionCN":"把分开的部分合为一个整体的行为或过程","example":"The integration of the two departments took a year.","exampleCN":"两个部门的整合花了一年。","why":"Latin integrare means 'to make whole', from integer 'untouched, complete'. Integration is the work of restoring wholeness to parts.","whyCN":"拉丁 integrare 意为「使完整」，来自 integer「未被触碰的、完整的」。integration 是让部分恢复整全的工作。"},{"no":"02","title":"Becoming part of a society","titleCN":"融入；社会融合","definition":"the process by which newcomers become accepted members of a society","definitionCN":"新来者被社会接纳为成员的过程","example":"Language classes speed up the integration of new arrivals.","exampleCN":"语言课程加快新来者的融入。","why":"Society is imagined as a whole; the newcomer is a part being joined to it, so the word means social joining.","whyCN":"社会被想象成一个整体；新来者是正被接上去的一个部分，因此该词表示社会性的接合。"},{"no":"03","title":"Ending racial segregation","titleCN":"（种族）融合；取消隔离","definition":"the process of opening schools, housing, or institutions to all races on equal terms","definitionCN":"以平等条件向所有种族开放学校、住房或机构的过程","example":"The court ordered the integration of the city's schools.","exampleCN":"法院下令该市学校实行种族融合。","why":"Here the parts kept apart by segregation are brought into one body; the metaphor remains 'making whole'.","whyCN":"此处被隔离分开的部分被带入同一个整体；隐喻仍是「使完整」。"},{"no":"04","title":"Economic integration","titleCN":"经济一体化","definition":"the removal of barriers so that separate economies combine into a larger market","definitionCN":"消除壁垒，使分开的经济体合并为更大市场","example":"Trade rules deepened regional economic integration.","exampleCN":"贸易规则加深了区域经济一体化。","why":"Separate markets are treated as parts; lowering barriers joins them into one economic space.","whyCN":"分开的市场被当作部分；降低壁垒把它们接成一个经济空间。"},{"no":"05","title":"Integration in calculus","titleCN":"积分","definition":"the mathematical operation of finding a function whose derivative is given, or the total area under a curve","definitionCN":"求已知导数的原函数，或求曲线下总面积的数学运算","example":"Integration gives the total area under the curve.","exampleCN":"积分给出曲线下的总面积。","why":"The Latin word for making whole fits the mathematics: infinitely many small slices are summed into one total.","whyCN":"拉丁语「使完整」正好契合这一数学：无穷多个小片被相加成一个总量。"},{"no":"06","title":"Linking computer systems","titleCN":"系统集成","definition":"the process of making different systems, applications, or networks work together","definitionCN":"使不同系统、应用或网络协同工作的过程","example":"System integration let the old database talk to the new platform.","exampleCN":"系统集成让旧数据库与新平台通信。","why":"Technical parts are made to function as one system; the word keeps its engineering sense of assembling.","whyCN":"技术部件被组合成一个系统运作；该词保留了组装的工程义。"},{"no":"07","title":"Bringing together the parts of a personality","titleCN":"人格整合","definition":"in psychology, the process by which different aspects of the self become a coherent whole","definitionCN":"心理学中，自我的不同方面成为连贯整体的过程","example":"Therapy aims at the integration of split-off memories.","exampleCN":"治疗旨在整合被割裂的记忆。","why":"The mind is pictured as parts that can be scattered; integration is the healing work of making them one.","whyCN":"心灵被想象成可能散落的部分；integration 是把它们合而为一的疗愈工作。"},{"no":"08","title":"Combining data from different sources","titleCN":"数据整合","definition":"the process of merging data from separate sources into a consistent set","definitionCN":"把不同来源的数据合并为一致数据集的过程","example":"Data integration removed duplicate records across the agencies.","exampleCN":"数据整合清除了各机构之间的重复记录。","why":"Records are fragments; integration assembles them into one reliable whole.","whyCN":"记录是碎片；integration 把它们组装成一个可靠的整体。"},{"no":"09","title":"The state of being united","titleCN":"统一；整体状态","definition":"the condition of being combined or unified rather than separate","definitionCN":"处于合并或统一而非分离的状态","example":"The report stresses integration rather than mere coordination.","exampleCN":"报告强调统一整合，而非仅仅协调。","why":"The noun can name the result as well as the process: once the parts are joined, the whole is in a state of integration.","whyCN":"这个名词既可指过程，也可指结果：部分一旦接合，整体就处于整合状态。"}],"etymology":{"intro":{"en":"Integration comes from Latin integratio, from integrare 'to make whole', from integer 'untouched, complete'. The chain runs from the root tag- 'touch' through tangere and integer to English -ation.","cn":"integration 来自拉丁 integratio，源自 integrare「使完整」，再来自 integer「未被触碰的、完整的」。链条从词根 tag-「接触」经 tangere 与 integer，直到英语 -ation。"},"items":[{"era":"PROTO-INDO-EUROPEAN *tag-","en":"The reconstructed root *tag- 'to touch' is generally thought to underlie Latin tangere. It is a reconstruction, not a recorded word.","cn":"原始印欧语重构形式 *tag- 意为「接触」，一般认为它是拉丁 tangere 的来源。它是重构形式，并非有记录的实际词。"},{"era":"LATIN tangere","en":"tangere meant 'to touch'. Its family includes tact, tactile, contact, and tangent, all about touching or reaching a surface.","cn":"tangere 意为「触碰」。其词族包括 tact、tactile、contact、tangent，都与接触或触及表面有关。"},{"era":"LATIN integer","en":"integer is in- 'not' + tangere 'touch': 'not touched, unharmed, whole'. Here in- is a true negative prefix, unlike the locative in- of institution.","cn":"integer 是 in-「不」+ tangere「触碰」：「未被碰过的、未受损伤的、完整的」。这里的 in- 是真正的否定前缀，不同于 institution 中表位置的 in-。"},{"era":"LATIN integrare","en":"integrare 'to make whole, renew, restore' turns the adjective into a verb: to bring something back to its untouched wholeness.","cn":"integrare「使完整、更新、恢复」把形容词变成动词：使某物回到未被破坏的完整状态。"},{"era":"LATIN integratio","en":"integratio named a renewing or making whole; the suffix -tio (English -ation) marks the action or its result.","cn":"integratio 指更新或使完整；后缀 -tio（英语 -ation）标记动作或其结果。"},{"era":"FRENCH AND ENGLISH","en":"French integration and English integration kept the sense of making whole; modern English extended it to society, mathematics, and computer systems.","cn":"法语 integration 与英语 integration 保留了「使完整」义；现代英语把它扩展到社会、数学和计算机系统。"}]},"similar":{"note":{"en":"The first group shares the integer root or the tang- root, but each forms a different part of speech or meaning; the second contains words close in meaning.","cn":"第一组共享 integer 词根或 tang- 词根，但各自构成不同词性或意义；第二组是意义相近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"integrity","ipa":"/ɪnˈteɡrəti/","tag":"same integer root, -ity noun","definition":"the state of being whole and unbroken; -ity names a state, while -ation names a process, and integrity adds a moral sense","definitionCN":"完整、未被破坏的状态；-ity 指状态，-ation 指过程，且 integrity 另有道德义"},{"word":"integral","ipa":"/ˈɪntɪɡrəl/","tag":"same root, -al adjective","definition":"necessary to the whole; as a noun, a mathematical integral. It describes a part's necessity, not the act of joining","definitionCN":"对整体不可或缺的；作名词指积分。它描述部分的必要性，而非接合动作"},{"word":"entire","ipa":"/ɪnˈtaɪə/","tag":"same Latin source, different route","definition":"complete, whole; from Latin integer through French entier, an adjective rather than a process noun","definitionCN":"完整的；由拉丁 integer 经法语 entier 而来，是形容词而非过程名词"},{"word":"contact","ipa":"/kənˈtækt/","tag":"same tang- root, different prefix","definition":"the act of touching; con- 'together' + tangere, literal touch, not the making of a whole","definitionCN":"接触行为；con-「一起」+ tangere，字面触碰，不是使完整"}]},{"heading":"NEAR MEANING","entries":[{"word":"unification","ipa":"/ˌjuːnɪfɪˈkeɪʃn/","tag":"making one","definition":"the act of making separate things one; close to sense 01 but often political or organizational","definitionCN":"使分开事物成为一个的行为；接近第 1 个义项，但常用于政治或组织"},{"word":"incorporation","ipa":"/ˌɪnkɔːpəˈreɪʃn/","tag":"taking into a body","definition":"the act of including something in a larger body; close to senses 01 and 02 but stresses absorption","definitionCN":"把某物纳入更大团体的行为；接近第 1、2 个义项，但强调吸收"},{"word":"assimilation","ipa":"/əˌsɪmɪˈleɪʃn/","tag":"absorbing into a culture","definition":"the process of becoming absorbed into a culture; close to sense 02 but often implies losing difference","definitionCN":"被文化吸收的过程；接近第 2 个义项，但常含失去差异之意"},{"word":"merger","ipa":"/ˈmɜːdʒər/","tag":"joining of bodies","definition":"the joining of two companies or organizations; close to sense 01 but usually legal and corporate","definitionCN":"两家公司或组织的合并；接近第 1 个义项，但通常指法律与公司事务"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'not' + tangere 'touch' gives integer 'untouched, whole'; integrare is 'to make whole', and integration is that making.","cn":"in-「不」+ tangere「触碰」构成 integer「未被碰过的、完整的」；integrare 是「使完整」，integration 就是这一使完整的过程。"},{"en":"integer, entire, contact, and tangent all come from the same tang- root about touching.","cn":"integer、entire、contact、tangent 都来自同一个表示接触的 tang- 词根。"},{"en":"integrate is the verb, integration the noun, integrated the adjective, integral the adjective or the mathematical noun.","cn":"integrate 是动词，integration 是名词，integrated 是形容词，integral 是形容词或数学名词。"},{"en":"integration keeps the family idea: parts that were separate are made one.","cn":"integration 保留家族观念：原本分开的部分被合为一体。"},{"en":"The mathematical sense is literal: infinitely many slices are summed into one whole area.","cn":"数学义是字面延伸：无穷多个切片被加总成一个完整面积。"}],"abstract":[{"en":"Think of scattered machine parts clicked back into one engine: integration is both the clicking and the moment it runs.","cn":"把散落的机器零件想成咔哒装回一台发动机：integration 既是装配动作，也是它开始运转的那一刻。"},{"en":"Think of a torn map taped back together: no piece is new, but the whole is restored.","cn":"把撕破的地图用胶带拼回：没有一块是新的，但整体被恢复。"},{"en":"Think of a society as a body: integration is not melting everyone alike, but making the parts work as one body.","cn":"把社会想象成一个身体：integration 不是把每个人熔成一样，而是让各部分作为一个身体运作。"}]},"examples":[{"en":"The integration of the two teams improved the product's reliability.","cn":"两个团队的整合提高了产品的可靠性。"},{"en":"Integration of the data revealed patterns hidden in separate records.","cn":"数据整合揭示了分散记录中隐藏的模式。"},{"en":"The city's integration policy aimed to end segregated housing.","cn":"该市的融合政策旨在终结住房隔离。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（不）+ teg（触碰）+ -ration：没有被碰坏 → 完整 → integrate 使完整 → integration 整合、一体化","word":"integration"},"root":"拉丁 integrare「使完整」← integer「完整的、未被碰过的」（in-「不」+ tangere「触碰」，词根 tag-「接触」）+ -atio（英语 -ation）；与 integer、entire、contact、tangent 同源。","sensesIntro":{"en":"Nine senses all turn on 'making whole': joining departments, welcoming newcomers, ending segregation, uniting markets, summing slices, linking systems, and restoring a self.","cn":"九个义项都围绕「使完整」：合并部门、接纳新来者、终结隔离、统一市场、加总切片、连接系统，以及修复自我。"},"semanticMap":{"core":{"en":"CORE IMAGE: scattered parts clicked back into one working whole.","cn":"核心意象：散落的零件被重新接合成一个能运转的整体。"},"chain":["NOT TOUCHED","WHOLE AND UNBROKEN","MAKE WHOLE","JOIN THE PARTS","THE WHOLE AT WORK","THE STATE OF UNITY"],"branches":[{"senses":"S01 · S09","en":"MAKING AND BEING WHOLE: the process of joining parts and the resulting state of unity.","cn":"使完整与处于完整：接合部分的过程与由此形成的统一状态。"},{"senses":"S02 · S03","en":"SOCIAL JOINING: newcomers enter a society, and segregated groups are brought together.","cn":"社会接合：新来者进入社会，被隔离的群体被带到一起。"},{"senses":"S04","en":"ECONOMIC JOINING: separate markets become one larger space.","cn":"经济接合：分开的市场成为一个更大空间。"},{"senses":"S05","en":"MATHEMATICAL SUMMING: infinitely many slices are added into one total.","cn":"数学加总：无穷多个切片被加成一个总量。"},{"senses":"S06 · S07 · S08","en":"SYSTEMS AND SELF: technical systems, data, and the parts of a personality are made to work as one.","cn":"系统与自我：技术系统、数据以及人格各部分被整合为一体。"}]},"affixes":{"intro":{"en":"Integration is integrate plus -ation, from Latin -atio. The base integrate is Latin integrare, whose in- is a genuine negative prefix and whose root is tangere 'touch'.","cn":"integration 是 integrate 加 -ation（拉丁 -atio）。词基 integrate 来自拉丁 integrare，其 in- 是真正的否定前缀，词根是 tangere「触碰」。"},"latinIntro":{"en":"Latin tangere 'to touch' gives tact, tactile, contact, tangent, and integer. The root appears as tang-, tact-, or teg-. The reconstructed *tag- is a scholarly form, not an attested word.","cn":"拉丁 tangere「触碰」产生 tact、tactile、contact、tangent、integer。词根以 tang-、tact- 或 teg- 形式出现。重构形式 *tag- 是学术构拟，并非有记录的实际词。"},"items":[{"word":"integrate","structure":"integer + -ate (verb)","meaning":"to make whole; to combine parts; to find an integral","meaningCN":"使完整；整合；求积分（-ate 动词后缀，意义从「使完整」扩展到数学）","example":"The plan integrates the two systems.","exampleCN":"该计划整合了两个系统。"},{"word":"integration","structure":"integrate + -ation (Latin -atio)","meaning":"the process or result of making whole","meaningCN":"整合；一体化（-ation 过程或结果名词）","example":"Integration takes time.","exampleCN":"整合需要时间。"},{"word":"integral","structure":"integer + -al","meaning":"necessary to the whole; a mathematical integral","meaningCN":"不可或缺的；积分（-al 形容词后缀；数学中作名词）","example":"Practice is integral to learning.","exampleCN":"练习对学习不可或缺。"},{"word":"integrity","structure":"integer + -ity (Latin -itas)","meaning":"the state of being whole; moral soundness","meaningCN":"完整；正直（-ity 状态名词，语义从物体完整偏移到品格完整）","example":"The data kept its integrity.","exampleCN":"数据保持完整。"},{"word":"integrated","structure":"integrate + -ed","meaning":"combined into a whole","meaningCN":"整合的；融合的（-ed 分词形容词）","example":"They run an integrated service.","exampleCN":"他们运营一项综合服务。"},{"word":"disintegrate","structure":"dis- (apart) + integrate","meaning":"to break into parts","meaningCN":"瓦解；分裂（dis-「分开」+ integrate，与整合相反）","example":"The old system disintegrated.","exampleCN":"旧系统瓦解了。"},{"word":"reintegrate","structure":"re- (again) + integrate","meaning":"to bring back into a whole","meaningCN":"重新整合；重新融入（re-「再」+ integrate）","example":"The programme helps offenders reintegrate.","exampleCN":"该项目帮助违法者重新融入。"},{"word":"contact","structure":"con- (together) + tangere","meaning":"a touching; communication","meaningCN":"接触；联系（con-「一起」+ tangere，保留字面触碰义）","example":"Keep contact with the team.","exampleCN":"与团队保持联系。"},{"word":"tangent","structure":"tangere + -ent","meaning":"a line that touches a curve at one point","meaningCN":"切线（-ent 形容词/名词后缀，字面为「触碰的」）","example":"Draw a tangent to the circle.","exampleCN":"画一条圆的切线。"}],"latinEntries":[{"word":"tangere","structure":"tangere (to touch)","meaning":"to touch","meaningCN":"触碰"},{"word":"integer","structure":"in- (not) + tangere","meaning":"untouched, whole","meaningCN":"未被碰过的；完整的"},{"word":"integrare","structure":"integer + -are","meaning":"to make whole, restore","meaningCN":"使完整；恢复"},{"word":"integratio","structure":"integrare + -tio","meaning":"a making whole, renewal","meaningCN":"使完整；更新"}]}},{"word":"integrity","ipa_uk":"/ɪnˈteɡrəti/","ipa_us":"/ɪnˈteɡrəti/","definition_zh":"完整；正直；诚信；操守；完整性","definition_en":"the state of being whole and unbroken; the quality of being honest and having strong moral principles; the soundness of data, structures, or records","core_image":"一只没有裂缝的瓷瓶：既没有缺口，也没有被偷偷换过的釉","scene":"She refused the offer, and her integrity impressed even her opponents.","sceneCN":"这里 integrity 是「正直」（第 2 个义项：诚实且坚守道德原则的品质）；句意：她拒绝了那笔钱，她的正直甚至打动了对手。图中可辨识物件：拒签的手、信封、对方点头的神情。","pos":[{"tag":"n.","zh":"完整；正直；诚信；完整性"}],"collocations":[{"phrase":"structural integrity","zh":"结构完整性"},{"phrase":"personal integrity","zh":"个人正直"},{"phrase":"professional integrity","zh":"职业操守"},{"phrase":"territorial integrity","zh":"领土完整"},{"phrase":"data integrity","zh":"数据完整性"},{"phrase":"a person of integrity","zh":"正直的人"}],"forms":[{"label":"复数（罕用；通常不可数）","form":"integrities"}],"derivatives":[{"word":"integrate","pos":"v.","zh":"整合；使完整"},{"word":"integral","pos":"adj./n.","zh":"不可或缺的；积分"},{"word":"integration","pos":"n.","zh":"整合；一体化"},{"word":"integrated","pos":"adj.","zh":"综合的；融合的"},{"word":"disintegrate","pos":"v.","zh":"瓦解；分裂"}],"senses":[{"no":"01","title":"Wholeness; the state of being complete","titleCN":"完整；完好","definition":"the state of being whole and undivided, with no part missing","definitionCN":"完整且未被分割、没有缺失部分的状态","example":"The manuscript survived in its integrity despite the fire.","exampleCN":"尽管经历火灾，这份手稿仍完整保存。","why":"Latin integritas comes from integer 'untouched, whole', built from in- 'not' + tangere 'to touch'. What has not been touched remains whole.","whyCN":"拉丁 integritas 来自 integer「未被碰过的、完整的」，由 in-「不」+ tangere「触碰」构成。未被碰过的东西保持完整。"},{"no":"02","title":"Honesty and moral firmness","titleCN":"正直；诚实","definition":"the quality of being honest and firm in one's moral principles","definitionCN":"诚实且坚守道德原则的品质","example":"No one doubted the judge's personal integrity.","exampleCN":"没有人怀疑这位法官的个人正直。","why":"A person of integrity is morally unbroken: no part has been chipped away by lies or bribes, so the whole self holds together.","whyCN":"正直的人在道德上未被破坏：没有哪一部分被谎言或贿赂敲掉，因此整个自我保持完整。"},{"no":"03","title":"Professional probity","titleCN":"职业操守；诚信","definition":"the quality of behaving honestly and ethically in a profession","definitionCN":"在职业中诚实且合乎伦理地行事的品质","example":"The code demands integrity in handling client funds.","exampleCN":"该准则要求在处理客户资金时保持职业操守。","why":"The metaphor moves from an unbroken object to an uncorrupted role: the professional's duty is kept whole.","whyCN":"隐喻从未被破坏的物体转到未被腐蚀的角色：专业人士的职责被保持完整。"},{"no":"04","title":"Soundness of data or records","titleCN":"数据完整性","definition":"the condition in which data is accurate, complete, and unaltered","definitionCN":"数据准确、完整且未被篡改的状态","example":"Checksums are used to verify the integrity of the file.","exampleCN":"校验和用于核实文件的完整性。","why":"Digital data is whole when no bit has been silently changed; integrity names that untouched state.","whyCN":"当没有任何一位被悄悄改动时，数字数据就是完整的；integrity 指这种未被触碰的状态。"},{"no":"05","title":"Structural soundness","titleCN":"结构完整性","definition":"the ability of a structure to hold together without weakening or collapse","definitionCN":"结构保持整体、不弱化或不倒塌的能力","example":"Engineers inspected the dam for signs of lost integrity.","exampleCN":"工程师检查大坝是否有失去完整性的迹象。","why":"A structure has integrity when all its parts still act as one body, with no crack allowed to divide it.","whyCN":"当所有部分仍作为一个整体起作用、没有裂缝将其分开时，结构就具有完整性。"},{"no":"06","title":"Artistic wholeness","titleCN":"（作品的）完整性","definition":"the quality of a work of art that remains true to its own vision and is not compromised","definitionCN":"艺术作品忠于自身构想且未被妥协的品质","example":"The director fought to preserve the film's artistic integrity.","exampleCN":"导演力争保全这部影片的艺术完整性。","why":"An artist's work is whole when nothing foreign is inserted for profit; the moral and structural senses meet.","whyCN":"当没有为利益插入异物时，艺术家的作品就是完整的；道德义与结构义在此交汇。"},{"no":"07","title":"Territorial wholeness","titleCN":"领土完整","definition":"the principle that a state's territory must not be divided or violated","definitionCN":"国家领土不得被分割或侵犯的原则","example":"The charter protects the territorial integrity of member states.","exampleCN":"该宪章保护成员国的领土完整。","why":"A country is pictured as a body whose borders must remain unbroken; any seizure is a wound to its integrity.","whyCN":"国家被想象成一个边界必须保持完整的身体；任何夺取都是对其完整性的创伤。"},{"no":"08","title":"Coherence of the self","titleCN":"人格的完整统一","definition":"in psychology, the condition of a self whose parts are not split off from one another","definitionCN":"心理学中，自我的各部分未彼此割裂的状态","example":"Sleep loss undermined his sense of integrity.","exampleCN":"睡眠不足损害了他的自我完整感。","why":"The psyche is treated as a whole that can fragment; integrity is the state in which its parts remain joined.","whyCN":"心灵被当作一个可能碎裂的整体；integrity 是其各部分保持连接的状态。"},{"no":"09","title":"Freedom from corruption in public life","titleCN":"廉洁；公正","definition":"the quality of public conduct that is uncorrupted by private gain","definitionCN":"公共行为不被私人利益腐蚀的品质","example":"Voters questioned the integrity of the procurement process.","exampleCN":"选民质疑采购程序的公正性。","why":"Public trust depends on a process no one has quietly altered; integrity is the guarantee that it remains untouched.","whyCN":"公共信任取决于一个无人悄悄改动的程序；integrity 是它未被触碰的保证。"}],"etymology":{"intro":{"en":"Integrity comes from Latin integritas, from integer 'untouched, whole'. It shares the root tangere 'touch' with integration, but names a state rather than a process, and has shifted from physical wholeness to moral soundness.","cn":"integrity 来自拉丁 integritas，源自 integer「未被碰过的、完整的」。它与 integration 共享 tangere「触碰」词根，但指状态而非过程，并从物理完整偏移到道德操守。"},"items":[{"era":"PROTO-INDO-EUROPEAN *tag-","en":"The reconstructed root *tag- 'to touch' is generally thought to underlie Latin tangere. The star marks a reconstruction, not an attested word.","cn":"原始印欧语重构形式 *tag- 意为「接触」，一般认为它是拉丁 tangere 的来源。星号表示重构，并非有记录的实际词。"},{"era":"LATIN tangere","en":"tangere 'to touch' also gives contact, tangent, and tactile; the family is about contact with a surface.","cn":"tangere「触碰」还产生 contact、tangent、tactile；这个词族都与接触表面有关。"},{"era":"LATIN integer","en":"integer is in- 'not' + tangere 'touch': 'not touched, unharmed, whole'. The in- here is a real negative prefix.","cn":"integer 是 in-「不」+ tangere「触碰」：「未被碰过的、未受损伤的、完整的」。这里的 in- 是真正的否定前缀。"},{"era":"LATIN integritas","en":"integritas 'wholeness, soundness' added -itas to integer. It named the state of being untouched and complete.","cn":"integritas「完整、健全」由 integer 加 -itas 构成，指未被触碰且完整的状态。"},{"era":"FRENCH AND ENGLISH -ity","en":"Latin -itas became French -ité and English -ity. English integrity kept both the physical sense of wholeness and the moral sense of soundness.","cn":"拉丁 -itas 变为法语 -ité 和英语 -ity。英语 integrity 同时保留物理完整义与道德健全义。"},{"era":"MORAL SHIFT","en":"From the 16th century the word was increasingly applied to character: a person of integrity is one whose moral self has no cracks.","cn":"自 16 世纪起，该词越来越多用于品格：一个 integrity 的人，其道德自我没有裂缝。"}]},"similar":{"note":{"en":"The first group shares the integer root or a near shape but differs in formation and sense; the second contains words close in meaning.","cn":"第一组共享 integer 词根或外形相近，但构词与意义不同；第二组是意义相近的词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"integration","ipa":"/ˌɪntɪˈɡreɪʃn/","tag":"same root, -ation noun","definition":"the process of making whole; -ation names the act, while integrity names the state, and integration has no moral sense","definitionCN":"使完整的过程；-ation 指动作，integrity 指状态，且 integration 没有道德义"},{"word":"integral","ipa":"/ˈɪntɪɡrəl/","tag":"same root, -al adjective","definition":"necessary to the whole; as a noun, a mathematical integral; it does not mean honesty","definitionCN":"对整体不可或缺的；作名词指积分；不含诚实义"},{"word":"entirety","ipa":"/ɪnˈtaɪərəti/","tag":"from entire, same Latin source","definition":"the whole of something; from entire + -ty, naming a total, not a moral quality","definitionCN":"某物的全部；由 entire + -ty 构成，指总体，不是道德品质"},{"word":"integer","ipa":"/ˈɪntɪdʒər/","tag":"the Latin source word","definition":"a whole number; the adjective integer 'whole' lies behind integrity but is not the noun itself","definitionCN":"整数；形容词 integer「完整的」是 integrity 的来源，但并非该名词本身"}]},{"heading":"NEAR MEANING","entries":[{"word":"honesty","ipa":"/ˈɒnəsti/","tag":"truthfulness","definition":"the quality of being truthful; narrower than integrity, which also includes wholeness and firm principles","definitionCN":"诚实的品质；比 integrity 窄，后者还包括完整与原则坚定"},{"word":"wholeness","ipa":"/ˈhəʊlnəs/","tag":"completeness","definition":"the state of being complete; close to sense 01 but without the moral extension","definitionCN":"完整的状态；接近第 1 个义项，但没有道德延伸"},{"word":"soundness","ipa":"/ˈsaʊndnəs/","tag":"structural health","definition":"the condition of being structurally healthy; close to senses 04 and 05","definitionCN":"结构健全的状态；接近第 4、5 个义项"},{"word":"probity","ipa":"/ˈprɒbəti/","tag":"moral uprightness","definition":"strict moral uprightness, especially in public life; close to sense 03 and more formal than integrity","definitionCN":"严格的道义正直，尤指公共生活；接近第 3 个义项，比 integrity 更正式"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes and real word relatives.","cn":"正常联想：真实的构词成分和真实同族词。"},"normal":[{"en":"in- 'not' + tangere 'touch' gives integer 'untouched'; integritas is the state of being untouched and whole.","cn":"in-「不」+ tangere「触碰」构成 integer「未被碰过的」；integritas 是未被触碰且完整的状态。"},{"en":"Integrity and integration share the same root, but -ity names a state while -ation names a process.","cn":"integrity 与 integration 同根，但 -ity 指状态，-ation 指过程。"},{"en":"A person of integrity has no moral cracks: the same picture as an unbroken vase.","cn":"有 integrity 的人没有道德裂缝：与一只完好的花瓶是同一画面。"},{"en":"Data integrity means no bit has been silently changed; structural integrity means no crack has divided the whole.","cn":"数据完整性指没有一位被悄悄改动；结构完整性指没有裂缝把整体分开。"},{"en":"The moral sense grew from the physical one: untouched -> uncorrupted -> honest.","cn":"道德义从物理义生长而来：未被碰过 → 未被腐蚀 → 诚实。"}],"abstract":[{"en":"Think of a vase with no crack and no swapped glaze: integrity is both the shape and the fact that nothing was quietly replaced.","cn":"把 integrity 想象成一只没有裂缝、也没有被偷换釉面的花瓶：既是形状完整，也是没有东西被悄悄替换。"},{"en":"Think of a bridge whose every cable still pulls as one: that is structural integrity, and the same image explains moral integrity.","cn":"把 integrity 想象成一座每根缆索仍整体受力的桥：那是结构完整性，同一画面也解释道德正直。"},{"en":"Think of a public ledger with no erased line: integrity is the page that no one has quietly altered.","cn":"把 integrity 想象成一本没有擦改痕迹的公共账本：它是无人悄悄改动的那一页。"}]},"examples":[{"en":"The engineers certified the structural integrity of the tower.","cn":"工程师认证了这座塔的结构完整性。"},{"en":"She is widely respected for her personal and professional integrity.","cn":"她因个人正直与职业操守广受尊敬。"},{"en":"Encryption helps protect the integrity of transmitted records.","cn":"加密有助于保护传输记录的完整性。"}],"dict_mnemonic":{"note":"拆词联想 · 词源辅助","text":"in-（不）+ tegr（触碰）+ -ity（状态）：没有被碰坏的状态 → 完整 → 引申为「正直」","word":"integrity"},"root":"拉丁 integritas「完整、无缺损」← integer「完整的、未被碰过的」（in-「不」+ tangere「触碰」，词根 tag-「接触」）+ -itas（英语 -ity）；与 integration、integral、integrate 同源：integral 与 integrate 强调「使合为一体」，integrity 强调未被破坏的整全，并引申出「正直」义。","sensesIntro":{"en":"Nine senses grow from 'untouched and whole': an intact manuscript, an honest character, sound data, a strong bridge, a country's borders, an unbroken self.","cn":"九个义项从「未被碰过且完整」生长而来：完好的手稿、诚实的品格、健全的数据、坚固的桥、国家的边界、未碎裂的自我。"},"semanticMap":{"core":{"en":"CORE IMAGE: a whole vessel with no crack and nothing quietly replaced.","cn":"核心意象：一只没有裂缝、也没有东西被悄悄替换的完整器皿。"},"chain":["NOT TOUCHED","WHOLE AND SOUND","STRUCTURAL SOUNDNESS","DATA UNALTERED","MORAL UNCORRUPTED","PUBLIC TRUST"],"branches":[{"senses":"S01","en":"PHYSICAL WHOLENESS: nothing missing, nothing divided.","cn":"物理完整：没有缺失，也没有被分割。"},{"senses":"S02 · S03 · S09","en":"MORAL WHOLENESS: personal honesty, professional probity, and uncorrupted public conduct.","cn":"道德完整：个人诚实、职业操守与未被腐蚀的公共行为。"},{"senses":"S04 · S05","en":"TECHNICAL AND STRUCTURAL SOUNDNESS: data unchanged, structures holding together.","cn":"技术与结构健全：数据未被改动，结构保持整体。"},{"senses":"S06","en":"ARTISTIC WHOLENESS: a work true to its own vision.","cn":"艺术完整：作品忠于自身构想。"},{"senses":"S07 · S08","en":"BOUNDED WHOLENESS: a country's borders and a coherent self.","cn":"有边界的完整：国家边界与连贯统一的自我。"}]},"affixes":{"intro":{"en":"Integrity is integer plus -ity, from Latin -itas. The in- is a real negative prefix, and the root tangere 'touch' is fossilized inside the base.","cn":"integrity 是 integer 加 -ity（拉丁 -itas）。in- 是真正的否定前缀，词根 tangere「触碰」凝固在词基中。"},"latinIntro":{"en":"Latin tangere 'to touch' also gives contact, tangent, tactile, and integer. The root appears as tang-, tact-, or teg-; *tag- is a reconstruction, not a recorded form.","cn":"拉丁 tangere「触碰」还产生 contact、tangent、tactile、integer。词根以 tang-、tact- 或 teg- 形式出现；*tag- 是重构形式，并非有记录的实际词。"},"items":[{"word":"integer","structure":"in- (not) + tangere","meaning":"a whole number; literally 'untouched, whole'","meaningCN":"整数；字面为「未被碰过的、完整的」（in- 否定 + tangere）","example":"Five is an integer.","exampleCN":"五是一个整数。"},{"word":"integral","structure":"integer + -al","meaning":"necessary to the whole; a mathematical integral","meaningCN":"不可或缺的；积分（-al 形容词后缀）","example":"Trust is integral to the team.","exampleCN":"信任对团队不可或缺。"},{"word":"integrate","structure":"integer + -ate","meaning":"to make whole; to combine","meaningCN":"使完整；整合（-ate 动词后缀）","example":"The design integrates old and new.","exampleCN":"设计整合了新旧元素。"},{"word":"integration","structure":"integrate + -ation","meaning":"the process of making whole","meaningCN":"整合；一体化（-ation 过程名词）","example":"Integration followed the merger.","exampleCN":"合并之后进行了整合。"},{"word":"integrity","structure":"integer + -ity (Latin -itas)","meaning":"the state of being whole; moral soundness","meaningCN":"完整；正直（-ity 状态名词，由物理完整偏移到道德完整）","example":"The seal guarantees the product's integrity.","exampleCN":"密封保证产品的完整性。"},{"word":"integrated","structure":"integrate + -ed","meaning":"combined into one whole","meaningCN":"整合的；综合的（-ed 分词形容词）","example":"They use an integrated approach.","exampleCN":"他们采用综合方法。"},{"word":"disintegrate","structure":"dis- (apart) + integrate","meaning":"to break apart","meaningCN":"瓦解；分裂（dis-「分开」+ integrate）","example":"The comet disintegrated in the atmosphere.","exampleCN":"彗星在大气中解体。"},{"word":"contact","structure":"con- (together) + tangere","meaning":"a touching; communication","meaningCN":"接触；联系（con-「一起」+ tangere）","example":"Avoid contact with the chemical.","exampleCN":"避免接触该化学品。"},{"word":"entire","structure":"in- (not) + tangere via French entier","meaning":"complete, whole","meaningCN":"完整的；全部的（经法语 entier 来自 integer）","example":"The entire class attended.","exampleCN":"全班都出席了。"}],"latinEntries":[{"word":"tangere","structure":"tangere (to touch)","meaning":"to touch","meaningCN":"触碰"},{"word":"integer","structure":"in- (not) + tangere","meaning":"untouched, whole","meaningCN":"未被碰过的；完整的"},{"word":"integritas","structure":"integer + -itas","meaning":"wholeness, soundness","meaningCN":"完整；健全"},{"word":"integrare","structure":"integer + -are","meaning":"to make whole","meaningCN":"使完整；恢复"}]}}]);
